// Importando os módulos necessários
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');

// Criando a aplicação Express
const app = express();
const port = process.env.PORT || 3000;

// Configurando middleware
app.use(cors());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// Armazenamento temporário de dados (em produção, use um banco de dados)
let items = [
  { id: 1, name: 'Item 1', description: 'Descrição do Item 1' },
  { id: 2, name: 'Item 2', description: 'Descrição do Item 2' },
  { id: 3, name: 'Item 3', description: 'Descrição do Item 3' }
];

// Rota de boas-vindas
app.get('/', (req, res) => {
  res.json({ message: 'Bem-vindo à API de exemplo para o Aider!' });
});

// Obter todos os itens
app.get('/api/items', (req, res) => {
  res.json(items);
});

// Obter um item específico por ID
app.get('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const item = items.find(item => item.id === id);

  if (!item) {
    return res.status(404).json({ message: 'Item não encontrado' });
  }

  res.json(item);
});

// Criar um novo item
app.post('/api/items', (req, res) => {
  const { name, description } = req.body;

  if (!name || !description) {
    return res.status(400).json({ message: 'Nome e descrição são obrigatórios' });
  }

  const newId = items.length > 0 ? Math.max(...items.map(item => item.id)) + 1 : 1;

  const newItem = {
    id: newId,
    name,
    description
  };

  items.push(newItem);
  res.status(201).json(newItem);
});

// Atualizar um item existente
app.put('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const { name, description } = req.body;
  const itemIndex = items.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ message: 'Item não encontrado' });
  }

  if (!name || !description) {
    return res.status(400).json({ message: 'Nome e descrição são obrigatórios' });
  }

  items[itemIndex] = {
    id,
    name,
    description
  };

  res.json(items[itemIndex]);
});

// Excluir um item
app.delete('/api/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const itemIndex = items.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ message: 'Item não encontrado' });
  }

  const deletedItem = items[itemIndex];
  items = items.filter(item => item.id !== id);

  res.json(deletedItem);
});

// Iniciar o servidor
app.listen(port, () => {
  console.log(`Servidor rodando na porta ${port}`);
});

module.exports = app; // Para testes ou importação por outros módulos

