#!/usr/bin/env python3
import requests
import json
import sys
import os

def load_api_key(key_file="api_key.json"):
    """Carrega a chave API do arquivo JSON."""
    try:
        if not os.path.exists(key_file):
            print(f"❌ Arquivo de chave não encontrado: {key_file}")
            return None

        with open(key_file, 'r') as f:
            key_data = json.load(f)

        if "api_key" not in key_data:
            print("❌ Formato de chave inválido: chave 'api_key' não encontrada")
            return None

        return key_data["api_key"]

    except Exception as e:
        print(f"❌ Erro ao carregar chave: {str(e)}")
        return None

def make_api_request(api_key, endpoint="http://localhost:3000/api/items", method="GET", data=None):
    """Faz uma requisição à API usando a chave de autenticação."""
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    try:
        if method.upper() == "GET":
            response = requests.get(endpoint, headers=headers)
        elif method.upper() == "POST":
            response = requests.post(endpoint, headers=headers, json=data)
        elif method.upper() == "PUT":
            response = requests.put(endpoint, headers=headers, json=data)
        elif method.upper() == "DELETE":
            response = requests.delete(endpoint, headers=headers)
        else:
            print(f"❌ Método HTTP não suportado: {method}")
            return None

        # Verifica se a requisição foi bem-sucedida
        response.raise_for_status()

        # Retorna os dados em formato JSON
        return response.json()

    except requests.exceptions.RequestException as e:
        print(f"❌ Erro na requisição: {str(e)}")
        if hasattr(e, 'response') and e.response is not None:
            try:
                print(f"Detalhes: {e.response.json()}")
            except:
                print(f"Status: {e.response.status_code}")
        return None

def main():
    # Carrega a chave API
    api_key = load_api_key()
    if not api_key:
        print("Por favor, gere uma chave API primeiro usando o script gerador.")
        sys.exit(1)

    print(f"🔑 Usando chave API: {api_key[:10]}...{api_key[-5:]}")

    # Exemplos de uso da API
    print("\n1. Obtendo todos os itens:")
    items = make_api_request(api_key)
    if items:
        print(json.dumps(items, indent=2))

    print("\n2. Criando um novo item:")
    new_item = {
        "name": "Item via Python",
        "description": "Este item foi criado usando o script Python"
    }
    created = make_api_request(api_key, method="POST", data=new_item)
    if created:
        print(json.dumps(created, indent=2))

        # Pega o ID do item criado
        item_id = created.get("id")

        print(f"\n3. Obtendo o item {item_id}:")
        item = make_api_request(api_key, endpoint=f"http://localhost:3000/api/items/{item_id}")
        if item:
            print(json.dumps(item, indent=2))

        print(f"\n4. Atualizando o item {item_id}:")
        updated_item = {
            "name": "Item Atualizado",
            "description": "Este item foi atualizado pelo script Python"
        }
        updated = make_api_request(
            api_key, 
            endpoint=f"http://localhost:3000/api/items/{item_id}", 
            method="PUT", 
            data=updated_item
        )
        if updated:
            print(json.dumps(updated, indent=2))

        print(f"\n5. Deletando o item {item_id}:")
        deleted = make_api_request(
            api_key, 
            endpoint=f"http://localhost:3000/api/items/{item_id}", 
            method="DELETE"
        )
        if deleted:
            print(json.dumps(deleted, indent=2))

    print("\n✅ Demonstração concluída!")

if __name__ == "__main__":
    main()

