// ChatGPT Socket Bridge - Content Script
class ChatGPTBridge {
  constructor() {
    this.ws = null;
    this.config = {
      socketUrl: 'ws://localhost:8080',
      autoConnect: true
    };
    this.init();
  }

  async init() {
    // Carrega configurações
    const stored = await chrome.storage.sync.get(['socketUrl', 'autoConnect']);
    this.config = { ...this.config, ...stored };

    if (this.config.autoConnect) {
      this.connectSocket();
    }

    this.setupChatObserver();
    this.setupInputHandler();
    this.addUI();
  }

  connectSocket() {
    try {
      this.ws = new WebSocket(this.config.socketUrl);

      this.ws.onopen = () => {
        console.log('ChatGPT Bridge: Conectado ao socket');
        this.updateStatus('Conectado', 'green');
      };

      this.ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          this.handleSocketMessage(data);
        } catch (e) {
          // Trata como texto simples
          this.insertTextInInput(event.data);
        }
      };

      this.ws.onclose = () => {
        console.log('ChatGPT Bridge: Desconectado do socket');
        this.updateStatus('Desconectado', 'red');
        // Reconecta em 5s
        setTimeout(() => this.connectSocket(), 5000);
      };

      this.ws.onerror = (error) => {
        console.error('ChatGPT Bridge: Erro no socket:', error);
        this.updateStatus('Erro', 'orange');
      };
    } catch (error) {
      console.error('ChatGPT Bridge: Erro ao conectar:', error);
      this.updateStatus('Erro', 'red');
    }
  }

  setupChatObserver() {
    // Observer para capturar novas mensagens do ChatGPT
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType === Node.ELEMENT_NODE) {
            // Procura por mensagens do assistente
            const assistantMsgs = node.querySelectorAll('[data-message-author-role="assistant"]');
            assistantMsgs.forEach((msg) => {
              this.processAssistantMessage(msg);
            });
          }
        });
      });
    });

    // Observa mudanças no chat
    const chatContainer = document.querySelector('[role="main"]') || document.body;
    observer.observe(chatContainer, {
      childList: true,
      subtree: true
    });
  }

  processAssistantMessage(messageElement) {
    // Evita processar a mesma mensagem múltiplas vezes
    if (messageElement.hasAttribute('data-bridge-processed')) return;
    messageElement.setAttribute('data-bridge-processed', 'true');

    // Extrai o texto da mensagem
    const textContent = this.extractMessageText(messageElement);

    if (textContent && this.ws && this.ws.readyState === WebSocket.OPEN) {
      const payload = {
        type: 'chatgpt_response',
        content: textContent,
        timestamp: Date.now(),
        url: window.location.href
      };

      this.ws.send(JSON.stringify(payload));
      console.log('ChatGPT Bridge: Mensagem enviada via socket');
    }
  }

  extractMessageText(element) {
    // Remove elementos de código e outros que não queremos
    const clone = element.cloneNode(true);

    // Remove botões, ícones, etc.
    const unwanted = clone.querySelectorAll('button, svg, .sr-only');
    unwanted.forEach(el => el.remove());

    // Pega apenas o texto da resposta
    const contentDiv = clone.querySelector('[data-message-content]') || clone;
    return contentDiv.textContent?.trim() || '';
  }

  handleSocketMessage(data) {
    switch (data.type) {
      case 'insert_text':
        this.insertTextInInput(data.content);
        break;
      case 'send_message':
        this.insertTextInInput(data.content);
        this.submitMessage();
        break;
      case 'config_update':
        this.updateConfig(data.config);
        break;
      default:
        console.log('ChatGPT Bridge: Mensagem desconhecida:', data);
    }
  }

  insertTextInInput(text) {
    // Procura pelo campo de input do ChatGPT
    const input = document.querySelector('textarea[placeholder*="Message"]') || 
                  document.querySelector('#prompt-textarea') ||
                  document.querySelector('textarea');

    if (input) {
      // Define o valor
      input.value = text;
      input.textContent = text;

      // Dispara eventos para o ChatGPT reconhecer a mudança
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));

      // Foca no input
      input.focus();

      console.log('ChatGPT Bridge: Texto inserido no input');
    } else {
      console.error('ChatGPT Bridge: Campo de input não encontrado');
    }
  }

  submitMessage() {
    // Procura pelo botão de enviar
    const sendBtn = document.querySelector('button[data-testid="send-button"]') ||
                   document.querySelector('button[aria-label*="Send"]') ||
                   document.querySelector('[data-testid="send-button"]');

    if (sendBtn && !sendBtn.disabled) {
      sendBtn.click();
      console.log('ChatGPT Bridge: Mensagem enviada');
    }
  }

  setupInputHandler() {
    // Monitora quando o usuário digita (opcional - para capturar prompts)
    document.addEventListener('keydown', (e) => {
      if (e.ctrlKey && e.key === 'Enter') {
        const input = document.querySelector('textarea');
        if (input && input.value.trim()) {
          // Envia o prompt via socket (opcional)
          if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            const payload = {
              type: 'user_prompt',
              content: input.value.trim(),
              timestamp: Date.now()
            };
            this.ws.send(JSON.stringify(payload));
          }
        }
      }
    });
  }

  addUI() {
    // Adiciona indicador visual de status
    const statusDiv = document.createElement('div');
    statusDiv.id = 'chatgpt-bridge-status';
    statusDiv.style.cssText = `
      position: fixed;
      top: 10px;
      right: 10px;
      z-index: 10000;
      background: rgba(0,0,0,0.8);
      color: white;
      padding: 5px 10px;
      border-radius: 5px;
      font-size: 12px;
      font-family: monospace;
    `;
    statusDiv.textContent = 'Bridge: Iniciando...';
    document.body.appendChild(statusDiv);
  }

  updateStatus(status, color) {
    const statusDiv = document.getElementById('chatgpt-bridge-status');
    if (statusDiv) {
      statusDiv.textContent = `Bridge: ${status}`;
      statusDiv.style.background = color === 'green' ? 'rgba(0,150,0,0.8)' :
                                  color === 'red' ? 'rgba(150,0,0,0.8)' :
                                  color === 'orange' ? 'rgba(150,75,0,0.8)' :
                                  'rgba(0,0,0,0.8)';
    }
  }

  updateConfig(newConfig) {
    this.config = { ...this.config, ...newConfig };
    chrome.storage.sync.set(this.config);
  }

  disconnect() {
    if (this.ws) {
      this.ws.close();
    }
  }
}

// Inicia o bridge quando a página carrega
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    window.chatGPTBridge = new ChatGPTBridge();
  });
} else {
  window.chatGPTBridge = new ChatGPTBridge();
