// ChatGPT Socket Bridge - Popup Script
document.addEventListener('DOMContentLoaded', async () => {
    const elements = {
        socketUrl: document.getElementById('socketUrl'),
        autoConnect: document.getElementById('autoConnect'),
        connectBtn: document.getElementById('connectBtn'),
        disconnectBtn: document.getElementById('disconnectBtn'),
        saveConfig: document.getElementById('saveConfig'),
        status: document.getElementById('status'),
        testMessage: document.getElementById('testMessage'),
        sendTest: document.getElementById('sendTest'),
        sendAndSubmit: document.getElementById('sendAndSubmit')
    };

    // Carrega configurações salvas
    const config = await chrome.storage.sync.get({
        socketUrl: 'ws://localhost:8080',
        autoConnect: true
    });

    elements.socketUrl.value = config.socketUrl;
    elements.autoConnect.checked = config.autoConnect;

    // Verifica status da conexão
    updateConnectionStatus();

    // Event Listeners
    elements.connectBtn.addEventListener('click', () => {
        sendMessageToContentScript({ action: 'connect' });
    });

    elements.disconnectBtn.addEventListener('click', () => {
        sendMessageToContentScript({ action: 'disconnect' });
    });

    elements.saveConfig.addEventListener('click', async () => {
        const newConfig = {
            socketUrl: elements.socketUrl.value,
            autoConnect: elements.autoConnect.checked
        };

        await chrome.storage.sync.set(newConfig);

        // Envia nova configuração para o content script
        sendMessageToContentScript({ 
            action: 'updateConfig', 
            config: newConfig 
        });

        // Feedback visual
        const originalText = elements.saveConfig.textContent;
        elements.saveConfig.textContent = 'Salvo!';
        elements.saveConfig.style.background = '#28a745';

        setTimeout(() => {
            elements.saveConfig.textContent = originalText;
            elements.saveConfig.style.background = '#007cba';
        }, 2000);
    });

    elements.sendTest.addEventListener('click', () => {
        const message = elements.testMessage.value.trim();
        if (message) {
            sendMessageToContentScript({
                action: 'insertText',
                text: message
            });
        }
    });

    elements.sendAndSubmit.addEventListener('click', () => {
        const message = elements.testMessage.value.trim();
        if (message) {
            sendMessageToContentScript({
                action: 'sendMessage',
                text: message
            });
        }
    });

    // Atualiza status a cada 2 segundos
    setInterval(updateConnectionStatus, 2000);

    async function sendMessageToContentScript(message) {
        try {
            const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });

            if (tab && (tab.url.includes('chat.openai.com') || tab.url.includes('chatgpt.com'))) {
                chrome.tabs.sendMessage(tab.id, message);
            } else {
                updateStatus('Erro: Não está no ChatGPT', 'disconnected');
            }
        } catch (error) {
            console.error('Erro ao enviar mensagem:', error);
            updateStatus('Erro de comunicação', 'disconnected');
        }
    }

    async function updateConnectionStatus() {
        try {
            const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });

            if (!tab || (!tab.url.includes('chat.openai.com') && !tab.url.includes('chatgpt.com'))) {
                updateStatus('Abra o ChatGPT', 'disconnected');
                return;
            }

            // Verifica se o content script está ativo
            chrome.tabs.sendMessage(tab.id, { action: 'getStatus' }, (response) => {
                if (chrome.runtime.lastError) {
                    updateStatus('Script não carregado', 'disconnected');
                } else if (response) {
                    updateStatus(response.status, response.connected ? 'connected' : 'disconnected');
                } else {
                    updateStatus('Verificando...', 'connecting');
                }
            });
        } catch (error) {
            updateStatus('Erro ao verificar status', 'disconnected');
        }
    }

    function updateStatus(message, type) {
        elements.status.textContent = message;
        elements.status.className = `status ${type}`;

        // Atualiza estado dos botões
        if (type === 'connected') {
            elements.connectBtn.disabled = true;
            elements.disconnectBtn.disabled = false;
        } else {
            elements.connectBtn.disabled = false;
            elements.disconnectBtn.disabled = false;
        }
    }
});

// Escuta mensagens do content script
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message.type === 'status_update') {
        const statusElement = document.getElementById('status');
        if (statusElement) {
            statusElement.textContent = message.status;
            statusElement.className = `status ${message.connected ? 'connected' : 'disconnected'}`;
        }
    }
});

// ChatGPT Socket Bridge - Background Service Worker

// Escuta quando a extensão é instalada
chrome.runtime.onInstalled.addListener(() => {
    console.log('ChatGPT Socket Bridge instalado');

    // Define configurações padrão
    chrome.storage.sync.set({
        socketUrl: 'ws://localhost:8080',
        autoConnect: true
    });
});

// Escuta mensagens dos content scripts e popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    switch (message.action) {
        case 'log':
            console.log('ChatGPT Bridge:', message.data);
            break;

        case 'notification':
            showNotification(message.title, message.message);
            break;

        case 'getConfig':
            chrome.storage.sync.get(['socketUrl', 'autoConnect'], (config) => {
                sendResponse(config);
            });
            return true; // Mantém o canal aberto para resposta assíncrona

        default:
            console.log('Mensagem não reconhecida:', message);
    }
});

// Escuta mudanças nas abas para reiniciar conexões se necessário
chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
    if (changeInfo.status === 'complete' && 
        (tab.url?.includes('chat.openai.com') || tab.url?.includes('chatgpt.com'))) {

        // Espera um pouco para a página carregar completamente
        setTimeout(() => {
            chrome.tabs.sendMessage(tabId, { action: 'checkConnection' }, (response) => {
                if (chrome.runtime.lastError) {
                    // Content script ainda não carregou, normal
                }
            });
        }, 2000);
    }
});

// Função para mostrar notificações
function showNotification(title, message) {
    if (chrome.notifications) {
        chrome.notifications.create({
            type: 'basic',
            iconUrl: 'icon.png', // Você pode adicionar um ícone
            title: title,
            message: message
        });
    }
}

// Mantém o service worker ativo
chrome.runtime.onConnect.addListener((port) => {
    console.log('Conexão estabelecida:', port.name);
});

// Cleanup quando a extensão é desabilitada
chrome.runtime.onSuspend.addListener(() => {
    console.log('ChatGPT Socket Bridge sendo suspensa');
});

