        this.clients = new Set();
        this.setupServer();
        this.setupCLI();
    }

    setupServer() {
        this.wss = new WebSocket.Server({ port: this.port });

        this.wss.on('connection', (ws, req) => {
            console.log(`\n🔗 Nova conexão do Chrome: ${req.connection.remoteAddress}`);
            this.clients.add(ws);

            // Envia confirmação de conexão
