            return {
                "status": "success",
                "query": query,
                "filters": filters,
                "response_code": response.status_code,
                "results": response.json()
            }
        except Exception as e:
            return {"status": "error", "query": query, "message": str(e)}

    def run_full_test_suite(self) -> Dict[str, Any]:
        """Executa suite completa de testes"""
        print("🔍 Iniciando testes da ferramenta web-research MCP...")
        results = {}

        # Teste 1: Conexão
        print("\n📡 Testando conexão...")
        results["connection"] = self.test_connection()
        print(f"   Status: {results['connection']['status']}")

        # Teste 2: Busca básica
        print("\n🔎 Testando busca básica...")
        results["basic_search"] = self.test_search_basic("fractura coerência contextual")
        print(f"   Status: {results['basic_search']['status']}")

        # Teste 3: Fetch URL
        print("\n📄 Testando fetch de URL...")
        results["url_fetch"] = self.test_fetch_url("https://fcc.rogerluft.com.br")
        print(f"   Status: {results['url_fetch']['status']}")

        # Teste 4: Busca avançada
        print("\n🎯 Testando busca avançada...")
        filters = {
            "date_range": "last_month",
            "language": "pt",
            "domain_filter": ["arxiv.org", "github.com"]
        }
        results["advanced_search"] = self.test_advanced_search("AI consciousness", filters)
        print(f"   Status: {results['advanced_search']['status']}")

        # Teste 5: Performance
        print("\n⚡ Testando performance...")
        start_time = time.time()
        perf_results = []

        for i in range(5):
            result = self.test_search_basic(f"test query {i}")
            perf_results.append(result)

        end_time = time.time()

        results["performance"] = {
            "total_time": end_time - start_time,
            "avg_per_request": (end_time - start_time) / 5,
            "successful_requests": len([r for r in perf_results if r["status"] == "success"])
        }

        print(f"   Tempo total: {results['performance']['total_time']:.2f}s")
        print(f"   Média por request: {results['performance']['avg_per_request']:.2f}s")

        return results

    def save_results(self, results: Dict[str, Any], filename: str = "web_research_test_results.json"):
        """Salva resultados em arquivo JSON"""
        with open(filename, 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=2, ensure_ascii=False, default=str)
        print(f"\n💾 Resultados salvos em: {filename}")

def main():
    # Configurações
    BASE_URL = "http://localhost:8080"  # Ajuste conforme sua configuração

    print("🚀 Web-Research MCP Tester")
    print("=" * 50)

    # Inicializa tester
    tester = WebResearchTester(BASE_URL)

    # Executa testes
    results = tester.run_full_test_suite()

    # Salva resultados
    tester.save_results(results)

    # Summary
    print("\n📊 RESUMO DOS TESTES:")
    print("=" * 30)
    for test_name, result in results.items():
        if isinstance(result, dict) and "status" in result:
            status_emoji = "✅" if result["status"] == "success" else "❌"
            print(f"{status_emoji} {test_name}: {result['status']}")
        else:
            print(f"📈 {test_name}: Dados coletados")

if __name__ == "__main__":
    main()

