                localStorage.setItem('alcatruzLastUpdate', new Date().toISOString());
            } catch (e) {
                console.warn('Não foi possível salvar dados:', e);
            }
        }

        function loadData() {
            try {
                const saved = localStorage.getItem('alcatruzServers');
                const lastUpdate = localStorage.getItem('alcatruzLastUpdate');

                if (saved) {
                    serversData = { ...serversData, ...JSON.parse(saved) };
                }

                if (lastUpdate) {
                    document.getElementById('lastAccess').textContent = 
                        new Date(lastUpdate).toLocaleString('pt-BR');
                }
            } catch (e) {
                console.warn('Não foi possível carregar dados salvos:', e);
            }
        }

