        const originalToggleService = toggleService;
        toggleService = function(serverId, serviceId) {
            originalToggleService(serverId, serviceId);
            autoSave();
        };

        const originalDeleteService = deleteService;
        deleteService = function(serverId, serviceId) {
            const result = originalDeleteService(serverId, serviceId);
            if (result !== false) autoSave();
        };

        const originalAddServer = addServer;
        addServer = function() {
            originalAddServer();
            autoSave();
        };

        const originalDeleteServer = deleteServer;
        deleteServer = function(serverId) {
            const result = originalDeleteServer(serverId);
            if (result !== false) autoSave();
        };

