            // Auto-save a cada 5 minutos
            setInterval(saveData, 300000);

            showNotification('🚀 Portal Alcatruz carregado com sucesso!', 'success');
        });

        // Atalhos de teclado
        document.addEventListener('keydown', function(e) {
            if (e.ctrlKey || e.metaKey) {
                switch(e.key) {
                    case 'f':
                        e.preventDefault();
                        document.getElementById('searchInput').focus();
                        break;
                    case 'n':
                        e.preventDefault();
                        addServer();
                        break;
                    case 'r':
                        e.preventDefault();
                        refreshAll();
                        break;
                }
            }

            if (e.key === 'Escape') {
                // Fechar formulários abertos
                document.querySelectorAll('.add-service-form.show').forEach(form => {
                    form.classList.remove('show');
                });

                // Limpar busca
                document.getElementById('searchInput').value = '';
                filterTree();
            }
        });

        // Função para exportar configuração
        function exportConfig() {
            const config = {
                servers: serversData,
                exportDate: new Date().toISOString(),
                version: '1.0'
            };

            const blob = new Blob([JSON.stringify(config, null, 2)], 
                { type: 'application/json' });
            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');
            a.href = url;
            a.download = `alcatruz-config-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            showNotification('📁 Configuração exportada!', 'success');
        }

        // Função para importar configuração
        function importConfig() {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.json';

            input.onchange = function(e) {
                const file = e.target.files[0];
                if (!file) return;

                const reader = new FileReader();
                reader.onload = function(e) {
                    try {
                        const config = JSON.parse(e.target.result);
                        if (config.servers && confirm('Importar configuração? Isso substituirá os dados atuais.')) {
                            serversData = config.servers;
                            autoSave();
                            showNotification('📥 Configuração importada!', 'success');
                        }
                    } catch (error) {
                        showNotification('❌ Erro ao importar arquivo!', 'error');
                    }
                };
                reader.readAsText(file);
            };

            input.click();
        }

        // Adicionar botões de importar/exportar na interface
        const controls = document.querySelector('.controls');
        const exportBtn = document.createElement('button');
        exportBtn.className = 'btn';
        exportBtn.innerHTML = '📤 Exportar';
        exportBtn.onclick = exportConfig;

        const importBtn = document.createElement('button');
        importBtn.className = 'btn';
        importBtn.innerHTML = '📥 Importar';
        importBtn.onclick = importConfig;

        controls.appendChild(exportBtn);
        controls.appendChild(importBtn);
    </script>
