```javascript
function extractCommandFromResponse(aiResponse) {
    const content = aiResponse.trim();

    // Se começar com explicação, tentar extrair comando
    if (content.toLowerCase().includes('comando') || 
        content.toLowerCase().includes('utilizado') ||
        content.toLowerCase().includes('serve para')) {

        // Procurar comando entre aspas
        const quotedMatch = content.match(/["']([^"']+)["']/g);
        if (quotedMatch && quotedMatch.length > 0) {
            // Pegar o primeiro comando entre aspas
            const cmd = quotedMatch[0].replace(/["']/g, '');
            // Verificar se parece com comando shell (sem espaços em português)
            if (cmd.length < 50 && !cmd.includes(' para ') && !cmd.includes(' é ')) {
                return cmd;
            }
        }

        // Fallback: pegar primeira palavra que parece comando
        const words = content.split(' ');
        for (const word of words) {
            if (word.match(/^[a-z]+$/i) && word.length > 1 && word.length < 20) {
                return word;
            }
        }

        return null; // Comando não identificado
    }

    // Se não é explicação, assumir que é o comando
    const lines = content.split('\n');
    const firstLine = lines[0].trim();

    // Verificar se parece com comando válido
    if (firstLine && firstLine.length < 100 && !firstLine.includes(' para ')) {
        return firstLine;
    }

    return null;
}

