## 🎯 **FUNÇÃO AUXILIAR PARA EXTRAIR COMANDOS**

```javascript
function extractCommand(aiResponse) {
    const content = aiResponse.trim();

    // Se é uma linha simples sem explicação
    if (!content.includes('\n') && 
        !content.toLowerCase().includes('comando') && 
        !content.toLowerCase().includes('serve para') &&
        content.length < 100) {
        return content;
    }

    // Se tem explicação, tentar extrair comando
    const lines = content.split('\n');
    for (const line of lines) {
        const trimmed = line.trim();
        // Procurar linha que parece comando (curta, sem palavras em português)
        if (trimmed && 
            trimmed.length < 50 && 
            !trimmed.includes(' é ') && 
            !trimmed.includes(' para ') &&
            !trimmed.includes('serve') &&
            !trimmed.includes(':')) {
            return trimmed;
        }
    }

    return null;
}
```

