                Write-Warning "No WSL2 distributions found. WSL2 is required for Codex"
                return $false
            }
        }
    } catch {
        Write-Error "WSL is not installed or not accessible"
        return $false
    }

    return $false
}

function Install-WSL2 {
    Write-Status "Installing WSL2..."

    # Check if running as administrator
    if (-NOT ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
        Write-Error "Administrator privileges required to install WSL2"
        Write-Status "Please run this script as Administrator"
        return $false
    }

    try {
        # Install WSL
        Write-Status "Enabling WSL feature..."
        dism.exe /online /enable-feature /featurename:Microsoft-Windows-Subsystem-Linux /all /norestart

        # Install Virtual Machine Platform
        Write-Status "Enabling Virtual Machine Platform..."
        dism.exe /online /enable-feature /featurename:VirtualMachinePlatform /all /norestart

        # Set WSL2 as default
        Write-Status "Setting WSL2 as default version..."
        wsl --set-default-version 2

        Write-Success "WSL2 features enabled"
        Write-Warning "A restart may be required"

        # Install Ubuntu (most common distribution)
        Write-Status "Installing Ubuntu distribution..."
        wsl --install -d Ubuntu

        Write-Success "Ubuntu installed. Please complete the initial setup"
        return $true
    } catch {
        Write-Error "Failed to install WSL2: $_"
        return $false
    }
}

function Test-NodeJS {
    Write-Status "Checking Node.js in WSL..."

    try {
        $nodeVersion = wsl node --version 2>$null
        if ($LASTEXITCODE -eq 0) {
            $version = $nodeVersion.Replace("v", "").Split(".")[0]
            if ([int]$version -ge 22) {
                Write-Success "Node.js version compatible: $nodeVersion"
                return $true
            } else {
                Write-Error "Node.js version $nodeVersion found. Version 22+ required"
                return $false
            }
        }
    } catch {
        Write-Error "Node.js not found in WSL"
        return $false
    }

    return $false
}

function Install-NodeJS {
    Write-Status "Installing Node.js in WSL..."

    $installScript = @"
#!/bin/bash
set -e

# Update package list
sudo apt update

# Install Node.js 22 via NodeSource repository
curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash -
sudo apt-get install -y nodejs

# Verify installation
node --version
npm --version
"@

    $scriptPath = "$env:TEMP\install_nodejs.sh"
    $installScript | Out-File -FilePath $scriptPath -Encoding UTF8

    try {
        wsl bash $scriptPath
        Write-Success "Node.js installed successfully"
        return $true
    } catch {
        Write-Error "Failed to install Node.js: $_"
        return $false
    }
}

function Install-Codex {
    Write-Status "Installing OpenAI Codex in WSL..."

    $installScript = @"
#!/bin/bash
set -e

# Fix npm permissions
mkdir -p ~/.npm-global
npm config set prefix '~/.npm-global'
export PATH=~/.npm-global/bin:\$PATH

# Add to shell profile
echo 'export PATH=~/.npm-global/bin:\$PATH' >> ~/.bashrc

# Install Codex
npm install -g @openai/codex

# Verify installation
codex --version
"@

    $scriptPath = "$env:TEMP\install_codex.sh"
    $installScript | Out-File -FilePath $scriptPath -Encoding UTF8

    try {
        wsl bash $scriptPath
        Write-Success "OpenAI Codex installed successfully"
        return $true
    } catch {
        Write-Error "Failed to install Codex: $_"
        return $false
    }
}

function Set-APIKey {
    param([string]$Key)

    if (-not $Key) {
        Write-Status "OpenAI API key is required"
        Write-Status "Get your API key from: https://platform.openai.com/api-keys"
        $Key = Read-Host "Enter your OpenAI API key (or press Enter to skip)"
    }

    if ($Key) {
        $envScript = @"
#!/bin/bash
echo 'export OPENAI_API_KEY="$1"' >> ~/.bashrc
export OPENAI_API_KEY="$1"
echo "API key set successfully"
"@

        $scriptPath = "$env:TEMP\set_api_key.sh"
