        } catch {
            Write-Error "Failed to set API key: $_"
        }
    } else {
        Write-Warning "API key not set. You can set it later in WSL with:"
        Write-Status "export OPENAI_API_KEY=`"your-api-key-here`""
    }
}

function Setup-Config {
    Write-Status "Setting up Codex configuration..."

    $configScript = @"
#!/bin/bash
set -e

# Create config directory
mkdir -p ~/.codex

# Create sample config.yaml
cat > ~/.codex/config.yaml << 'EOF'
# OpenAI Codex Configuration
model: o4-mini # Default model (can be changed to gpt-4o, etc.)
fullAutoErrorMode: ask-user # or ignore-and-continue
EOF

