- Use descriptive variable names
EOF

echo "Configuration files created in ~/.codex/"
"@

    $scriptPath = "$env:TEMP\setup_config.sh"
    $configScript | Out-File -FilePath $scriptPath -Encoding UTF8

    try {
        wsl bash $scriptPath
        Write-Success "Configuration files created"
    } catch {
        Write-Error "Failed to create configuration: $_"
    }
}

function Test-Installation {
    Write-Status "Testing Codex installation..."

    try {
        $help = wsl codex --help 2>$null
        if ($LASTEXITCODE -eq 0) {
            Write-Success "Codex is working correctly"
            return $true
        }
    } catch {
        Write-Error "Codex test failed"
        return $false
    }

    return $false
}

function Show-Usage {
    Write-Status ""
    Write-Status "OpenAI Codex is now installed!"
    Write-Status ""
    Write-Status "To use Codex:"
    Write-Status "1. Open WSL terminal: wsl"
    Write-Status "2. Navigate to your project: cd /mnt/c/your/project"
    Write-Status "3. Run Codex: codex"
