    Write-Status "- Config files: ~/.codex/ (in WSL)"
    Write-Status "- Help: codex --help"
}

# Main installation process
function Main {
    Write-Host "==================================================" -ForegroundColor $Colors.Blue
    Write-Host "OpenAI Codex Installation Script for Windows" -ForegroundColor $Colors.Blue
    Write-Host "==================================================" -ForegroundColor $Colors.Blue
    Write-Host ""

    # Check Windows version
    $osVersion = [Environment]::OSVersion.Version
    if ($osVersion.Major -lt 10) {
        Write-Error "Windows 10 or later required"
        exit 1
    }

    # Check WSL2
    if (-not $SkipWSLCheck) {
        if (-not (Test-WSL2)) {
            $install = Read-Host "Install WSL2? (y/N)"
            if ($install -match "^[Yy]") {
                if (-not (Install-WSL2)) {
                    Write-Error "Failed to install WSL2"
                    exit 1
                }
                Write-Warning "Please restart your computer and run this script again"
                exit 0
            } else {
                Write-Error "WSL2 is required for Codex"
                exit 1
            }
        }
    }

    # Check Node.js
    if (-not (Test-NodeJS)) {
        $install = Read-Host "Install Node.js 22 in WSL? (y/N)"
        if ($install -match "^[Yy]") {
            if (-not (Install-NodeJS)) {
                Write-Error "Failed to install Node.js"
                exit 1
            }
        } else {
            Write-Error "Node.js 22+ is required"
            exit 1
        }
    }

    # Install Codex
    if (-not (Install-Codex)) {
        Write-Error "Failed to install Codex"
        exit 1
    }

