    }

    # Show usage instructions
    Show-Usage

    Write-Host ""
    Write-Host "==================================================" -ForegroundColor $Colors.Green
    Write-Host "Installation Complete! 🚀" -ForegroundColor $Colors.Green
    Write-Host "==================================================" -ForegroundColor $Colors.Green
}

# Run main function
Main

