// Função principal que detecta se estamos numa página de ticket do WHMCS
function detectWHMCSTicket() {
    // Procura por elementos típicos de uma página de ticket do WHMCS
    const ticketIndicators = [
        'input[name="message"]',           // Campo de resposta comum
        'textarea[name="message"]',       // Campo de resposta alternativo
        '.ticket-reply',                  // Classe comum de resposta
        '#ticketreply',                   // ID comum de resposta
        '.admin-ticket-reply'             // Outra variação comum
    ];

    for (let selector of ticketIndicators) {
        if (document.querySelector(selector)) {
            console.log('✅ Página de ticket WHMCS detectada!');
            return true;
        }
    }

    // Também verifica por palavras-chave na URL
    const url = window.location.href.toLowerCase();
    if (url.includes('ticket') || url.includes('support') || url.includes('admin')) {
        console.log('✅ Possível página WHMCS detectada pela URL');
        return true;
    }

    return false;
}

// Função para extrair a descrição do problema do ticket
function extractProblemDescription() {
    // Lista de seletores onde geralmente fica a descrição do problema
    const problemSelectors = [
        '.ticket-message:first-of-type',     // Primeira mensagem do ticket
        '.ticket-content:first-child',       // Conteúdo do ticket
        '.original-message',                 // Mensagem original
        '.ticket-body',                      // Corpo do ticket
        '.support-message:first-of-type'     // Primeira mensagem de suporte
    ];

    for (let selector of problemSelectors) {
        const element = document.querySelector(selector);
        if (element) {
            let text = element.innerText || element.textContent;
            // Limpa o texto e remove quebras de linha excessivas
            text = text.trim().replace(/\s+/g, ' ');
            console.log('📝 Descrição do problema encontrada:', text.substring(0, 100) + '...');
            return text;
        }
    }

    // Se não encontrou seletores específicos, tenta buscar no conteúdo geral
    const allText = document.body.innerText.toLowerCase();
    if (allText.includes('problema:') || allText.includes('issue:') || allText.includes('error:')) {
        console.log('📝 Possível descrição encontrada no conteúdo geral');
        return allText.substring(0, 500); // Limita a 500 caracteres
    }

    console.log('❌ Não foi possível extrair a descrição do problema');
    return null;
}

// Função que implementa o sistema híbrido de geração de respostas
function generateHybridResponse(problemDescription) {
    if (!problemDescription) {
        console.log('❌ Descrição do problema não fornecida');
