            input.includes(keyword.toLowerCase())
        ).length;

        if (matches > maxMatches) {
            maxMatches = matches;
            bestMatch = data;
            matchScore = matches / data.keywords.length; // Calcula score de confiança
        }
    }

    let response, complexity, confidence, method;

    // Se encontrou uma boa correspondência na base local (confiança alta)
    if (bestMatch && matchScore > 0.3 && bestMatch.confidence > 0.8) {
        console.log('✅ Usando resposta da base de conhecimento local');
        response = bestMatch.response;
        complexity = bestMatch.complexity;
        confidence = bestMatch.confidence;
        method = 'local';

    } else {
        // Fallback para resposta genérica estruturada
