        complexity = 'medium';
        confidence = 0.70;
        method = 'template';
    }

    // Calcula tempo baseado na complexidade
    const timeRanges = {
        'small': () => `${Math.floor(Math.random() * 2) + 1}-3 horas (Solução Simples)`,
        'medium': () => `${Math.floor(Math.random() * 2) + 2}-4 horas (Solução Intermediária)`,
        'large': () => `${Math.floor(Math.random() * 4) + 4}-8 horas (Solução Complexa)`
    };

    const timeEstimate = timeRanges[complexity]();

    // Monta a resposta final com todas as informações
    const finalResponse = `${response}

Tempo decorrido: ${timeEstimate}
Método utilizado: ${method === 'local' ? 'Base de Conhecimento' : 'Template Estruturado'}
Confiança: ${Math.round(confidence * 100)}%`;

    console.log(`✅ Resposta gerada via ${method} com ${Math.round(confidence * 100)}% de confiança`);

    return {
        text: finalResponse,
        complexity: complexity,
        confidence: confidence,
