        timeEstimate: timeEstimate
    };
}

// Função para encontrar e preencher o campo de resposta no WHMCS
function fillResponseField(responseText) {
    // Lista de possíveis seletores para campos de resposta
    const responseFieldSelectors = [
        'textarea[name="message"]',        // Campo mais comum
        'input[name="message"]',           // Variação input
        '#message',                       // Por ID
        '.ticket-reply textarea',         // Por classe
        '#ticketreply textarea',          // Combinação de ID e tag
        'textarea[id*="message"]',        // ID contendo "message"
        'textarea[name*="reply"]'         // Name contendo "reply"
    ];

    for (let selector of responseFieldSelectors) {
        const field = document.querySelector(selector);
        if (field) {
            console.log('✅ Campo de resposta encontrado:', selector);

            // Preenche o campo com a resposta gerada
            field.value = responseText;

            // Dispara eventos para garantir que o WHMCS detecte a mudança
            field.dispatchEvent(new Event('input', { bubbles: true }));
            field.dispatchEvent(new Event('change', { bubbles: true }));

            // Destaca o campo visualmente para o usuário
            field.style.border = '3px solid #4CAF50';
            field.style.backgroundColor = '#f0fff0';

            // Remove o destaque após alguns segundos
            setTimeout(() => {
                field.style.border = '';
                field.style.backgroundColor = '';
            }, 3000);

            return true;
        }
    }

    console.log('❌ Campo de resposta não encontrado');
    return false;
}

// Função para criar e mostrar o botão de ação da extensão
function createActionButton() {
    // Verifica se o botão já existe para evitar duplicatas
    if (document.getElementById('whmcs-auto-responder-btn')) {
        return;
    }

    // Cria o botão com estilo atraente
    const button = document.createElement('button');
    button.id = 'whmcs-auto-responder-btn';
    button.innerHTML = '🤖 Gerar Resposta Automática';
    button.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        z-index: 9999;
