    `;

    // Efeitos visuais no hover
    button.addEventListener('mouseenter', () => {
        button.style.transform = 'translateY(-2px)';
        button.style.boxShadow = '0 6px 12px rgba(0,0,0,0.3)';
    });

    button.addEventListener('mouseleave', () => {
        button.style.transform = 'translateY(0)';
        button.style.boxShadow = '0 4px 8px rgba(0,0,0,0.2)';
    });

    // Função principal executada quando o botão é clicado
    button.addEventListener('click', async () => {
        console.log('🚀 Iniciando geração automática de resposta...');

        // Muda visual do botão para indicar processamento
        const originalText = button.innerHTML;
        button.innerHTML = '⏳ Gerando...';
        button.disabled = true;
        button.style.background = '#ccc';

        try {
            // Extrai a descrição do problema da página
            const problemDescription = extractProblemDescription();

            if (!problemDescription) {
                alert('❌ Não foi possível encontrar a descrição do problema nesta página.');
                return;
            }

            // Gera a resposta usando o sistema híbrido
            const response = generateHybridResponse(problemDescription);

            if (!response) {
                alert('❌ Erro ao gerar resposta. Tente novamente.');
                return;
            }

            // Tenta preencher o campo de resposta automaticamente
            const fieldFilled = fillResponseField(response.text);

            if (fieldFilled) {
                // Mostra notificação de sucesso
                showNotification(`✅ Resposta gerada com sucesso!\nMétodo: ${response.method}\nConfiança: ${Math.round(response.confidence * 100)}%\nTempo estimado: ${response.timeEstimate}`, 'success');
            } else {
                // Se não conseguiu preencher automaticamente, copia para clipboard
                navigator.clipboard.writeText(response.text).then(() => {
                    showNotification('📋 Resposta copiada para a área de transferência!\nCole manualmente no campo de resposta.', 'info');
                }).catch(() => {
                    // Fallback se clipboard não funcionar - mostra em popup
                    alert(`Resposta gerada com sucesso!\n\n${response.text}\n\nCopie e cole manualmente no campo de resposta.`);
                });
            }

        } catch (error) {
            console.error('❌ Erro durante processamento:', error);
            showNotification('❌ Erro interno. Verifique o console do navegador.', 'error');
        } finally {
            // Restaura o botão ao estado original
            setTimeout(() => {
                button.innerHTML = originalText;
                button.disabled = false;
                button.style.background = 'linear-gradient(45deg, #4CAF50, #45a049)';
            }, 1000);
        }
    });

    // Adiciona o botão à página
    document.body.appendChild(button);
    console.log('🎯 Botão de ação criado e posicionado');
}

// Função para mostrar notificações elegantes
function showNotification(message, type = 'info') {
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        top: 80px;
        right: 20px;
        z-index: 10000;
        padding: 15px 20px;
