    setTimeout(() => {
        notification.style.transform = 'translateX(100%)';
        setTimeout(() => {
            if (notification.parentNode) {
                notification.parentNode.removeChild(notification);
            }
        }, 300);
    }, 5000);
}

// Função de inicialização que roda quando a página carrega
function initialize() {
    console.log('🔍 Verificando se esta é uma página do WHMCS...');

    // Aguarda a página carregar completamente
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initialize);
        return;
    }

    // Verifica se estamos numa página de ticket
    if (detectWHMCSTicket()) {
        console.log('🎯 Página de ticket WHMCS confirmada - inicializando extensão');

        // Aguarda um pouco para garantir que todos os elementos carregaram
        setTimeout(() => {
            createActionButton();
            showNotification('🤖 WHMCS Auto Responder ativo!\nClique no botão verde para gerar respostas automáticas.', 'info');
        }, 1000);

    } else {
        console.log('ℹ️ Esta não parece ser uma página de ticket do WHMCS');
    }
}

// Observa mudanças na página para detectar navegação SPA (Single Page Application)
const observer = new MutationObserver((mutations) => {
    // Se houve mudanças significativas na página, re-verifica
    mutations.forEach((mutation) => {
        if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
            // Aguarda um pouco e re-inicializa se necessário
            setTimeout(() => {
                if (detectWHMCSTicket() && !document.getElementById('whmcs-auto-responder-btn')) {
                    createActionButton();
                }
            }, 500);
        }
    });
});

// Inicia a observação de mudanças na página
observer.observe(document.body, {
    childList: true,
    subtree: true
});

// Inicia a extensão
initialize();

