// WHMCS Auto Responder - Content Script (VERSÃO CORRIGIDA)
// Versão otimizada para funcionar com editores WYSIWYG do WHMCS

console.log('🤖 WHMCS Auto Responder v2.0 carregado!');

// Base de conhecimento expandida
const knowledgeBase = {
    'proxy': {
        keywords: ['proxy', 'transparente', 'squid', 'opnsense', 'pfsense'],
        response: `Configuração de proxy transparente concluída:

1. Instalação do Squid Proxy via Package Manager no pfSense/OPNsense
2. Configuração do modo transparente em Services > Squid Proxy Server
3. Criação de regras NAT para redirecionamento automático do tráfego HTTP/HTTPS
4. Configuração de ACLs (Access Control Lists) para controle de acesso por usuário/grupo
5. Otimização do cache e definição de políticas de filtragem de conteúdo
6. Teste de funcionamento em diferentes navegadores e validação de logs

Status: Proxy transparente funcionando corretamente`,
        complexity: 'medium',
        confidence: 0.9
    },

    'firewall': {
        keywords: ['firewall', 'bloqueio', 'regra', 'porta', 'acesso', 'liberação', 'nat'],
        response: `Configuração de regras de firewall executada:

1. Análise detalhada dos requisitos de segurança e conectividade necessária
2. Criação de regras específicas para liberação/bloqueio conforme política de segurança
3. Configuração de grupos de objetos (hosts/redes) para facilitar gerenciamento futuro
4. Implementação de logs detalhados para monitoramento e auditoria
5. Teste rigoroso de conectividade em todas as portas e serviços afetados
6. Documentação completa das regras criadas para referência e compliance

Status: Regras de firewall aplicadas e validadas com sucesso`,
        complexity: 'small',
        confidence: 0.95
    },

    'email': {
        keywords: ['email', 'correio', 'smtp', 'pop3', 'imap', 'postfix', 'exchange', 'outlook'],
        response: `Resolução de problemas do servidor de email concluída:

1. Diagnóstico completo através de análise de logs do servidor de email
2. Verificação e correção de registros DNS (MX, SPF, DKIM, DMARC)
3. Teste de conectividade SMTP/IMAP/POP3 nas portas apropriadas (25, 587, 993, 995)
4. Configuração/renovação de certificados SSL/TLS para comunicação segura
5. Otimização de filas de email, limpeza de spam e configuração de antivírus
6. Validação de envio/recebimento com diferentes provedores (Gmail, Outlook, etc.)

Status: Serviço de email operacional e todos os testes de conectividade aprovados`,
        complexity: 'medium',
        confidence: 0.88
    },

    'backup': {
        keywords: ['backup', 'restore', 'recuperação', 'dados', 'restauração', 'dump'],
        response: `Procedimento de backup/restore executado com total sucesso:

1. Verificação prévia da integridade dos dados originais e espaço disponível
2. Execução do backup/restore seguindo melhores práticas de segurança
3. Validação bit-a-bit da consistência e integridade dos dados recuperados
4. Teste funcional completo de todas as aplicações e serviços afetados
5. Criação de documentação detalhada do procedimento para referência futura
6. Implementação de verificações automáticas de integridade e agendamento

Status: Dados recuperados com 100% de integridade, sistemas operacionais`,
        complexity: 'large',
        confidence: 0.92
    },

    'servidor': {
        keywords: ['servidor', 'server', 'hardware', 'liga', 'boot', 'reiniciar', 'travou'],
        response: `Resolução de problema no servidor concluída:

1. Diagnóstico físico completo do hardware (fonte, memória RAM, processador, discos)
2. Análise detalhada de logs de sistema, eventos de erro e mensagens de boot
3. Teste individual de componentes críticos e verificação de conectividade
4. Aplicação de correções de configuração e atualizações identificadas como necessárias
5. Reinicialização controlada com monitoramento de estabilidade em tempo real
6. Implementação de monitoramento preventivo para detectar problemas futuros

Status: Servidor operacional e estável, monitoramento preventivo ativo`,
        complexity: 'medium',
        confidence: 0.85
    },

    'rede': {
        keywords: ['rede', 'internet', 'conectividade', 'cabo', 'switch', 'roteador', 'ip'],
        response: `Resolução de problema de conectividade de rede:

1. Diagnóstico completo da infraestrutura de rede (cabos, switches, roteadores)
2. Verificação de configurações IP, DNS, gateway e tabelas de roteamento
3. Teste de conectividade em diferentes camadas (física, enlace, rede, aplicação)
4. Resolução de conflitos de endereçamento IP e configuração de VLANs se necessário
5. Otimização de performance de rede e correção de gargalos identificados
6. Validação final da conectividade com todos os recursos críticos

Status: Conectividade de rede totalmente restabelecida e otimizada`,
        complexity: 'small',
        confidence: 0.90
    }
};

// Função melhorada para detectar páginas de ticket WHMCS
function detectWHMCSTicket() {
    // Verifica elementos específicos do WHMCS
    const whmcsIndicators = [
        // Campos de resposta comuns
        'textarea[name="message"]',
        'input[name="message"]',
        'textarea[name="reply"]',
        'input[name="reply"]',

        // Editores WYSIWYG
        '.mce-tinymce',              // TinyMCE
        '.cke_editor',               // CKEditor
        '.ck-editor',                // CKEditor 5

        // Elementos específicos do WHMCS
        '.ticket-reply-form',
        '.admin-ticket-reply',
        '.support-ticket-reply',
        '#ticketreply',

        // Botões específicos
        'input[value="Add Reply"]',
        'button[type="submit"]',

        // Pela URL
        () => {
            const url = window.location.href.toLowerCase();
            return url.includes('supporttickets') || 
                   url.includes('ticket') || 
                   url.includes('admin') ||
                   url.includes('support');
        }
    ];

    for (let indicator of whmcsIndicators) {
        if (typeof indicator === 'function') {
            if (indicator()) {
                console.log('✅ Página WHMCS detectada pela URL');
                return true;
            }
        } else if (document.querySelector(indicator)) {
            console.log('✅ Página WHMCS detectada:', indicator);
            return true;
        }
    }

    // Verifica também por texto específico do WHMCS
    const pageText = document.body.innerText.toLowerCase();
    if (pageText.includes('whmcs') || 
        pageText.includes('support ticket') || 
        pageText.includes('ticket reply')) {
        console.log('✅ Página WHMCS detectada por texto');
        return true;
    }

    return false;
}

// Função melhorada para extrair descrição do problema
function extractProblemDescription() {
    const problemSelectors = [
        // Mensagens específicas do WHMCS
        '.ticket-message:first-of-type .message-content',
        '.ticket-content:first-child',
        '.original-message',
        '.ticket-body',
        '.support-message:first-of-type',
        '.ticket-thread .message:first-child',

        // Elementos gerais
        '.panel-body:first-of-type',
        '.well:first-of-type',
        '.alert:first-of-type'
    ];

    for (let selector of problemSelectors) {
        const element = document.querySelector(selector);
        if (element) {
            let text = element.innerText || element.textContent;
            text = text.trim().replace(/\s+/g, ' ');
            if (text.length > 20) { // Só considera se tiver conteúdo significativo
                console.log('📝 Descrição encontrada:', text.substring(0, 100) + '...');
                return text;
            }
        }
    }

    // Busca por padrões específicos no texto
    const allText = document.body.innerText;
    const patterns = [
        /problema:?\s*(.{20,500})/i,
        /issue:?\s*(.{20,500})/i,
        /error:?\s*(.{20,500})/i,
        /help:?\s*(.{20,500})/i,
        /support:?\s*(.{20,500})/i
    ];

    for (let pattern of patterns) {
        const match = allText.match(pattern);
        if (match && match[1]) {
            console.log('📝 Descrição encontrada por padrão:', match[1].substring(0, 100) + '...');
            return match[1].trim();
        }
    }

    console.log('❌ Descrição do problema não encontrada');
    return null;
}

// Função de geração de resposta (mantida igual)
function generateHybridResponse(problemDescription) {
    if (!problemDescription) {
        console.log('❌ Descrição do problema não fornecida');
        return null;
    }

    const input = problemDescription.toLowerCase();
    console.log('🧠 Analisando problema:', input.substring(0, 100) + '...');

    let bestMatch = null;
    let maxMatches = 0;
    let matchScore = 0;

    for (const [category, data] of Object.entries(knowledgeBase)) {
        const matches = data.keywords.filter(keyword => 
            input.includes(keyword.toLowerCase())
        ).length;

        if (matches > maxMatches) {
            maxMatches = matches;
            bestMatch = data;
            matchScore = matches / data.keywords.length;
        }
    }

    let response, complexity, confidence, method;

    if (bestMatch && matchScore > 0.3 && bestMatch.confidence > 0.8) {
        console.log('✅ Usando resposta da base de conhecimento local');
        response = bestMatch.response;
        complexity = bestMatch.complexity;
        confidence = bestMatch.confidence;
        method = 'local';
    } else {
        console.log('🔄 Usando template genérico estruturado');
        response = `Atendimento técnico especializado realizado conforme solicitação:

1. Análise técnica detalhada do problema reportado pelo cliente
2. Identificação da causa raiz através de diagnósticos direcionados
3. Implementação da solução mais adequada seguindo melhores práticas
4. Execução de testes rigorosos para validação da correção aplicada
5. Documentação completa do procedimento para referência futura
6. Monitoramento pós-implementação para garantir estabilidade da solução

Status: Problema resolvido com sucesso conforme especificações técnicas`;

        complexity = 'medium';
        confidence = 0.70;
        method = 'template';
    }

    const timeRanges = {
        'small': () => `${Math.floor(Math.random() * 2) + 1}-3 horas (Solução Simples)`,
        'medium': () => `${Math.floor(Math.random() * 2) + 2}-4 horas (Solução Intermediária)`,
        'large': () => `${Math.floor(Math.random() * 4) + 4}-8 horas (Solução Complexa)`
    };

    const timeEstimate = timeRanges[complexity]();

    const finalResponse = `${response}

Tempo decorrido: ${timeEstimate}
Método utilizado: ${method === 'local' ? 'Base de Conhecimento' : 'Template Estruturado'}
Confiança: ${Math.round(confidence * 100)}%`;

    console.log(`✅ Resposta gerada via ${method} com ${Math.round(confidence * 100)}% de confiança`);

    return {
        text: finalResponse,
        complexity: complexity,
        confidence: confidence,
        method: method,
        timeEstimate: timeEstimate
    };
}

// Função MUITO melhorada para preencher campos (incluindo editores WYSIWYG)
function fillResponseField(responseText) {
    console.log('🔍 Procurando campo de resposta...');

    // Estratégia 1: Tentar editores WYSIWYG primeiro
    const wysiwygStrategies = [
        // TinyMCE
        () => {
            if (window.tinymce && window.tinymce.editors.length > 0) {
                const editor = window.tinymce.editors[0];
                console.log('✅ TinyMCE encontrado');
                editor.setContent(responseText);
                editor.fire('change');
                return true;
            }
            return false;
        },

        // CKEditor 4
        () => {
            if (window.CKEDITOR && window.CKEDITOR.instances) {
                const instances = Object.keys(window.CKEDITOR.instances);
                if (instances.length > 0) {
                    const editor = window.CKEDITOR.instances[instances[0]];
                    console.log('✅ CKEditor 4 encontrado');
                    editor.setData(responseText);
                    editor.fire('change');
                    return true;
                }
            }
            return false;
        },

        // CKEditor 5
        () => {
            const ckEditor = document.querySelector('.ck-editor__editable');
            if (ckEditor) {
                console.log('✅ CKEditor 5 encontrado');
                ckEditor.innerHTML = responseText.replace(/\n/g, '<br>');
                ckEditor.dispatchEvent(new Event('input', { bubbles: true }));
                return true;
            }
            return false;
        }
    ];

    // Tenta cada estratégia de editor WYSIWYG
    for (let strategy of wysiwygStrategies) {
        if (strategy()) {
            return true;
        }
    }

    // Estratégia 2: Campos de texto tradicionais (EXPANDIDA)
    const responseFieldSelectors = [
        // Seletores específicos do WHMCS
        'textarea[name="message"]',
        'input[name="message"]',
        'textarea[name="reply"]',
        'input[name="reply"]',
        'textarea[name="replycontents"]',
        'textarea[name="admin_reply"]',

        // Seletores por ID
        '#message',
        '#reply',
        '#replycontents',
        '#admin_reply',
        '#ticketreply',

        // Seletores por classe
        '.ticket-reply textarea',
        '.admin-reply textarea',
        '.support-reply textarea',
        '.message-input textarea',

        // Seletores genéricos
        'textarea[id*="message"]',
        'textarea[name*="reply"]',
        'textarea[class*="reply"]',
        'textarea[placeholder*="reply"]',
        'textarea[placeholder*="message"]',

        // Último recurso - qualquer textarea visível
        'textarea:not([style*="display: none"]):not([style*="display:none"])'
    ];

    for (let selector of responseFieldSelectors) {
        const fields = document.querySelectorAll(selector);

        for (let field of fields) {
            // Verifica se o campo está visível
            const rect = field.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0 && 
                window.getComputedStyle(field).display !== 'none') {

                console.log('✅ Campo de resposta encontrado:', selector);

                // Preenche o campo
                field.value = responseText;

                // Dispara múltiplos eventos para garantir detecção
                const events = ['input', 'change', 'keyup', 'paste'];
                events.forEach(eventType => {
                    field.dispatchEvent(new Event(eventType, { bubbles: true }));
                });

                // Destaca visualmente
                field.style.border = '3px solid #4CAF50';
                field.style.backgroundColor = '#f0fff0';
                field.style.boxShadow = '0 0 10px rgba(76, 175, 80, 0.5)';

                // Foca no campo
                field.focus();

                // Remove destaque após alguns segundos
                setTimeout(() => {
                    field.style.border = '';
                    field.style.backgroundColor = '';
                    field.style.boxShadow = '';
                }, 3000);

                return true;
            }
        }
    }

    // Estratégia 3: Buscar dentro de iframes
    const iframes = document.querySelectorAll('iframe');
    for (let iframe of iframes) {
        try {
            const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
            const textareas = iframeDoc.querySelectorAll('textarea, [contenteditable="true"]');

            for (let textarea of textareas) {
                console.log('✅ Campo encontrado em iframe');
                if (textarea.tagName === 'TEXTAREA') {
                    textarea.value = responseText;
                } else {
                    textarea.innerHTML = responseText.replace(/\n/g, '<br>');
                }
                textarea.dispatchEvent(new Event('input', { bubbles: true }));
                return true;
            }
        } catch (e) {
            // Iframe de domínio diferente, não podemos acessar
            console.log('❌ Não foi possível acessar iframe (CORS)');
        }
    }

    console.log('❌ Nenhum campo de resposta encontrado');
    return false;
}

// Função para criar botão (melhorada)
function createActionButton() {
    if (document.getElementById('whmcs-auto-responder-btn')) {
        return;
    }

    const button = document.createElement('button');
    button.id = 'whmcs-auto-responder-btn';
    button.innerHTML = '🤖 Gerar Resposta Automática';
    button.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        z-index: 99999;
        background: linear-gradient(45deg, #4CAF50, #45a049);
        color: white;
        border: none;
        padding: 12px 20px;
        border-radius: 8px;
        cursor: pointer;
        font-weight: bold;
        font-size: 14px;
        box-shadow: 0 4px 8px rgba(0,0,0,0.2);
        transition: all 0.3s ease;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    `;

    button.addEventListener('mouseenter', () => {
        button.style.transform = 'translateY(-2px)';
        button.style.boxShadow = '0 6px 12px rgba(0,0,0,0.3)';
    });

    button.addEventListener('mouseleave', () => {
        button.style.transform = 'translateY(0)';
        button.style.boxShadow = '0 4px 8px rgba(0,0,0,0.2)';
    });

    button.addEventListener('click', async () => {
        console.log('🚀 Iniciando geração automática de resposta...');

        const originalText = button.innerHTML;
        button.innerHTML = '⏳ Analisando...';
        button.disabled = true;
        button.style.background = '#ccc';

        try {
            // Aguarda um pouco para garantir que a página está carregada
            await new Promise(resolve => setTimeout(resolve, 500));

            const problemDescription = extractProblemDescription();

            if (!problemDescription) {
                showNotification('❌ Não foi possível encontrar a descrição do problema.\nTente navegar até a página do ticket específico.', 'error');
                return;
            }

            button.innerHTML = '🧠 Gerando resposta...';

            const response = generateHybridResponse(problemDescription);

            if (!response) {
                showNotification('❌ Erro ao gerar resposta. Tente novamente.', 'error');
                return;
            }

            button.innerHTML = '📝 Preenchendo campo...';

            // Aguarda um pouco antes de tentar preencher
            await new Promise(resolve => setTimeout(resolve, 300));

            const fieldFilled = fillResponseField(response.text);

            if (fieldFilled) {
                showNotification(`✅ Resposta preenchida com sucesso!\n\n📊 Detalhes:\n• Método: ${response.method}\n• Confiança: ${Math.round(response.confidence * 100)}%\n• Tempo estimado: ${response.timeEstimate}`, 'success');
            } else {
                // Copia para clipboard como fallback
                try {
                    await navigator.clipboard.writeText(response.text);
                    showNotification('📋 Campo não encontrado automaticamente.\nResposta copiada para área de transferência!\n\nCole manualmente no campo de resposta.', 'warning');
                } catch (clipboardError) {
                    // Mostra em modal como último recurso
                    showResponseModal(response.text);
                }
            }

        } catch (error) {
            console.error('❌ Erro durante processamento:', error);
            showNotification(`❌ Erro interno: ${error.message}\nVerifique o console para mais detalhes.`, 'error');
        } finally {
            setTimeout(() => {
                button.innerHTML = originalText;
                button.disabled = false;
                button.style.background = 'linear-gradient(45deg, #4CAF50, #45a049)';
            }, 1000);
        }
    });

    document.body.appendChild(button);
    console.log('🎯 Botão de ação criado');
}

// Função para mostrar resposta em modal quando outros métodos falham
function showResponseModal(responseText) {
    const modal = document.createElement('div');
    modal.id = 'response-modal';
    modal.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0,0,0,0.8);
        z-index: 100000;
        display: flex;
        align-items: center;
        justify-content: center;
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    `;

    const modalContent = document.createElement('div');
    modalContent.style.cssText = `
        background: white;
        padding: 30px;
        border-radius: 10px;
        max-width: 600px;
        max-height: 70vh;
        overflow-y: auto;
        box-shadow: 0 10px 30px rgba(0,0,0,0.3);
    `;

    modalContent.innerHTML = `
        <h3 style="margin-top: 0; color: #333;">🤖 Resposta Gerada</h3>
