// Prompt melhorado para o FazAI - Especialmente otimizado para DeepSeek
// Substituir nas funções queryOpenAI, queryOpenRouter, queryRequesty

const FAZAI_SYSTEM_PROMPT = `Você é o FazAI, assistente de automação Linux. REGRAS OBRIGATÓRIAS:

1. SEMPRE responda APENAS com o comando shell executável
2. NUNCA adicione explicações, comentários ou texto extra
3. NUNCA use markdown, backticks ou formatação
4. Se precisar de múltiplos comandos, separe com &&
5. Para comandos complexos, use scripts inline com bash -c

EXEMPLOS:
Usuário: "instalar nginx"
Resposta: apt update && apt install -y nginx

Usuário: "verificar espaço em disco"
Resposta: df -h

Usuário: "criar backup do /home"
Resposta: tar -czf /backup/home-$(date +%Y%m%d).tar.gz /home

IMPORTANTE: Sua resposta deve ser executável diretamente no shell.`;

// Função auxiliar para extrair apenas o comando da resposta do DeepSeek
function extractCommandFromResponse(response) {
  if (!response || typeof response !== 'string') {
    return 'echo "Erro: resposta inválida"';
  }

  // Remove backticks e markdown
  let cleaned = response.replace(/```[\s\S]*?```/g, '').replace(/`([^`]+)`/g, '$1');

  // Remove explicações comuns do DeepSeek
  cleaned = cleaned.replace(/^(Aqui está|Para fazer isso|Você pode usar|Execute o seguinte comando|O comando é):?\s*/i, '');
  cleaned = cleaned.replace(/\n\s*Explicação:[\s\S]*$/i, '');
  cleaned = cleaned.replace(/\n\s*Isso irá[\s\S]*$/i, '');
  cleaned = cleaned.replace(/\n\s*Este comando[\s\S]*$/i, '');

  // Pega apenas a primeira linha se houver múltiplas
  const firstLine = cleaned.split('\n')[0].trim();

  // Se começar com comando válido, retorna
  if (firstLine && (firstLine.includes('apt') || firstLine.includes('systemctl') || 
                   firstLine.includes('ls') || firstLine.includes('cd') || 
                   firstLine.includes('mkdir') || firstLine.includes('cp') ||
                   firstLine.includes('mv') || firstLine.includes('rm') ||
                   firstLine.includes('chmod') || firstLine.includes('chown') ||
                   firstLine.includes('tar') || firstLine.includes('wget') ||
                   firstLine.includes('curl') || firstLine.includes('ps') ||
                   firstLine.includes('df') || firstLine.includes('du') ||
                   firstLine.includes('find') || firstLine.includes('grep'))) {
    return firstLine;
  }

  // Fallback: retorna a resposta limpa
  return cleaned.trim() || 'echo "Comando não reconhecido"';
}

// Versão aprimorada da função queryOpenAI com tratamento específico para DeepSeek
async function queryOpenAI(command) {
  const apiKey = config.openai?.api_key || process.env.OPENAI_API_KEY;
  const model = config.openai?.default_model || process.env.OPENAI_MODEL || 'gpt-4-turbo';
  const endpoint = config.openai?.endpoint || process.env.OPENAI_ENDPOINT || 'https://api.openai.com/v1';

  if (!apiKey) {
    throw new Error(`Chave de API da OpenAI não configurada, modelo: ${model}`);
  }

  logger.info(`Enviando requisição para OpenAI (modelo: ${model})`);

  try {
    const response = await axios.post(`${endpoint}/chat/completions`, {
      model: model,
      messages: [
        {
          role: 'system',
          content: FAZAI_SYSTEM_PROMPT
        },
        {
          role: 'user',
          content: command
        }
      ],
      temperature: 0.1, // Mais determinístico
      max_tokens: 150,  // Limita verbosidade
      stop: ['\n\n', 'Explicação:', 'Isso irá', 'Este comando'] // Para na primeira explicação
    }, {
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      }
    });

    const rawResponse = response.data.choices[0].message.content;
    const cleanedCommand = extractCommandFromResponse(rawResponse);

    logger.info(`Resposta bruta: ${rawResponse}`);
    logger.info(`Comando extraído: ${cleanedCommand}`);

    return {
      interpretation: cleanedCommand,
      success: true
    };
  } catch (err) {
    logger.error(`Erro na requisição para OpenAI: ${err.message}`);
    if (err.response) {
      logger.error(`Detalhes da resposta de erro: ${JSON.stringify(err.response.data)}`);
    }
    throw err;
  }
}

// Versão específica para DeepSeek com fallback robusto
async function queryDeepSeekWithFallback(command) {
  const DEEPSEEK_SPECIFIC_PROMPT = `Você é um interpretador de comandos Linux. Responda APENAS com o comando shell, sem explicações.

COMANDO: ${command}
RESPOSTA (apenas comando shell):`;

  try {
    const response = await axios.post('https://api.deepseek.com/v1/chat/completions', {
      model: 'deepseek-chat',
      messages: [
        {
          role: 'system',
          content: 'Você é um interpretador de comandos Linux. Responda APENAS com comandos shell executáveis, sem explicações, comentários ou formatação.'
        },
        {
          role: 'user',
          content: DEEPSEEK_SPECIFIC_PROMPT
        }
      ],
      temperature: 0.0,
      max_tokens: 100,
      stop: ['\n\n', 'Explicação', 'Para', 'Isso', 'Este']
    }, {
      headers: {
        'Authorization': `Bearer ${process.env.DEEPSEEK_API_KEY}`,
        'Content-Type': 'application/json'
      }
    });

    const rawResponse = response.data.choices[0].message.content;
    const cleanedCommand = extractCommandFromResponse(rawResponse);

    logger.info(`DeepSeek - Resposta bruta: ${rawResponse}`);
    logger.info(`DeepSeek - Comando extraído: ${cleanedCommand}`);

    return {
      interpretation: cleanedCommand,
      success: true
    };
  } catch (err) {
    logger.error(`Erro no DeepSeek: ${err.message}`);
    throw err;
  }
}

// Exemplo de uso no deepseek_helper.js
async function deepseekFallback(command) {
  logger.info('Usando fallback DeepSeek aprimorado');

  try {
    return await queryDeepSeekWithFallback(command);
  } catch (err) {
    logger.error(`Fallback DeepSeek falhou: ${err.message}`);

    // Fallback final com interpretação local básica
    const basicCommands = {
      'instalar': `apt update && apt install -y`,
      'verificar': 'ps aux | grep',
      'listar': 'ls -la',
      'espaço': 'df -h',
      'memória': 'free -h',
      'processos': 'ps aux',
      'parar': 'systemctl stop',
      'iniciar': 'systemctl start',
      'reiniciar': 'systemctl restart',
      'status': 'systemctl status'
    };

    for (const [key, cmd] of Object.entries(basicCommands)) {
      if (command.toLowerCase().includes(key)) {
        return {
          interpretation: cmd,
          success: true
        };
      }
    }

    return {
      interpretation: 'echo "Comando não reconhecido. Fallback ativo."',
      success: false
    };
  }
}

