// Terminal ChatGPT Bridge - Content Script
class TerminalBridge {
  constructor() {
    this.ws = null;
    this.isConnected = false;
    this.lastResponse = '';
    this.observer = null;
    this.init();
  }

  init() {
    console.log('🚀 Terminal Bridge iniciado no ChatGPT');
    this.connectWebSocket();
    this.setupChatMonitor();
    this.setupInputHandler();
  }

  connectWebSocket() {
    try {
      // Conecta no servidor WebSocket local (você vai criar esse servidor)
      this.ws = new WebSocket('ws://localhost:8080');

      this.ws.onopen = () => {
        console.log('✅ Conectado ao terminal');
        this.isConnected = true;
        this.sendStatus('CONNECTED');
      };

      this.ws.onmessage = (event) => {
        const data = JSON.parse(event.data);
        console.log('📨 Comando do terminal:', data);

        if (data.type === 'SEND_MESSAGE') {
          this.sendMessageToChatGPT(data.message);
        } else if (data.type === 'GET_LAST_RESPONSE') {
          this.sendResponse(this.lastResponse);
        }
      };

      this.ws.onclose = () => {
        console.log('❌ Desconectado do terminal');
        this.isConnected = false;
        // Tenta reconectar em 5 segundos
        setTimeout(() => this.connectWebSocket(), 5000);
      };

      this.ws.onerror = (error) => {
        console.error('🚨 Erro WebSocket:', error);
      };

    } catch (error) {
      console.error('🚨 Erro ao conectar WebSocket:', error);
      setTimeout(() => this.connectWebSocket(), 5000);
    }
  }

  setupChatMonitor() {
    // Monitora novas mensagens do ChatGPT
    const targetNode = document.body;

    this.observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach((node) => {
            if (node.nodeType === Node.ELEMENT_NODE) {
              // Procura por mensagens do assistente
              const assistantMessages = node.querySelectorAll('[data-message-author-role="assistant"]');
              assistantMessages.forEach((msg) => {
                this.processAssistantMessage(msg);
              });
            }
          });
        }
      });
    });

    this.observer.observe(targetNode, {
      childList: true,
      subtree: true
    });

    // Também verifica mensagens já existentes
    this.checkExistingMessages();
  }

  checkExistingMessages() {
    const messages = document.querySelectorAll('[data-message-author-role="assistant"]');
    messages.forEach((msg) => this.processAssistantMessage(msg));
  }

  processAssistantMessage(messageElement) {
    const textContent = this.extractTextFromMessage(messageElement);

    if (textContent && textContent !== this.lastResponse) {
      this.lastResponse = textContent;
      console.log('📝 Nova resposta capturada:', textContent.substring(0, 100) + '...');

      if (this.isConnected) {
        this.sendResponse(textContent);
      }
    }
  }

  extractTextFromMessage(messageElement) {
    // Remove elementos de código e outros elementos não desejados
    const clonedElement = messageElement.cloneNode(true);

    // Remove botões e outros elementos de UI
    const elementsToRemove = clonedElement.querySelectorAll('button, svg, .sr-only');
    elementsToRemove.forEach(el => el.remove());

    return clonedElement.textContent.trim();
  }

  sendResponse(text) {
    if (this.ws && this.isConnected) {
      this.ws.send(JSON.stringify({
        type: 'CHATGPT_RESPONSE',
        message: text,
        timestamp: Date.now()
      }));
    }
  }

  sendStatus(status) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: 'STATUS',
        status: status,
        timestamp: Date.now()
      }));
    }
  }

  setupInputHandler() {
    // Função para encontrar e usar o campo de input
    this.findAndSetupInput();

    // Verifica periodicamente se o input mudou
    setInterval(() => {
      this.findAndSetupInput();
    }, 2000);
  }

  findAndSetupInput() {
    // Procura pelo campo de input do ChatGPT
    const inputSelectors = [
      '#prompt-textarea',
      '[data-id="prompt-textarea"]',
      'textarea[placeholder*="Message"]',
      'textarea[placeholder*="mensagem"]',
      'div[contenteditable="true"]'
    ];

    for (const selector of inputSelectors) {
      const input = document.querySelector(selector);
      if (input && !input.hasAttribute('data-bridge-setup')) {
        input.setAttribute('data-bridge-setup', 'true');
        console.log('🎯 Campo de input encontrado:', selector);
        break;
      }
    }
  }

  sendMessageToChatGPT(message) {
    const inputSelectors = [
      '#prompt-textarea',
      '[data-id="prompt-textarea"]',
      'textarea[placeholder*="Message"]', 
      'textarea[placeholder*="mensagem"]',
      'div[contenteditable="true"]'
    ];

    let inputElement = null;

    for (const selector of inputSelectors) {
      inputElement = document.querySelector(selector);
      if (inputElement) break;
    }

    if (!inputElement) {
      console.error('❌ Campo de input não encontrado');
      return;
    }

    // Preenche o campo
    if (inputElement.tagName === 'TEXTAREA') {
      inputElement.value = message;
      inputElement.dispatchEvent(new Event('input', { bubbles: true }));
    } else if (inputElement.contentEditable === 'true') {
      inputElement.textContent = message;
      inputElement.dispatchEvent(new Event('input', { bubbles: true }));
    }

    // Procura pelo botão de enviar
    setTimeout(() => {
      const sendButton = this.findSendButton();
      if (sendButton && !sendButton.disabled) {
        sendButton.click();
        console.log('✅ Mensagem enviada:', message.substring(0, 50) + '...');
      } else {
        console.error('❌ Botão de enviar não encontrado ou desabilitado');
      }
    }, 500);
  }

  findSendButton() {
    const buttonSelectors = [
      'button[data-testid="send-button"]',
      'button[aria-label*="Send"]',
      'button[aria-label*="Enviar"]',
      'button svg[viewBox*="24"]',
      '[data-testid="send-button"]'
    ];

    for (const selector of buttonSelectors) {
      const button = document.querySelector(selector);
      if (button) {
        return button.tagName === 'BUTTON' ? button : button.closest('button');
      }
    }

    // Fallback: procura por qualquer botão próximo ao input
    const buttons = document.querySelectorAll('button');
    for (const button of buttons) {
      if (button.querySelector('svg') && 
          button.getBoundingClientRect().width < 50 && 
          !button.disabled) {
        return button;
      }
    }

    return null;
  }
}

// Inicia a ponte quando a página carregar
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    new TerminalBridge();
  });
} else {
  new TerminalBridge();
}

// Background Service Worker para Terminal ChatGPT Bridge

chrome.runtime.onInstalled.addListener(() => {
  console.log('🚀 Terminal ChatGPT Bridge instalado!');
});

// Monitora mudanças de aba para reiniciar conexão se necessário
chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === 'complete' && 
      (tab.url?.includes('chat.openai.com') || tab.url?.includes('chatgpt.com'))) {

    // Injeta o content script se necessário
    chrome.scripting.executeScript({
      target: { tabId: tabId },
      function: () => {
        // Verifica se o bridge já existe
        if (!window.terminalBridge) {
          console.log('🔄 Reiniciando Terminal Bridge...');
          // O content script será injetado automaticamente
        }
      }
    }).catch(() => {
      // Ignora erros (aba pode não estar pronta)
    });
  }
});

// Lida com mensagens do popup e content script
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.type === 'GET_STATUS') {
    // Retorna status da conexão
    sendResponse({ status: 'ready' });
  } else if (request.type === 'PING_TERMINAL') {
    // Testa conexão com terminal
    fetch('http://localhost:8080', { 
      method: 'HEAD',
      mode: 'no-cors'
    })
    .then(() => sendResponse({ connected: true }))
    .catch(() => sendResponse({ connected: false }));

    return true; // Indica resposta assíncrona
  }
});

// Função para verificar se o ChatGPT está aberto
function isChatGPTOpen() {
  return new Promise((resolve) => {
    chrome.tabs.query({}, (tabs) => {
      const chatGPTTab = tabs.find(tab => 
        tab.url?.includes('chat.openai.com') || 
        tab.url?.includes('chatgpt.com')
      );
      resolve(!!chatGPTTab);
    });
  });
}

// Adiciona badge na extensão quando conectado
chrome.action.setBadgeBackgroundColor({ color: '#4CAF50' });

// Atualiza badge baseado no status
setInterval(async () => {
  const isOpen = await isChatGPTOpen();

  if (isOpen) {
    try {
      // Tenta verificar se o servidor está rodando
      const response = await fetch('http://localhost:8080', { 
        method: 'HEAD',
        mode: 'no-cors'
      });
      chrome.action.setBadgeText({ text: '●' });
      chrome.action.setBadgeBackgroundColor({ color: '#4CAF50' });
    } catch {
      chrome.action.setBadgeText({ text: '○' });
      chrome.action.setBadgeBackgroundColor({ color: '#f44336' });
    }
  } else {
    chrome.action.setBadgeText({ text: '' });
  }
}, 5000);

