#!/usr/bin/env python3
"""
FazAI Chat Terminal - Chat com Mia via shell
Servidor Flask local para chat IA via navegador de texto
"""

from flask import Flask, request, render_template_string
import openai
import os
import json
from datetime import datetime

app = Flask(__name__)

# Configurar OpenAI
openai.api_key = os.getenv('OPENAI_API_KEY')

# Histórico da conversa
conversa = []

# Template HTML minimalista para terminal
HTML_TEMPLATE = '''
<!DOCTYPE html>
<html><head><title>FazAI Chat - Mia</title></head>
<body style="font-family:monospace;background:#000;color:#0f0;margin:20px;">
<h2>🤖 Chat com Mia - FazAI Terminal</h2>
<div style="border:1px solid #0f0;padding:10px;height:300px;overflow-y:scroll;margin:10px 0;">
{% for msg in historico %}
<p><strong>{{ msg.role }}:</strong> {{ msg.content }}</p>
{% endfor %}
</div>
<form method="POST">
<input type="text" name="mensagem" placeholder="Digite sua mensagem..." 
       style="width:80%;background:#000;color:#0f0;border:1px solid #0f0;padding:5px;">
<input type="submit" value="Enviar" 
       style="background:#000;color:#0f0;border:1px solid #0f0;padding:5px;">
</form>
<p><small>Use: lynx localhost:5000 | w3m localhost:5000 | curl localhost:5000</small></p>
</body></html>
'''

@app.route('/', methods=['GET', 'POST'])
def chat():
    global conversa

    if request.method == 'POST':
        mensagem = request.form.get('mensagem', '').strip()

        if mensagem:
            # Adicionar mensagem do usuário
            conversa.append({"role": "user", "content": mensagem})

            try:
                # Chamar OpenAI API
                response = openai.ChatCompletion.create(
                    model="gpt-3.5-turbo",
                    messages=[
                        {"role": "system", "content": "Você é Mia, uma IA amigável e inteligente."},
                        *conversa[-20:]  # Últimas 20 mensagens para contexto
                    ],
                    max_tokens=500,
                    temperature=0.7
                )

                resposta = response.choices[0].message.content
                conversa.append({"role": "assistant", "content": resposta})

            except Exception as e:
                conversa.append({"role": "system", "content": f"Erro: {str(e)}"})

    # Preparar histórico para exibição
    historico = []
    for msg in conversa[-15:]:  # Últimas 15 mensagens
        role = "Você" if msg["role"] == "user" else "Mia" if msg["role"] == "assistant" else "Sistema"
