import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, BarChart, Bar, PieChart, Pie, Cell } from 'recharts';
import { Activity, Wifi, Shield, Server, AlertCircle, CheckCircle } from 'lucide-react';

const OPNsenseMCP = () => {
  const [connectionStatus, setConnectionStatus] = useState('disconnected');
  const [systemStats, setSystemStats] = useState(null);
  const [interfaces, setInterfaces] = useState([]);
  const [firewallStats, setFirewallStats] = useState(null);
  const [connectionConfig, setConnectionConfig] = useState({
    host: '',
    port: '443',
    apiKey: '',
    apiSecret: ''
  });
  const [isLoading, setIsLoading] = useState(false);

  // Mock data para demonstração (substitua pela API real do OPNsense)
  const mockSystemData = {
    cpu: 45,
    memory: 68,
    uptime: '15 days, 3 hours',
    temperature: 52,
    loadAverage: [1.2, 1.5, 1.3]
  };

  const mockInterfacesData = [
    { name: 'WAN', status: 'up', ip: '203.0.113.1', rx: 1250000, tx: 890000 },
    { name: 'LAN', status: 'up', ip: '192.168.1.1', rx: 2100000, tx: 1500000 },
    { name: 'DMZ', status: 'up', ip: '10.0.1.1', rx: 450000, tx: 320000 }
  ];

  const mockFirewallData = {
    totalRules: 45,
    activeConnections: 1250,
    blockedAttempts: 89,
    passedPackets: 15420,
    blockedPackets: 234
  };

  const mockTrafficData = [
    { time: '00:00', wan_in: 120, wan_out: 80, lan_in: 200, lan_out: 150 },
    { time: '04:00', wan_in: 90, wan_out: 60, lan_in: 150, lan_out: 100 },
    { time: '08:00', wan_in: 250, wan_out: 180, lan_in: 400, lan_out: 300 },
    { time: '12:00', wan_in: 300, wan_out: 220, lan_in: 450, lan_out: 350 },
    { time: '16:00', wan_in: 280, wan_out: 200, lan_in: 380, lan_out: 280 },
    { time: '20:00', wan_in: 200, wan_out: 140, lan_in: 300, lan_out: 220 }
  ];

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

  const connectToOPNsense = async () => {
    setIsLoading(true);
    try {
      // Simulação de conexão - substitua pela lógica real da API
      await new Promise(resolve => setTimeout(resolve, 2000));

      setConnectionStatus('connected');
      setSystemStats(mockSystemData);
      setInterfaces(mockInterfacesData);
      setFirewallStats(mockFirewallData);

    } catch (error) {
      setConnectionStatus('error');
      console.error('Erro ao conectar:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const formatBytes = (bytes) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-800 mb-6">OPNsense MCP Dashboard</h1>

        {/* Configuração de Conexão */}
        {connectionStatus === 'disconnected' && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Configuração de Conexão</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium mb-2">Host/IP</label>
                <input
                  type="text"
                  value={connectionConfig.host}
                  onChange={(e) => setConnectionConfig({...connectionConfig, host: e.target.value})}
                  placeholder="192.168.1.1 ou opnsense.local"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">Porta</label>
                <input
                  type="text"
                  value={connectionConfig.port}
                  onChange={(e) => setConnectionConfig({...connectionConfig, port: e.target.value})}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">API Key</label>
                <input
                  type="text"
                  value={connectionConfig.apiKey}
                  onChange={(e) => setConnectionConfig({...connectionConfig, apiKey: e.target.value})}
                  placeholder="Chave da API"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">API Secret</label>
                <input
                  type="password"
                  value={connectionConfig.apiSecret}
                  onChange={(e) => setConnectionConfig({...connectionConfig, apiSecret: e.target.value})}
                  placeholder="Secret da API"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
            <button
              onClick={connectToOPNsense}
              disabled={isLoading || !connectionConfig.host || !connectionConfig.apiKey}
              className="mt-4 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white px-6 py-2 rounded-md transition-colors"
            >
              {isLoading ? 'Conectando...' : 'Conectar ao OPNsense'}
            </button>
          </div>
        )}

        {/* Status da Conexão */}
        {connectionStatus !== 'disconnected' && (
          <div className="bg-white rounded-lg shadow-md p-4 mb-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                {connectionStatus === 'connected' ? (
                  <CheckCircle className="text-green-500" size={24} />
                ) : (
                  <AlertCircle className="text-red-500" size={24} />
                )}
                <span className="text-lg font-medium">
                  Status: {connectionStatus === 'connected' ? 'Conectado' : 'Erro de Conexão'}
                </span>
              </div>
              <button
                onClick={() => {
                  setConnectionStatus('disconnected');
                  setSystemStats(null);
                  setInterfaces([]);
                  setFirewallStats(null);
                }}
                className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md"
              >
                Desconectar
              </button>
            </div>
          </div>
        )}

        {connectionStatus === 'connected' && systemStats && (
          <>
            {/* Cards de Status do Sistema */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
              <div className="bg-white rounded-lg shadow-md p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">CPU</p>
                    <p className="text-2xl font-bold text-blue-600">{systemStats.cpu}%</p>
                  </div>
                  <Activity className="text-blue-600" size={32} />
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-md p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">Memória</p>
                    <p className="text-2xl font-bold text-green-600">{systemStats.memory}%</p>
                  </div>
                  <Server className="text-green-600" size={32} />
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-md p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">Temperatura</p>
                    <p className="text-2xl font-bold text-orange-600">{systemStats.temperature}°C</p>
                  </div>
                  <AlertCircle className="text-orange-600" size={32} />
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-md p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600">Conexões Ativas</p>
                    <p className="text-2xl font-bold text-purple-600">{firewallStats?.activeConnections}</p>
                  </div>
                  <Wifi className="text-purple-600" size={32} />
                </div>
              </div>
            </div>

            {/* Interfaces de Rede */}
            <div className="bg-white rounded-lg shadow-md p-6 mb-6">
              <h3 className="text-xl font-semibold mb-4 flex items-center">
                <Wifi className="mr-2" size={24} />
                Interfaces de Rede
              </h3>
              <div className="overflow-x-auto">
                <table className="min-w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-2 text-left">Interface</th>
                      <th className="px-4 py-2 text-left">Status</th>
                      <th className="px-4 py-2 text-left">IP</th>
                      <th className="px-4 py-2 text-left">RX</th>
                      <th className="px-4 py-2 text-left">TX</th>
                    </tr>
                  </thead>
                  <tbody>
                    {interfaces.map((iface, index) => (
                      <tr key={index} className="border-t">
                        <td className="px-4 py-2 font-medium">{iface.name}</td>
                        <td className="px-4 py-2">
                          <span className={`px-2 py-1 rounded-full text-xs ${
                            iface.status === 'up' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                          }`}>
                            {iface.status.toUpperCase()}
                          </span>
                        </td>
                        <td className="px-4 py-2">{iface.ip}</td>
                        <td className="px-4 py-2">{formatBytes(iface.rx)}</td>
                        <td className="px-4 py-2">{formatBytes(iface.tx)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Gráficos */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
              {/* Gráfico de Tráfego */}
              <div className="bg-white rounded-lg shadow-md p-6">
                <h3 className="text-xl font-semibold mb-4">Tráfego de Rede (24h)</h3>
                <ResponsiveContainer width="100%" height={300}>
                  <LineChart data={mockTrafficData}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="time" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Line type="monotone" dataKey="wan_in" stroke="#8884d8" name="WAN In (Mbps)" />
                    <Line type="monotone" dataKey="wan_out" stroke="#82ca9d" name="WAN Out (Mbps)" />
                    <Line type="monotone" dataKey="lan_in" stroke="#ffc658" name="LAN In (Mbps)" />
                    <Line type="monotone" dataKey="lan_out" stroke="#ff7300" name="LAN Out (Mbps)" />
                  </LineChart>
                </ResponsiveContainer>
              </div>

              {/* Estatísticas do Firewall */}
              <div className="bg-white rounded-lg shadow-md p-6">
                <h3 className="text-xl font-semibold mb-4 flex items-center">
                  <Shield className="mr-2" size={24} />
                  Firewall Stats
                </h3>
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <span>Total de Regras:</span>
                    <span className="font-bold">{firewallStats?.totalRules}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span>Pacotes Permitidos:</span>
                    <span className="font-bold text-green-600">{firewallStats?.passedPackets}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span>Pacotes Bloqueados:</span>
                    <span className="font-bold text-red-600">{firewallStats?.blockedPackets}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span>Tentativas Bloqueadas:</span>
                    <span className="font-bold text-orange-600">{firewallStats?.blockedAttempts}</span>
                  </div>
                </div>

                <div className="mt-6">
                  <ResponsiveContainer width="100%" height={200}>
                    <PieChart>
                      <Pie
                        data={[
                          { name: 'Permitidos', value: firewallStats?.passedPackets },
                          { name: 'Bloqueados', value: firewallStats?.blockedPackets }
                        ]}
                        cx="50%"
                        cy="50%"
                        outerRadius={80}
                        fill="#8884d8"
                        dataKey="value"
                        label
                      >
                        <Cell fill="#00C49F" />
                        <Cell fill="#FF8042" />
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>

            {/* Ações Rápidas */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h3 className="text-xl font-semibold mb-4">Ações Rápidas</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <button className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-md transition-colors">
                  Recarregar Regras
                </button>
                <button className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-md transition-colors">
                  Backup Config
                </button>
                <button className="bg-orange-600 hover:bg-orange-700 text-white px-4 py-2 rounded-md transition-colors">
                  Ver Logs
                </button>
                <button className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md transition-colors">
                  Reiniciar Serviços
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default OPNsenseMCP;

