  setIsLoading(true);
  try {
    const baseUrl = `https://${connectionConfig.host}:${connectionConfig.port}`;
    const auth = btoa(`${connectionConfig.apiKey}:${connectionConfig.apiSecret}`);

    const headers = {
      'Authorization': `Basic ${auth}`,
      'Content-Type': 'application/json',
    };

    // Test connection with system status
    const systemResponse = await fetch(`${baseUrl}/api/diagnostics/system/activity`, {
      method: 'GET',
      headers: headers,
    });

    if (!systemResponse.ok) {
      throw new Error(`HTTP ${systemResponse.status}`);
    }

    const systemData = await systemResponse.json();

    // Get interfaces
    const interfacesResponse = await fetch(`${baseUrl}/api/diagnostics/interface/getInterfaceStatistics`, {
      method: 'GET',
      headers: headers,
    });

    const interfacesData = interfacesResponse.ok ? await interfacesResponse.json() : {};

    // Get firewall stats (if available)
    const firewallResponse = await fetch(`${baseUrl}/api/diagnostics/firewall/statistics`, {
      method: 'GET',
      headers: headers,
    });

    const firewallData = firewallResponse.ok ? await firewallResponse.json() : {};

    setConnectionStatus('connected');

    // Process real data or fallback to mock
    setSystemStats({
      cpu: systemData.cpu || mockSystemData.cpu,
      memory: systemData.memory || mockSystemData.memory,
      uptime: systemData.uptime || mockSystemData.uptime,
      temperature: systemData.temperature || mockSystemData.temperature,
      loadAverage: systemData.loadAverage || mockSystemData.loadAverage
    });

    // Process interfaces data
    if (interfacesData && Object.keys(interfacesData).length > 0) {
      const processedInterfaces = Object.entries(interfacesData).map(([name, data]) => ({
        name: name,
        status: data.status || 'unknown',
        ip: data.ipv4 || 'N/A',
        rx: data.bytes_received || 0,
        tx: data.bytes_sent || 0
      }));
      setInterfaces(processedInterfaces);
    } else {
      setInterfaces(mockInterfacesData);
    }

    setFirewallStats(firewallData.stats || mockFirewallData);

  } catch (error) {
    setConnectionStatus('error');
    console.error('Erro ao conectar:', error);
    alert(`Erro de conexão: ${error.message}. Verifique as credenciais e conectividade.`);
  } finally {
    setIsLoading(false);
  }
};

