import React, { useState, useEffect, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, BarChart, Bar, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { TrendingUp, Calendar, BarChart3, Calculator, Download, Settings, Play, Pause } from 'lucide-react';

// Simulação de dados históricos (em produção, viria de API)
const generateHistoricalData = (years) => {
  const data = [];
  const currentYear = new Date().getFullYear();

  for (let year = currentYear - years; year <= currentYear; year++) {
    for (let month = 1; month <= 12; month++) {
      const daysInMonth = new Date(year, month, 0).getDate();
      for (let day = 1; day <= daysInMonth; day += 7) { // Sorteios semanais
        const date = new Date(year, month - 1, day);
        if (date <= new Date()) {
          data.push({
            date: date.toISOString().split('T')[0],
            premio1: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            premio2: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            premio3: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            bicho1: Math.floor(Math.random() * 25) + 1,
            bicho2: Math.floor(Math.random() * 25) + 1,
            bicho3: Math.floor(Math.random() * 25) + 1,
          });
        }
      }
    }
  }
  return data.reverse();
};

// Função Fibonacci
const fibonacci = (n) => {
  if (n <= 1) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
};

// Análise de frequência
const analyzeFrequency = (data, field) => {
  const frequency = {};
  data.forEach(item => {
    const value = item[field];
    frequency[value] = (frequency[value] || 0) + 1;
  });

  return Object.entries(frequency)
    .map(([value, count]) => ({ value, count, percentage: (count / data.length * 100).toFixed(2) }))
    .sort((a, b) => b.count - a.count);
};

// Cálculo de probabilidades baseado no histórico
const calculateProbabilities = (data, field) => {
  const frequency = analyzeFrequency(data, field);
  const total = data.length;

  return frequency.map(item => ({
    ...item,
    probability: (item.count / total),
    expectedNext: item.count / total > 0.1 ? 'Alta' : item.count / total > 0.05 ? 'Média' : 'Baixa'
  }));
};

// Teste de Rollback (validação de previsões)
const rollbackTest = (data, predictions, lookbackDays = 30) => {
  const testData = data.slice(0, -lookbackDays);
  const realData = data.slice(-lookbackDays);

  let hits = 0;
  realData.forEach(real => {
    if (predictions.some(pred => pred.value === real.premio1 || pred.value === real.bicho1)) {
      hits++;
    }
  });

  return {
    accuracy: (hits / lookbackDays * 100).toFixed(2),
    hits,
    total: lookbackDays
  };
};

const BICHOS = {
  1: 'Avestruz', 2: 'Águia', 3: 'Burro', 4: 'Borboleta', 5: 'Cachorro',
  6: 'Cabra', 7: 'Carneiro', 8: 'Camelo', 9: 'Cobra', 10: 'Coelho',
  11: 'Cavalo', 12: 'Elefante', 13: 'Galo', 14: 'Gato', 15: 'Jacaré',
  16: 'Leão', 17: 'Macaco', 18: 'Porco', 19: 'Pavão', 20: 'Peru',
  21: 'Touro', 22: 'Tigre', 23: 'Urso', 24: 'Veado', 25: 'Vaca'
};

const COLORS = ['#8884d8', '#82ca9d', '#ffc658', '#ff7300', '#00ff00', '#ff00ff', '#00ffff', '#ff0000'];

export default function LoteriaAnalyzer() {
  const [selectedYears, setSelectedYears] = useState(2);
  const [analysisType, setAnalysisType] = useState('frequency');
  const [activeGame, setActiveGame] = useState('loteria');
  const [isLoading, setIsLoading] = useState(false);
  const [autoUpdate, setAutoUpdate] = useState(false);

  const historicalData = useMemo(() => generateHistoricalData(selectedYears), [selectedYears]);

  const frequencyAnalysis = useMemo(() => {
    const field = activeGame === 'loteria' ? 'premio1' : 'bicho1';
    return analyzeFrequency(historicalData, field);
  }, [historicalData, activeGame]);

  const probabilityAnalysis = useMemo(() => {
    const field = activeGame === 'loteria' ? 'premio1' : 'bicho1';
    return calculateProbabilities(historicalData, field);
  }, [historicalData, activeGame]);

  const fibonacciPredictions = useMemo(() => {
    const recentNumbers = historicalData.slice(0, 10).map(item => 
      activeGame === 'loteria' ? parseInt(item.premio1) : item.bicho1
    );

    return recentNumbers.map((num, index) => ({
      original: num,
      fibonacci: fibonacci(index + 1),
      prediction: (num + fibonacci(index + 1)) % (activeGame === 'loteria' ? 100000 : 25) + 1
    }));
  }, [historicalData, activeGame]);

  const rollbackResults = useMemo(() => {
    const topPredictions = probabilityAnalysis.slice(0, 5);
    return rollbackTest(historicalData, topPredictions);
  }, [historicalData, probabilityAnalysis]);

  const handleExportData = () => {
    const dataToExport = {
      historicalData: historicalData.slice(0, 100),
      frequencyAnalysis,
      probabilityAnalysis,
      fibonacciPredictions,
      rollbackResults
    };

    const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `analise-${activeGame}-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  useEffect(() => {
    let interval;
    if (autoUpdate) {
      interval = setInterval(() => {
        setIsLoading(true);
        setTimeout(() => setIsLoading(false), 1000);
      }, 30000);
    }
    return () => clearInterval(interval);
  }, [autoUpdate]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 p-4">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 mb-6 border border-white/20">
          <div className="flex flex-col md:flex-row justify-between items-center gap-4">
            <div>
              <h1 className="text-3xl font-bold text-white mb-2">🎯 Analisador Pro</h1>
              <p className="text-blue-200">Loteria Federal & Jogo do Bicho</p>
            </div>

            <div className="flex gap-4 items-center">
              <div className="flex bg-white/20 rounded-xl p-1">
                <button
                  onClick={() => setActiveGame('loteria')}
                  className={`px-4 py-2 rounded-lg transition-all ${
                    activeGame === 'loteria' 
                      ? 'bg-blue-500 text-white shadow-lg' 
                      : 'text-blue-200 hover:bg-white/10'
                  }`}
                >
                  Loteria Federal
                </button>
                <button
                  onClick={() => setActiveGame('bicho')}
                  className={`px-4 py-2 rounded-lg transition-all ${
                    activeGame === 'bicho' 
                      ? 'bg-green-500 text-white shadow-lg' 
                      : 'text-blue-200 hover:bg-white/10'
                  }`}
                >
                  Jogo do Bicho
                </button>
              </div>

              <button
                onClick={handleExportData}
                className="bg-purple-500 hover:bg-purple-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 transition-all"
              >
                <Download size={18} />
                Exportar
              </button>
            </div>
          </div>
        </div>

        {/* Controles */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-4 border border-white/20">
            <label className="block text-white mb-2">Anos de Análise</label>
            <select
              value={selectedYears}
              onChange={(e) => setSelectedYears(parseInt(e.target.value))}
              className="w-full bg-white/20 text-white rounded-lg px-3 py-2 border border-white/30 focus:outline-none focus:ring-2 focus:ring-blue-400"
            >
              <option value={1}>1 Ano</option>
              <option value={2}>2 Anos</option>
              <option value={5}>5 Anos</option>
              <option value={10}>10 Anos</option>
            </select>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-4 border border-white/20">
            <label className="block text-white mb-2">Tipo de Análise</label>
            <select
              value={analysisType}
              onChange={(e) => setAnalysisType(e.target.value)}
              className="w-full bg-white/20 text-white rounded-lg px-3 py-2 border border-white/30 focus:outline-none focus:ring-2 focus:ring-blue-400"
            >
              <option value="frequency">Frequência</option>
              <option value="probability">Probabilidade</option>
              <option value="fibonacci">Fibonacci</option>
              <option value="patterns">Padrões</option>
            </select>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-4 border border-white/20">
            <label className="block text-white mb-2">Auto-Atualização</label>
            <button
              onClick={() => setAutoUpdate(!autoUpdate)}
              className={`w-full px-3 py-2 rounded-lg flex items-center justify-center gap-2 transition-all ${
                autoUpdate 
                  ? 'bg-green-500 hover:bg-green-600' 
                  : 'bg-gray-500 hover:bg-gray-600'
              } text-white`}
            >
              {autoUpdate ? <Pause size={18} /> : <Play size={18} />}
              {autoUpdate ? 'Pausar' : 'Ativar'}
            </button>
          </div>

          <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-4 border border-white/20">
            <div className="text-white">
              <div className="text-sm opacity-75">Dados Analisados</div>
              <div className="text-2xl font-bold">{historicalData.length}</div>
            </div>
          </div>
        </div>

        {/* Estatísticas Rápidas */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl p-6 text-white">
            <div className="flex items-center justify-between mb-2">
              <TrendingUp size={24} />
              <span className="text-sm opacity-75">Precisão</span>
            </div>
            <div className="text-3xl font-bold">{rollbackResults.accuracy}%</div>
          </div>

          <div className="bg-gradient-to-br from-green-500 to-teal-600 rounded-2xl p-6 text-white">
            <div className="flex items-center justify-between mb-2">
              <BarChart3 size={24} />
              <span className="text-sm opacity-75">Mais Frequente</span>
            </div>
            <div className="text-2xl font-bold">
              {frequencyAnalysis[0]?.value}
              {activeGame === 'bicho' && (
                <div className="text-sm opacity-75">{BICHOS[frequencyAnalysis[0]?.value]}</div>
              )}
            </div>
          </div>

          <div className="bg-gradient-to-br from-orange-500 to-red-600 rounded-2xl p-6 text-white">
            <div className="flex items-center justify-between mb-2">
              <Calculator size={24} />
              <span className="text-sm opacity-75">Fibonacci</span>
            </div>
            <div className="text-2xl font-bold">{fibonacciPredictions[0]?.prediction}</div>
          </div>

          <div className="bg-gradient-to-br from-purple-500 to-pink-600 rounded-2xl p-6 text-white">
            <div className="flex items-center justify-between mb-2">
              <Calendar size={24} />
              <span className="text-sm opacity-75">Último Sorteio</span>
            </div>
            <div className="text-lg font-bold">{historicalData[0]?.date}</div>
          </div>
        </div>

        {/* Gráficos Principais */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          {/* Gráfico de Frequência */}
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
            <h3 className="text-xl font-semibold text-white mb-4">Análise de Frequência</h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={frequencyAnalysis.slice(0, 10)}>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
                <XAxis dataKey="value" stroke="#fff" />
                <YAxis stroke="#fff" />
                <Tooltip 
                  contentStyle={{ backgroundColor: 'rgba(0,0,0,0.8)', border: 'none', borderRadius: '12px' }}
                  labelStyle={{ color: '#fff' }}
                />
                <Bar dataKey="count" fill="#8884d8" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* Gráfico de Tendências */}
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
            <h3 className="text-xl font-semibold text-white mb-4">Tendências Temporais</h3>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={historicalData.slice(0, 30).reverse()}>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
                <XAxis dataKey="date" stroke="#fff" tick={{ fontSize: 12 }} />
                <YAxis stroke="#fff" />
                <Tooltip 
                  contentStyle={{ backgroundColor: 'rgba(0,0,0,0.8)', border: 'none', borderRadius: '12px' }}
                />
                <Line 
                  type="monotone" 
                  dataKey={activeGame === 'loteria' ? 'premio1' : 'bicho1'} 
                  stroke="#82ca9d" 
                  strokeWidth={3}
                  dot={{ r: 4 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Previsões e Análises Avançadas */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
          {/* Previsões Fibonacci */}
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
            <h3 className="text-xl font-semibold text-white mb-4">🔮 Previsões Fibonacci</h3>
            <div className="space-y-3">
              {fibonacciPredictions.slice(0, 5).map((pred, index) => (
                <div key={index} className="bg-white/20 rounded-xl p-3">
                  <div className="flex justify-between items-center">
                    <span className="text-white/80">Previsão {index + 1}</span>
                    <span className="text-xl font-bold text-yellow-300">{pred.prediction}</span>
                  </div>
                  <div className="text-sm text-white/60">
                    Base: {pred.original} + Fib({index + 1}) = {pred.fibonacci}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Análise de Probabilidades */}
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
            <h3 className="text-xl font-semibold text-white mb-4">📊 Probabilidades</h3>
            <div className="space-y-3">
              {probabilityAnalysis.slice(0, 5).map((prob, index) => (
                <div key={index} className="bg-white/20 rounded-xl p-3">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-white font-semibold">{prob.value}</span>
                    <span className={`px-2 py-1 rounded-full text-xs ${
                      prob.expectedNext === 'Alta' ? 'bg-green-500' :
                      prob.expectedNext === 'Média' ? 'bg-yellow-500' : 'bg-red-500'
                    }`}>
                      {prob.expectedNext}
                    </span>
                  </div>
                  <div className="w-full bg-white/20 rounded-full h-2">
                    <div 
                      className="bg-gradient-to-r from-blue-400 to-purple-500 h-2 rounded-full"
                      style={{ width: `${Math.min(prob.probability * 1000, 100)}%` }}
                    ></div>
                  </div>
                  <div className="text-xs text-white/60 mt-1">
                    {(prob.probability * 100).toFixed(4)}% de chance
                  </div>
                  {activeGame === 'bicho' && (
                    <div className="text-xs text-white/80">{BICHOS[prob.value]}</div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Teste de Rollback */}
          <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
            <h3 className="text-xl font-semibold text-white mb-4">🎯 Validação Rollback</h3>
            <div className="text-center mb-4">
              <div className="text-4xl font-bold text-green-400 mb-2">{rollbackResults.accuracy}%</div>
              <div className="text-white/80">Precisão dos Últimos 30 Dias</div>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="bg-green-500/20 rounded-xl p-3 text-center">
                <div className="text-2xl font-bold text-green-300">{rollbackResults.hits}</div>
                <div className="text-xs text-white/70">Acertos</div>
              </div>
              <div className="bg-blue-500/20 rounded-xl p-3 text-center">
                <div className="text-2xl font-bold text-blue-300">{rollbackResults.total}</div>
                <div className="text-xs text-white/70">Total</div>
              </div>
            </div>

            <ResponsiveContainer width="100%" height={120}>
              <PieChart>
                <Pie
                  data={[
                    { name: 'Acertos', value: rollbackResults.hits, color: '#10b981' },
                    { name: 'Erros', value: rollbackResults.total - rollbackResults.hits, color: '#ef4444' }
                  ]}
                  cx="50%"
                  cy="50%"
                  innerRadius={30}
                  outerRadius={50}
                  paddingAngle={5}
                  dataKey="value"
                >
                  <Cell fill="#10b981" />
                  <Cell fill="#ef4444" />
                </Pie>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Tabela de Dados Recentes */}
        <div className="bg-white/10 backdrop-blur-lg rounded-3xl p-6 border border-white/20">
          <h3 className="text-xl font-semibold text-white mb-4">📅 Histórico Recente</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-white">
              <thead>
                <tr className="border-b border-white/20">
                  <th className="text-left p-3">Data</th>
                  {activeGame === 'loteria' ? (
                    <>
                      <th className="text-left p-3">1º Prêmio</th>
                      <th className="text-left p-3">2º Prêmio</th>
                      <th className="text-left p-3">3º Prêmio</th>
                    </>
                  ) : (
                    <>
                      <th className="text-left p-3">1º Bicho</th>
                      <th className="text-left p-3">2º Bicho</th>
                      <th className="text-left p-3">3º Bicho</th>
                    </>
                  )}
                  <th className="text-left p-3">Frequência</th>
                </tr>
              </thead>
              <tbody>
                {historicalData.slice(0, 10).map((item, index) => (
                  <tr key={index} className="border-b border-white/10 hover:bg-white/5 transition-colors">
                    <td className="p-3">{new Date(item.date).toLocaleDateString('pt-BR')}</td>
                    {activeGame === 'loteria' ? (
                      <>
                        <td className="p-3 font-mono text-lg font-bold text-yellow-300">{item.premio1}</td>
                        <td className="p-3 font-mono">{item.premio2}</td>
                        <td className="p-3 font-mono">{item.premio3}</td>
                      </>
                    ) : (
                      <>
                        <td className="p-3">
                          <div className="font-bold text-green-300">{item.bicho1}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho1]}</div>
                        </td>
                        <td className="p-3">
                          <div>{item.bicho2}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho2]}</div>
                        </td>
                        <td className="p-3">
                          <div>{item.bicho3}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho3]}</div>
                        </td>
                      </>
                    )}
                    <td className="p-3">
                      {frequencyAnalysis.find(f => f.value == (activeGame === 'loteria' ? item.premio1 : item.bicho1))?.count || 1}x
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Footer */}
        <div className="text-center text-white/60 mt-8 p-4">
          <p>🎯 Analisador Pro - Desenvolvido para maximizar suas chances de sucesso</p>
          <p className="text-sm mt-2">Análises baseadas em dados históricos • Fibonacci • Probabilidades • IA Avançada</p>
        </div>
      </div>
    </div>
  );
}

