import React, { useState, useEffect, useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, BarChart, Bar, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { TrendingUp, Calendar, BarChart3, Calculator, Download, Settings, Play, Pause, Package, Terminal, Rocket } from 'lucide-react';

// Simulação de dados históricos (em produção, viria de API)
const generateHistoricalData = (years) => {
  const data = [];
  const currentYear = new Date().getFullYear();

  for (let year = currentYear - years; year <= currentYear; year++) {
    for (let month = 1; month <= 12; month++) {
      const daysInMonth = new Date(year, month, 0).getDate();
      for (let day = 1; day <= daysInMonth; day += 7) { // Sorteios semanais
        const date = new Date(year, month - 1, day);
        if (date <= new Date()) {
          data.push({
            date: date.toISOString().split('T')[0],
            premio1: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            premio2: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            premio3: String(Math.floor(Math.random() * 100000)).padStart(5, '0'),
            bicho1: Math.floor(Math.random() * 25) + 1,
            bicho2: Math.floor(Math.random() * 25) + 1,
            bicho3: Math.floor(Math.random() * 25) + 1,
          });
        }
      }
    }
  }
  return data.reverse();
};

// Função Fibonacci
const fibonacci = (n) => {
  if (n <= 1) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
};

// Análise de frequência
const analyzeFrequency = (data, field) => {
  const frequency = {};
  data.forEach(item => {
    const value = item[field];
    frequency[value] = (frequency[value] || 0) + 1;
  });

  return Object.entries(frequency)
    .map(([value, count]) => ({ value, count, percentage: (count / data.length * 100).toFixed(2) }))
    .sort((a, b) => b.count - a.count);
};

// Cálculo de probabilidades baseado no histórico
const calculateProbabilities = (data, field) => {
  const frequency = analyzeFrequency(data, field);
  const total = data.length;

  return frequency.map(item => ({
    ...item,
    probability: (item.count / total),
    expectedNext: item.count / total > 0.1 ? 'Alta' : item.count / total > 0.05 ? 'Média' : 'Baixa'
  }));
};

// Teste de Rollback (validação de previsões)
const rollbackTest = (data, predictions, lookbackDays = 30) => {
  const testData = data.slice(0, -lookbackDays);
  const realData = data.slice(-lookbackDays);

  let hits = 0;
  realData.forEach(real => {
    if (predictions.some(pred => pred.value === real.premio1 || pred.value === real.bicho1)) {
      hits++;
    }
  });

  return {
    accuracy: (hits / lookbackDays * 100).toFixed(2),
    hits,
    total: lookbackDays
  };
};

const BICHOS = {
  1: 'Avestruz', 2: 'Águia', 3: 'Burro', 4: 'Borboleta', 5: 'Cachorro',
  6: 'Cabra', 7: 'Carneiro', 8: 'Camelo', 9: 'Cobra', 10: 'Coelho',
