const BuildManager = ({ isOpen, onClose }) => {
  const [buildType, setBuildType] = useState('web');
  const [building, setBuilding] = useState(false);
  const [buildLogs, setBuildLogs] = useState([]);

  const addBuildLog = (message) => {
    setBuildLogs(prev => [...prev, `${new Date().toLocaleTimeString()}: ${message}`]);
  };

  const startBuild = async () => {
    setBuilding(true);
    setBuildLogs([]);

    const buildSteps = buildType === 'apk' ? [
      'Preparando build para Android...',
      'Compilando código React...',
      'Otimizando assets...',
      'Gerando bundle JavaScript...',
      'Configurando Cordova/Capacitor...',
      'Criando APK não-assinado...',
      'Aplicando assinatura...',
      'APK gerado com sucesso!'
    ] : [
      'Iniciando build web...',
      'Compilando componentes React...',
      'Otimizando CSS e JavaScript...',
      'Gerando bundle de produção...',
      'Criando service worker...',
      'Build web concluído!'
    ];

    for (const step of buildSteps) {
      await new Promise(resolve => setTimeout(resolve, 1200));
      addBuildLog(step);
    }

    setBuilding(false);
    addBuildLog(`✅ ${buildType === 'apk' ? 'APK' : 'Build web'} pronto para distribuição!`);
