          )}

          {building && (
            <button disabled className="flex-1 bg-gray-600 text-white py-3 px-6 rounded-xl font-semibold flex items-center justify-center gap-2">
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
