export default function LoteriaAnalyzer() {
  const [selectedYears, setSelectedYears] = useState(2);
  const [analysisType, setAnalysisType] = useState('frequency');
  const [activeGame, setActiveGame] = useState('loteria');
  const [isLoading, setIsLoading] = useState(false);
  const [autoUpdate, setAutoUpdate] = useState(false);
  const [showInstaller, setShowInstaller] = useState(false);
  const [showBuildManager, setShowBuildManager] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);

  const historicalData = useMemo(() => generateHistoricalData(selectedYears), [selectedYears]);

  const frequencyAnalysis = useMemo(() => {
    const field = activeGame === 'loteria' ? 'premio1' : 'bicho1';
    return analyzeFrequency(historicalData, field);
  }, [historicalData, activeGame]);

  const probabilityAnalysis = useMemo(() => {
    const field = activeGame === 'loteria' ? 'premio1' : 'bicho1';
    return calculateProbabilities(historicalData, field);
  }, [historicalData, activeGame]);

  const fibonacciPredictions = useMemo(() => {
    const recentNumbers = historicalData.slice(0, 10).map(item => 
      activeGame === 'loteria' ? parseInt(item.premio1) : item.bicho1
    );

    return recentNumbers.map((num, index) => ({
      original: num,
      fibonacci: fibonacci(index + 1),
      prediction: (num + fibonacci(index + 1)) % (activeGame === 'loteria' ? 100000 : 25) + 1
    }));
  }, [historicalData, activeGame]);

  const rollbackResults = useMemo(() => {
    const topPredictions = probabilityAnalysis.slice(0, 5);
    return rollbackTest(historicalData, topPredictions);
  }, [historicalData, probabilityAnalysis]);

