                      <th className="text-left p-3">1º Prêmio</th>
                      <th className="text-left p-3">2º Prêmio</th>
                      <th className="text-left p-3">3º Prêmio</th>
                    </>
                  ) : (
                    <>
                      <th className="text-left p-3">1º Bicho</th>
                      <th className="text-left p-3">2º Bicho</th>
                      <th className="text-left p-3">3º Bicho</th>
                    </>
                  )}
                  <th className="text-left p-3">Frequência</th>
                </tr>
              </thead>
              <tbody>
                {historicalData.slice(0, 10).map((item, index) => (
                  <tr key={index} className="border-b border-white/10 hover:bg-white/5 transition-colors">
                    <td className="p-3">{new Date(item.date).toLocaleDateString('pt-BR')}</td>
                    {activeGame === 'loteria' ? (
                      <>
                        <td className="p-3 font-mono text-lg font-bold text-yellow-300">{item.premio1}</td>
                        <td className="p-3 font-mono">{item.premio2}</td>
                        <td className="p-3 font-mono">{item.premio3}</td>
                      </>
                    ) : (
                      <>
                        <td className="p-3">
                          <div className="font-bold text-green-300">{item.bicho1}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho1]}</div>
                        </td>
                        <td className="p-3">
                          <div>{item.bicho2}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho2]}</div>
                        </td>
                        <td className="p-3">
                          <div>{item.bicho3}</div>
                          <div className="text-xs text-white/60">{BICHOS[item.bicho3]}</div>
                        </td>
                      </>
                    )}
                    <td className="p-3">
                      {frequencyAnalysis.find(f => f.value == (activeGame === 'loteria' ? item.premio1 : item.bicho1))?.count || 1}x
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Footer */}
        <div className="text-center text-white/60 mt-8 p-4">
          <p>🏆 MegaLoteriaWinner - O app definitivo para vencer na loteria</p>
          <p className="text-sm mt-2">Análises IA • Fibonacci • Probabilidades • Dados Históricos • Rollback Testing</p>
        </div>

        {/* Modais */}
        <InstallerModal 
          isOpen={showInstaller} 
          onClose={() => setShowInstaller(false)}
          onInstall={() => setIsInstalled(true)}
        />

        <BuildManager 
          isOpen={showBuildManager} 
          onClose={() => setShowBuildManager(false)}
        />
      </div>
    </div>
  );
}

