/**
 * Tipos TypeScript para OpenAI Computer Use Agent (CUA)
 * 
 * Este arquivo define todas as interfaces e tipos utilizados
 * pelo servidor MCP para integração com a API da OpenAI.
 */

// ============================================
// TIPOS DA API OPENAI - COMPUTER USE
// ============================================

/**
 * Tipos de ações que o agente pode executar
 */
export type ComputerActionType = 
  | 'click'
  | 'double_click'
  | 'triple_click'
  | 'type'
  | 'scroll'
  | 'keypress'
  | 'wait'
  | 'screenshot'
  | 'drag';

/**
 * Botões do mouse disponíveis
 */
export type MouseButton = 'left' | 'right' | 'middle';

/**
 * Direção do scroll
 */
export type ScrollDirection = 'up' | 'down' | 'left' | 'right';

/**
 * Teclas especiais que podem ser pressionadas
 */
export type SpecialKey = 
  | 'enter' | 'escape' | 'tab' | 'space' | 'backspace' | 'delete'
  | 'up' | 'down' | 'left' | 'right'
  | 'f1' | 'f2' | 'f3' | 'f4' | 'f5' | 'f6' | 'f7' | 'f8' | 'f9' | 'f10' | 'f11' | 'f12'
  | 'home' | 'end' | 'pageup' | 'pagedown'
  | 'ctrl' | 'alt' | 'shift' | 'meta';

// ============================================
// ESTRUTURAS DE AÇÕES
// ============================================

/**
 * Ação de clique do mouse
 */
export interface ClickAction {
  type: 'click' | 'double_click' | 'triple_click';
  x: number;
  y: number;
  button?: MouseButton;
}

/**
 * Ação de digitação
 */
export interface TypeAction {
  type: 'type';
  text: string;
}

/**
 * Ação de scroll
 */
export interface ScrollAction {
  type: 'scroll';
  x?: number;
  y?: number;
  scroll_x?: number;
  scroll_y?: number;
  direction?: ScrollDirection;
  wheel_times?: number;
}

/**
 * Ação de pressionar tecla
 */
export interface KeypressAction {
  type: 'keypress';
  keys: string[];
}

/**
 * Ação de espera
 */
export interface WaitAction {
  type: 'wait';
  duration: number; // em segundos
}

/**
 * Ação de screenshot
 */
export interface ScreenshotAction {
  type: 'screenshot';
}

/**
 * Ação de arrastar (drag and drop)
 */
export interface DragAction {
  type: 'drag';
  from_x: number;
  from_y: number;
  to_x: number;
  to_y: number;
}

/**
 * União de todos os tipos de ação
 */
export type ComputerAction = 
  | ClickAction
  | TypeAction
  | ScrollAction
  | KeypressAction
  | WaitAction
  | ScreenshotAction
  | DragAction;

// ============================================
// RESPOSTAS DA API
// ============================================

/**
 * Item de raciocínio retornado pela API
 */
export interface ReasoningItem {
  type: 'reasoning';
  id: string;
  summary: {
    type: 'summary_text';
    text: string;
  }[];
}

/**
 * Chamada de ferramenta retornada pela API
 */
export interface ComputerCallItem {
  type: 'computer_call';
  id: string;
  call_id: string;
  action: ComputerAction;
  pending_safety_checks?: SafetyCheck[];
  status: 'completed' | 'pending';
}

/**
 * Item de saída da resposta da API
 */
export type OutputItem = ReasoningItem | ComputerCallItem;

/**
 * Resposta completa da API OpenAI
 */
export interface OpenAIResponse {
  id: string;
  output: OutputItem[];
}

// ============================================
// VERIFICAÇÕES DE SEGURANÇA
// ============================================

/**
 * Tipos de verificações de segurança
 */
export type SafetyCheckCode = 
  | 'malicious_instructions'
  | 'irrelevant_domain'
  | 'sensitive_domain';

/**
 * Verificação de segurança pendente
 */
export interface SafetyCheck {
  id: string;
  code: SafetyCheckCode;
  message: string;
}

/**
 * Verificações de segurança confirmadas pelo usuário
 */
export interface AcknowledgedSafetyCheck {
  id: string;
  code: SafetyCheckCode;
  message: string;
}

// ============================================
// CONFIGURAÇÃO DO AMBIENTE
// ============================================

/**
 * Tipos de ambiente suportados
 */
export type EnvironmentType = 'browser' | 'mac' | 'windows' | 'ubuntu';

/**
 * Configuração da ferramenta computer-use-preview
 */
export interface ComputerUseTool {
  type: 'computer_use_preview';
  display_width: number;
  display_height: number;
  environment: EnvironmentType;
}

// ============================================
// ESTADO DA SESSÃO CUA
// ============================================

/**
 * Estado completo da sessão CUA
 */
export interface CUASessionState {
  sessionId: string;
  conversationHistory: any[]; // Array de mensagens da conversa
  lastScreenshot?: string; // Base64 do último screenshot
  lastCallId?: string; // ID da última chamada
  pendingSafetyChecks: SafetyCheck[];
  isActive: boolean;
  environment: EnvironmentType;
  displayWidth: number;
  displayHeight: number;
}

// ============================================
// PARÂMETROS DAS FERRAMENTAS MCP
// ============================================

/**
 * Parâmetros para iniciar sessão CUA
 */
export interface StartCUASessionParams {
  initialPrompt: string;
  environment?: EnvironmentType;
  displayWidth?: number;
  displayHeight?: number;
  includeInitialScreenshot?: boolean;
}

/**
 * Parâmetros para executar ação CUA
 */
export interface ExecuteCUAActionParams {
  sessionId: string;
  acknowledgedSafetyChecks?: AcknowledgedSafetyCheck[];
}

/**
 * Parâmetros para obter estado da sessão
 */
export interface GetCUASessionParams {
  sessionId: string;
}

/**
 * Parâmetros para parar sessão CUA
 */
export interface StopCUASessionParams {
  sessionId: string;
}

// ============================================
// RESULTADOS DAS FERRAMENTAS MCP
// ============================================

/**
 * Resultado de iniciar sessão CUA
 */
export interface StartCUASessionResult {
  sessionId: string;
  status: 'started';
  message: string;
  firstResponse?: OpenAIResponse;
}

/**
 * Resultado de executar ação CUA
 */
export interface ExecuteCUAActionResult {
  success: boolean;
  actionsExecuted: number;
  response?: OpenAIResponse;
  message: string;
  pendingSafetyChecks?: SafetyCheck[];
}

/**
 * Resultado de obter estado da sessão
 */
export interface GetCUASessionResult {
  exists: boolean;
  state?: CUASessionState;
  message: string;
}

/**
 * Resultado de parar sessão CUA
 */
export interface StopCUASessionResult {
  success: boolean;
  message: string;
}

