/**
 * Módulo de Verificações de Segurança para OpenAI CUA
 * 
 * Implementa as verificações de segurança conforme documentação da OpenAI:
 * - Detecção de instruções maliciosas
 * - Verificação de domínios irrelevantes
 * - Verificação de domínios sensíveis
 */

import { SafetyCheck, SafetyCheckCode } from './types.js';

// ============================================
// LISTAS DE DOMÍNIOS
// ============================================

/**
 * Lista de domínios sensíveis que requerem confirmação do usuário
 * (bancos, emails, redes sociais, etc)
 */
const SENSITIVE_DOMAINS = [
  // Bancos brasileiros
  'bancodobrasil.com.br',
  'bradesco.com.br',
  'itau.com.br',
  'santander.com.br',
  'caixa.gov.br',
  'nubank.com.br',
  'inter.co',
  'c6bank.com.br',

  // Bancos internacionais
  'bankofamerica.com',
  'chase.com',
  'wellsfargo.com',
  'citibank.com',
  'hsbc.com',

  // Email providers
  'gmail.com',
  'outlook.com',
  'hotmail.com',
  'yahoo.com',
  'protonmail.com',

  // Redes sociais
  'facebook.com',
  'instagram.com',
  'twitter.com',
  'x.com',
  'linkedin.com',
  'tiktok.com',

  // Serviços financeiros
  'paypal.com',
  'stripe.com',
  'mercadopago.com.br',
  'picpay.com',

  // Governo
  'gov.br',
  'receita.fazenda.gov.br',

  // Cloud/Admin panels
  'aws.amazon.com',
  'console.cloud.google.com',
  'portal.azure.com',
  'digitalocean.com'
];

/**
 * Palavras-chave que indicam instruções potencialmente maliciosas
 */
const MALICIOUS_KEYWORDS = [
  // Comandos de sistema perigosos
  'rm -rf',
  'del /f',
  'format c:',
  'sudo rm',
  'DROP TABLE',
  'DROP DATABASE',

  // Transferências financeiras
  'transfer money',
  'transferir dinheiro',
  'enviar pagamento',
  'send payment',

  // Credenciais
  'steal password',
  'roubar senha',
  'extract credentials',
  'extrair credenciais',

  // Malware
  'download malware',
  'baixar vírus',
  'install backdoor',
  'instalar backdoor',

  // Manipulação de dados
  'delete all',
  'deletar tudo',
  'erase data',
  'apagar dados',

  // Fraudes
  'phishing',
  'scam',
  'golpe',
  'fraude'
];

// ============================================
// FUNÇÕES DE VERIFICAÇÃO
// ============================================

/**
 * Extrai domínio de uma URL
 */
function extractDomain(url: string): string | null {
  try {
    const urlObj = new URL(url);
    return urlObj.hostname.toLowerCase();
  } catch {
    return null;
  }
}

/**
 * Verifica se um domínio é sensível
 */
function isSensitiveDomain(url: string): boolean {
  const domain = extractDomain(url);
  if (!domain) return false;

  return SENSITIVE_DOMAINS.some(sensitive => 
    domain === sensitive || domain.endsWith('.' + sensitive)
  );
}

/**
 * Verifica se o texto contém instruções maliciosas
 */
function containsMaliciousInstructions(text: string): boolean {
  const lowerText = text.toLowerCase();

  return MALICIOUS_KEYWORDS.some(keyword => 
    lowerText.includes(keyword.toLowerCase())
  );
}

/**
 * Analisa um screenshot em base64 para verificar conteúdo adversarial
 * 
 * Nota: Esta é uma implementação básica. Em produção, você pode
 * integrar com serviços de análise de imagem mais sofisticados.
 */
function analyzeScreenshotForThreats(screenshotBase64: string): boolean {
  // Por enquanto, retorna false (sem ameaças detectadas)
  // Em produção, você poderia usar:
  // - OCR para detectar texto suspeito na tela
  // - Análise de padrões visuais
  // - Verificação de URLs visíveis
  return false;
}

// ============================================
// INTERFACE PÚBLICA
// ============================================

/**
 * Realiza verificações de segurança completas
 */
export function performSafetyChecks(
  prompt: string,
  currentUrl?: string,
  screenshotBase64?: string
): SafetyCheck[] {
  const checks: SafetyCheck[] = [];

  // 1. Verificar instruções maliciosas no prompt
  if (containsMaliciousInstructions(prompt)) {
    checks.push({
      id: generateCheckId(),
      code: 'malicious_instructions',
      message: 'Detectamos instruções que podem causar danos ao sistema ou dados. Por favor, confirme se deseja prosseguir.'
    });
  }

  // 2. Verificar domínio sensível
  if (currentUrl && isSensitiveDomain(currentUrl)) {
    checks.push({
      id: generateCheckId(),
      code: 'sensitive_domain',
      message: `Você está em um domínio sensível (${extractDomain(currentUrl)}). Certifique-se de que está monitorando ativamente as ações do modelo.`
    });
  }

  // 3. Analisar screenshot para ameaças (se fornecido)
  if (screenshotBase64 && analyzeScreenshotForThreats(screenshotBase64)) {
    checks.push({
      id: generateCheckId(),
      code: 'malicious_instructions',
      message: 'Detectamos conteúdo suspeito na tela que pode indicar tentativa de manipulação do modelo.'
    });
  }

  return checks;
}

/**
 * Verifica se um domínio é relevante para a tarefa
 */
export function checkDomainRelevance(
  currentUrl: string,
  taskDescription: string
): SafetyCheck | null {
  const domain = extractDomain(currentUrl);
  if (!domain) return null;

  // Verifica se o domínio é mencionado na descrição da tarefa
  const taskLower = taskDescription.toLowerCase();
  const domainLower = domain.toLowerCase();

  if (!taskLower.includes(domainLower)) {
    return {
      id: generateCheckId(),
      code: 'irrelevant_domain',
      message: `O modelo navegou para '${domain}' que não parece estar relacionado à tarefa solicitada. Verifique se isso é esperado.`
    };
  }

  return null;
}

/**
 * Valida lista de domínios permitidos
 */
export function createDomainAllowlist(allowedDomains: string[]): (url: string) => boolean {
  return (url: string) => {
    const domain = extractDomain(url);
    if (!domain) return false;

    return allowedDomains.some(allowed => 
      domain === allowed || domain.endsWith('.' + allowed)
    );
  };
}

/**
 * Valida lista de domínios bloqueados
 */
export function createDomainBlocklist(blockedDomains: string[]): (url: string) => boolean {
  return (url: string) => {
    const domain = extractDomain(url);
    if (!domain) return true; // Bloqueia URLs inválidas

    return blockedDomains.some(blocked => 
      domain === blocked || domain.endsWith('.' + blocked)
    );
  };
}

// ============================================
// FUNÇÕES AUXILIARES
// ============================================

/**
 * Gera um ID único para verificação de segurança
 */
function generateCheckId(): string {
  return `sc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Valida se uma ação específica é segura
 */
export function isActionSafe(action: any): { safe: boolean; reason?: string } {
  // Verifica ações de clique em coordenadas extremas (possível tentativa de fechar janelas)
  if (action.type === 'click' || action.type === 'double_click') {
    const { x, y } = action;

    // Canto superior direito (botão fechar)
    if (x > 1900 && y < 50) {
      return {
        safe: false,
        reason: 'Tentativa de clicar no botão fechar da janela'
      };
    }
  }

  // Verifica tentativas de pressionar combinações perigosas
  if (action.type === 'keypress') {
    const keys = action.keys.map((k: string) => k.toLowerCase());

    // Alt+F4 (fechar aplicativo)
    if (keys.includes('alt') && keys.includes('f4')) {
      return {
        safe: false,
        reason: 'Tentativa de fechar aplicativo (Alt+F4)'
      };
    }

    // Ctrl+W (fechar aba)
    if (keys.includes('ctrl') && keys.includes('w')) {
      return {
        safe: false,
        reason: 'Tentativa de fechar aba do navegador (Ctrl+W)'
      };
    }
  }

  return { safe: true };
}

/**
 * Formata mensagem de segurança para o usuário
 */
export function formatSafetyMessage(checks: SafetyCheck[]): string {
  if (checks.length === 0) return '';

  let message = '⚠️  VERIFICAÇÕES DE SEGURANÇA:\n\n';

  checks.forEach((check, index) => {
    message += `${index + 1}. [${check.code}]\n`;
    message += `   ${check.message}\n\n`;
  });

  message += 'Para continuar, você deve confirmar explicitamente estas verificações.';

  return message;
}

