/**
 * Handler Principal do OpenAI Computer Use Agent (CUA)
 * 
 * Gerencia:
 * - Sessões CUA ativas
 * - Comunicação com API OpenAI
 * - Execução de ações do computador
 * - Loop de feedback contínuo
 */

import OpenAI from 'openai';
import { chromium, Browser, Page } from 'playwright';
import {
  CUASessionState,
  ComputerAction,
  OpenAIResponse,
  ComputerCallItem,
  StartCUASessionParams,
  ExecuteCUAActionParams,
  SafetyCheck,
  AcknowledgedSafetyCheck,
  EnvironmentType
} from './types.js';
import { performSafetyChecks, isActionSafe, formatSafetyMessage } from './safety-checks.js';

// ============================================
// GERENCIADOR DE SESSÕES CUA
// ============================================

/**
 * Armazena todas as sessões CUA ativas
 */
const activeSessions = new Map<string, CUASessionState>();

/**
 * Armazena instâncias de browser por sessão
 */
const browserInstances = new Map<string, { browser: Browser; page: Page }>();

/**
 * Cliente OpenAI (será inicializado com API key)
 */
let openaiClient: OpenAI | null = null;

// ============================================
// INICIALIZAÇÃO
// ============================================

/**
 * Inicializa o cliente OpenAI
 */
export function initializeOpenAI(apiKey: string): void {
  openaiClient = new OpenAI({
    apiKey: apiKey
  });
}

/**
 * Verifica se o cliente OpenAI está inicializado
 */
function ensureOpenAIClient(): OpenAI {
  if (!openaiClient) {
    throw new Error('OpenAI client not initialized. Please set OPENAI_API_KEY environment variable.');
  }
  return openaiClient;
}

// ============================================
// GERENCIAMENTO DE SESSÕES
// ============================================

/**
 * Gera um ID único para sessão
 */
function generateSessionId(): string {
  return `cua_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Cria uma nova sessão CUA
 */
export async function createCUASession(params: StartCUASessionParams): Promise<CUASessionState> {
  const sessionId = generateSessionId();

  const session: CUASessionState = {
    sessionId,
    conversationHistory: [],
    pendingSafetyChecks: [],
    isActive: true,
    environment: params.environment || 'browser',
    displayWidth: params.displayWidth || 1024,
    displayHeight: params.displayHeight || 768
  };

  // Inicializar browser se o ambiente for 'browser'
  if (session.environment === 'browser') {
    const browser = await chromium.launch({
      headless: false, // Modo visível para o usuário poder monitorar
      args: [`--window-size=${session.displayWidth},${session.displayHeight}`]
    });

    const page = await browser.newPage({
      viewport: {
        width: session.displayWidth,
        height: session.displayHeight
      }
    });

    browserInstances.set(sessionId, { browser, page });

    // Capturar screenshot inicial se solicitado
    if (params.includeInitialScreenshot) {
      const screenshot = await page.screenshot({ encoding: 'base64' });
      session.lastScreenshot = screenshot as string;
    }
  }

  // Adicionar prompt inicial ao histórico
  session.conversationHistory.push({
    role: 'user',
    content: params.initialPrompt
  });

  activeSessions.set(sessionId, session);

  return session;
}

/**
 * Obtém uma sessão existente
 */
export function getCUASession(sessionId: string): CUASessionState | undefined {
  return activeSessions.get(sessionId);
}

/**
 * Encerra uma sessão CUA
 */
export async function closeCUASession(sessionId: string): Promise<void> {
  const session = activeSessions.get(sessionId);
  if (!session) return;

  // Fechar browser se existir
  const browserInstance = browserInstances.get(sessionId);
  if (browserInstance) {
    await browserInstance.browser.close();
    browserInstances.delete(sessionId);
  }

  activeSessions.delete(sessionId);
}

// ============================================
// COMUNICAÇÃO COM OPENAI API
// ============================================

/**
 * Envia requisição para OpenAI CUA API
 */
async function callOpenAICUA(session: CUASessionState): Promise<OpenAIResponse> {
  const client = ensureOpenAIClient();

  // Preparar ferramentas
  const tools = [
    {
      type: 'computer_use_preview',
      display_width: session.displayWidth,
      display_height: session.displayHeight,
      environment: session.environment
    }
  ];

  // Preparar input com screenshot se disponível
  const lastMessage = session.conversationHistory[session.conversationHistory.length - 1];
  const input: any[] = [lastMessage];

  // Adicionar screenshot se disponível
  if (session.lastScreenshot) {
    input.push({
      type: 'computer_call_output',
      call_id: session.lastCallId || 'initial',
      output: {
        type: 'computer_screenshot',
        image_url: `data:image/png;base64,${session.lastScreenshot}`
      }
    });
  }

  try {
    const response = await client.responses.create({
      model: 'computer-use-preview',
      tools: tools,
      input: input,
      reasoning: { summary: 'concise' },
      truncation: 'auto'
    });

    return response as unknown as OpenAIResponse;
  } catch (error: any) {
    throw new Error(`OpenAI API Error: ${error.message}`);
  }
}

// ============================================
// EXECUÇÃO DE AÇÕES
// ============================================

/**
 * Executa uma ação de clique
 */
async function executeClickAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'click' && action.type !== 'double_click' && action.type !== 'triple_click') {
    throw new Error('Invalid action type for click');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const { x, y, button = 'left' } = action as any;

  const clickCount = action.type === 'double_click' ? 2 : action.type === 'triple_click' ? 3 : 1;

  await page.mouse.click(x, y, {
    button: button as 'left' | 'right' | 'middle',
    clickCount
  });
}

/**
 * Executa uma ação de digitação
 */
async function executeTypeAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'type') {
    throw new Error('Invalid action type for type');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const { text } = action as any;

  await page.keyboard.type(text);
}

/**
 * Executa uma ação de scroll
 */
async function executeScrollAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'scroll') {
    throw new Error('Invalid action type for scroll');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const { x = 0, y = 0, scroll_x = 0, scroll_y = 0, wheel_times = 1 } = action as any;

  // Mover mouse para posição (se especificado)
  if (x > 0 || y > 0) {
    await page.mouse.move(x, y);
  }

  // Executar scroll
  for (let i = 0; i < wheel_times; i++) {
    await page.mouse.wheel(scroll_x, scroll_y);
  }
}

/**
 * Executa uma ação de pressionar tecla
 */
async function executeKeypressAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'keypress') {
    throw new Error('Invalid action type for keypress');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const { keys } = action as any;

  // Pressionar teclas em sequência (para combinações)
  for (const key of keys) {
    await page.keyboard.down(key);
  }

  // Soltar teclas em ordem reversa
  for (const key of keys.reverse()) {
    await page.keyboard.up(key);
  }
}

/**
 * Executa uma ação de espera
 */
async function executeWaitAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'wait') {
    throw new Error('Invalid action type for wait');
  }

  const { duration } = action as any;
  await new Promise(resolve => setTimeout(resolve, duration * 1000));
}

/**
 * Executa uma ação de screenshot
 */
async function executeScreenshotAction(
  sessionId: string,
  action: ComputerAction
): Promise<string> {
  if (action.type !== 'screenshot') {
    throw new Error('Invalid action type for screenshot');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const screenshot = await page.screenshot({ encoding: 'base64' });

  return screenshot as string;
}

/**
 * Executa uma ação de arrastar
 */
async function executeDragAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  if (action.type !== 'drag') {
    throw new Error('Invalid action type for drag');
  }

  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) {
    throw new Error('Browser not initialized for this session');
  }

  const { page } = browserInstance;
  const { from_x, from_y, to_x, to_y } = action as any;

  await page.mouse.move(from_x, from_y);
  await page.mouse.down();
  await page.mouse.move(to_x, to_y);
  await page.mouse.up();
}

/**
 * Executa uma ação genérica do computador
 */
async function executeComputerAction(
  sessionId: string,
  action: ComputerAction
): Promise<void> {
  // Verificar segurança da ação
  const safetyResult = isActionSafe(action);
  if (!safetyResult.safe) {
    throw new Error(`Unsafe action blocked: ${safetyResult.reason}`);
  }

  // Executar ação baseada no tipo
  switch (action.type) {
    case 'click':
    case 'double_click':
    case 'triple_click':
      await executeClickAction(sessionId, action);
      break;

    case 'type':
      await executeTypeAction(sessionId, action);
      break;

    case 'scroll':
      await executeScrollAction(sessionId, action);
      break;

    case 'keypress':
      await executeKeypressAction(sessionId, action);
      break;

    case 'wait':
      await executeWaitAction(sessionId, action);
      break;

    case 'screenshot':
      const screenshot = await executeScreenshotAction(sessionId, action);
      const session = getCUASession(sessionId);
      if (session) {
        session.lastScreenshot = screenshot;
      }
      break;

    case 'drag':
      await executeDragAction(sessionId, action);
      break;

    default:
      throw new Error(`Unknown action type: ${(action as any).type}`);
  }
}

// ============================================
// LOOP PRINCIPAL CUA
// ============================================

/**
 * Executa um passo do loop CUA
 */
export async function executeCUAStep(
  params: ExecuteCUAActionParams
): Promise<{
  response: OpenAIResponse;
  actionsExecuted: number;
  pendingSafetyChecks: SafetyCheck[];
}> {
  const session = getCUASession(params.sessionId);
  if (!session) {
    throw new Error(`Session not found: ${params.sessionId}`);
  }

  // Aplicar confirmações de segurança se fornecidas
  if (params.acknowledgedSafetyChecks && params.acknowledgedSafetyChecks.length > 0) {
    const acknowledgedIds = params.acknowledgedSafetyChecks.map(c => c.id);
    session.pendingSafetyChecks = session.pendingSafetyChecks.filter(
      check => !acknowledgedIds.includes(check.id)
    );
  }

  // Se houver verificações pendentes, não continuar
  if (session.pendingSafetyChecks.length > 0) {
    throw new Error(formatSafetyMessage(session.pendingSafetyChecks));
  }

  // Chamar API OpenAI
  const response = await callOpenAICUA(session);

  // Processar resposta
  let actionsExecuted = 0;
  const newSafetyChecks: SafetyCheck[] = [];

  for (const item of response.output) {
    if (item.type === 'computer_call') {
      const callItem = item as ComputerCallItem;

      // Verificar se há pending safety checks
      if (callItem.pending_safety_checks && callItem.pending_safety_checks.length > 0) {
        newSafetyChecks.push(...callItem.pending_safety_checks);
        continue;
      }

      // Executar ação
      if (callItem.status === 'completed') {
        try {
          await executeComputerAction(params.sessionId, callItem.action);
          actionsExecuted++;
          session.lastCallId = callItem.call_id;
        } catch (error: any) {
          console.error(`Error executing action: ${error.message}`);
        }
      }
    }
  }

  // Capturar screenshot após ações
  if (actionsExecuted > 0) {
    const browserInstance = browserInstances.get(params.sessionId);
    if (browserInstance) {
      const screenshot = await browserInstance.page.screenshot({ encoding: 'base64' });
      session.lastScreenshot = screenshot as string;
    }
  }

  // Atualizar pending safety checks
  session.pendingSafetyChecks = newSafetyChecks;

  return {
    response,
    actionsExecuted,
    pendingSafetyChecks: newSafetyChecks
  };
}

/**
 * Obtém URL atual do browser (se aplicável)
 */
export async function getCurrentURL(sessionId: string): Promise<string | null> {
  const browserInstance = browserInstances.get(sessionId);
  if (!browserInstance) return null;

  return browserInstance.page.url();
}

