#!/usr/bin/env node

/**
 * Servidor MCP para OpenAI Computer Use Agent (CUA)
 * 
 * Este servidor MCP expõe ferramentas para controle completo de desktop
 * via agente de IA da OpenAI, incluindo:
 * - Iniciar sessões CUA
 * - Executar ações do computador
 * - Gerenciar verificações de segurança
 * - Monitorar estado das sessões
 * 
 * @author Claudio - DesktopGPT Integration
 * @version 1.0.0
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  Tool
} from '@modelcontextprotocol/sdk/types.js';

import {
  initializeOpenAI,
  createCUASession,
  getCUASession,
  closeCUASession,
  executeCUAStep,
  getCurrentURL
} from './cua-handler.js';

import {
  StartCUASessionParams,
  ExecuteCUAActionParams,
  GetCUASessionParams,
  StopCUASessionParams
} from './types.js';

// ============================================
// CONFIGURAÇÃO DO SERVIDOR
// ============================================

const SERVER_NAME = 'openai-cua-mcp';
const SERVER_VERSION = '1.0.0';

// ============================================
// FERRAMENTAS MCP DISPONÍVEIS
// ============================================

const TOOLS: Tool[] = [
  {
    name: 'start_cua_session',
    description: 'Inicia uma nova sessão do Computer Use Agent (CUA) da OpenAI. ' +
                 'Cria um ambiente controlado onde o agente pode interagir com o desktop, ' +
                 'navegador ou aplicativos. Retorna um sessionId que deve ser usado nas ' +
                 'próximas chamadas.',
    inputSchema: {
      type: 'object',
      properties: {
        initialPrompt: {
          type: 'string',
          description: 'Prompt inicial que descreve a tarefa que o agente deve executar. ' +
                      'Exemplo: "Pesquise as últimas notícias sobre IA no Google"'
        },
        environment: {
          type: 'string',
          enum: ['browser', 'mac', 'windows', 'ubuntu'],
          description: 'Tipo de ambiente onde o agente irá operar. ' +
                      'Padrão: "browser" (ambiente de navegação web)',
          default: 'browser'
        },
        displayWidth: {
          type: 'number',
          description: 'Largura da tela em pixels. Padrão: 1024',
          default: 1024
        },
        displayHeight: {
          type: 'number',
          description: 'Altura da tela em pixels. Padrão: 768',
          default: 768
        },
        includeInitialScreenshot: {
          type: 'boolean',
          description: 'Se true, captura um screenshot inicial do ambiente. Padrão: false',
          default: false
        }
      },
      required: ['initialPrompt']
    }
  },
  {
    name: 'execute_cua_action',
    description: 'Executa o próximo passo do loop CUA. O agente receberá o estado atual, ' +
                 'decidirá a próxima ação, e a executará. Este método deve ser chamado ' +
                 'repetidamente até que o agente complete a tarefa ou pare de retornar ações.',
    inputSchema: {
      type: 'object',
      properties: {
        sessionId: {
          type: 'string',
          description: 'ID da sessão CUA (retornado por start_cua_session)'
        },
        acknowledgedSafetyChecks: {
          type: 'array',
          description: 'Lista de verificações de segurança confirmadas pelo usuário. ' +
                      'Necessário quando o agente retorna pending_safety_checks.',
          items: {
            type: 'object',
            properties: {
              id: { type: 'string' },
              code: { type: 'string' },
              message: { type: 'string' }
            },
            required: ['id', 'code', 'message']
          }
        }
      },
      required: ['sessionId']
    }
  },
  {
    name: 'get_cua_session',
    description: 'Obtém informações detalhadas sobre uma sessão CUA ativa, incluindo ' +
                 'histórico de conversação, último screenshot, ações pendentes e estado atual.',
    inputSchema: {
      type: 'object',
      properties: {
        sessionId: {
          type: 'string',
          description: 'ID da sessão CUA'
        }
      },
      required: ['sessionId']
    }
  },
  {
    name: 'stop_cua_session',
    description: 'Encerra uma sessão CUA ativa, fechando o browser e liberando recursos. ' +
                 'Esta operação não pode ser desfeita.',
    inputSchema: {
      type: 'object',
      properties: {
        sessionId: {
          type: 'string',
          description: 'ID da sessão CUA a ser encerrada'
        }
      },
      required: ['sessionId']
    }
  }
];

// ============================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================

async function main() {
  console.error('🚀 Iniciando OpenAI CUA MCP Server...');

  // Verificar API Key
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    console.error('❌ ERRO: OPENAI_API_KEY não está configurada!');
    console.error('   Configure a variável de ambiente antes de iniciar o servidor.');
    process.exit(1);
  }

  // Inicializar cliente OpenAI
  initializeOpenAI(apiKey);
  console.error('✅ Cliente OpenAI inicializado');

  // Criar servidor MCP
  const server = new Server(
    {
      name: SERVER_NAME,
      version: SERVER_VERSION
    },
    {
      capabilities: {
        tools: {}
      }
    }
  );

  // ============================================
  // HANDLER: Listar Ferramentas
  // ============================================

  server.setRequestHandler(ListToolsRequestSchema, async () => {
    console.error('📋 Cliente solicitou lista de ferramentas');
    return { tools: TOOLS };
  });

  // ============================================
  // HANDLER: Executar Ferramenta
  // ============================================

  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;

    console.error(`🔧 Executando ferramenta: ${name}`);
    console.error(`   Argumentos: ${JSON.stringify(args, null, 2)}`);

    try {
      switch (name) {
        // ==========================================
        // START CUA SESSION
        // ==========================================
        case 'start_cua_session': {
          const params = args as unknown as StartCUASessionParams;

          console.error(`   📝 Iniciando sessão CUA com prompt: "${params.initialPrompt.substring(0, 50)}..."`);

          const session = await createCUASession(params);

          console.error(`   ✅ Sessão criada: ${session.sessionId}`);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  success: true,
                  sessionId: session.sessionId,
                  environment: session.environment,
                  displaySize: `${session.displayWidth}x${session.displayHeight}`,
                  message: 'Sessão CUA iniciada com sucesso! Use execute_cua_action para começar.'
                }, null, 2)
              }
            ]
          };
        }

        // ==========================================
        // EXECUTE CUA ACTION
        // ==========================================
        case 'execute_cua_action': {
          const params = args as unknown as ExecuteCUAActionParams;

          console.error(`   ⚡ Executando passo CUA para sessão: ${params.sessionId}`);

          const result = await executeCUAStep(params);

          console.error(`   ✅ Executadas ${result.actionsExecuted} ações`);

          if (result.pendingSafetyChecks.length > 0) {
            console.error(`   ⚠️  ${result.pendingSafetyChecks.length} verificações de segurança pendentes`);
          }

          // Obter URL atual se disponível
          const currentUrl = await getCurrentURL(params.sessionId);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  success: true,
                  actionsExecuted: result.actionsExecuted,
                  pendingSafetyChecks: result.pendingSafetyChecks,
                  currentUrl: currentUrl,
                  hasMoreActions: result.response.output.some(
                    (item: any) => item.type === 'computer_call' && item.status === 'completed'
                  ),
                  message: result.pendingSafetyChecks.length > 0
                    ? 'Ações pendentes de confirmação de segurança. Use acknowledgedSafetyChecks para continuar.'
                    : `${result.actionsExecuted} ações executadas com sucesso.`
                }, null, 2)
              }
            ]
          };
        }

        // ==========================================
        // GET CUA SESSION
        // ==========================================
        case 'get_cua_session': {
          const params = args as unknown as GetCUASessionParams;

          console.error(`   🔍 Obtendo informações da sessão: ${params.sessionId}`);

          const session = getCUASession(params.sessionId);

          if (!session) {
            return {
              content: [
                {
                  type: 'text',
                  text: JSON.stringify({
                    exists: false,
                    message: `Sessão ${params.sessionId} não encontrada ou foi encerrada.`
                  }, null, 2)
                }
              ]
            };
          }

          const currentUrl = await getCurrentURL(params.sessionId);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  exists: true,
                  sessionId: session.sessionId,
                  isActive: session.isActive,
                  environment: session.environment,
                  displaySize: `${session.displayWidth}x${session.displayHeight}`,
                  conversationLength: session.conversationHistory.length,
                  hasScreenshot: !!session.lastScreenshot,
                  pendingSafetyChecks: session.pendingSafetyChecks.length,
                  currentUrl: currentUrl,
                  message: 'Sessão encontrada e ativa.'
                }, null, 2)
              }
            ]
          };
        }

        // ==========================================
        // STOP CUA SESSION
        // ==========================================
        case 'stop_cua_session': {
          const params = args as unknown as StopCUASessionParams;

          console.error(`   🛑 Encerrando sessão: ${params.sessionId}`);

          await closeCUASession(params.sessionId);

          console.error(`   ✅ Sessão encerrada com sucesso`);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  success: true,
                  message: `Sessão ${params.sessionId} encerrada com sucesso.`
                }, null, 2)
              }
            ]
          };
        }

        default:
          throw new Error(`Ferramenta desconhecida: ${name}`);
      }

    } catch (error: any) {
      console.error(`   ❌ Erro ao executar ${name}: ${error.message}`);

      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              success: false,
              error: error.message,
              message: `Erro ao executar ${name}: ${error.message}`
            }, null, 2)
          }
        ],
        isError: true
      };
    }
  });

  // ============================================
  // INICIAR TRANSPORTE STDIO
  // ============================================

  const transport = new StdioServerTransport();
  await server.connect(transport);

  console.error('✅ Servidor MCP conectado e pronto!');
  console.error('   Aguardando requisições do cliente...');
}

// ============================================
// TRATAMENTO DE ERROS E SINAIS
// ============================================

process.on('SIGINT', async () => {
  console.error('\n🛑 Recebido SIGINT, encerrando servidor...');
  process.exit(0);
});

process.on('SIGTERM', async () => {
  console.error('\n🛑 Recebido SIGTERM, encerrando servidor...');
  process.exit(0);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('❌ Unhandled Rejection:', reason);
});

process.on('uncaughtException', (error) => {
  console.error('❌ Uncaught Exception:', error);
  process.exit(1);
});

// ============================================
// EXECUTAR
// ============================================

main().catch((error) => {
  console.error('❌ Erro fatal ao iniciar servidor:', error);
  process.exit(1);
});

