function Write-Status {
    param(
        [string]$Message,
        [string]$Type = "Info"
    )

    switch ($Type) {
        "Success" { Write-Host "✓ $Message" -ForegroundColor Green }
        "Error"   { Write-Host "✗ $Message" -ForegroundColor Red }
        "Warning" { Write-Host "⚠ $Message" -ForegroundColor Yellow }
        "Info"    { Write-Host "ℹ $Message" -ForegroundColor Cyan }
        "Step"    { Write-Host "`n► $Message" -ForegroundColor Magenta }
    }
}

# Função para verificar se comando existe
function Test-Command {
    param([string]$Command)
    try {
        if (Get-Command $Command -ErrorAction Stop) { return $true }
    } catch {
        return $false
    }
}

# Função para pausar e aguardar input
function Pause-Script {
    Write-Host "`nPressione qualquer tecla para continuar..." -ForegroundColor Yellow
    $null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
}

# =========================================
# 1. VERIFICAÇÃO DE PRÉ-REQUISITOS
# =========================================
Write-Status "Verificando pré-requisitos..." "Step"

# Verifica Git
if (-not (Test-Command "git")) {
    Write-Status "Git não encontrado! Por favor, instale o Git primeiro." "Error"
    Write-Host "Download: https://git-scm.com/download/win" -ForegroundColor Yellow
    Pause-Script
    exit 1
}
Write-Status "Git encontrado" "Success"

# Verifica Python
if (-not (Test-Command "python")) {
    Write-Status "Python não encontrado! Por favor, instale o Python 3.8+ primeiro." "Error"
    Write-Host "Download: https://www.python.org/downloads/" -ForegroundColor Yellow
    Pause-Script
    exit 1
}

$pythonVersion = python --version
Write-Status "Python encontrado: $pythonVersion" "Success"

# Verifica pip
if (-not (Test-Command "pip")) {
    Write-Status "pip não encontrado!" "Error"
    Pause-Script
    exit 1
}
Write-Status "pip encontrado" "Success"

# =========================================
# 2. CRIAÇÃO DA ESTRUTURA DE DIRETÓRIOS
# =========================================
Write-Status "Criando estrutura de diretórios..." "Step"

# Verifica se drive Z: existe
if (-not (Test-Path "Z:\")) {
