from flask import Flask, request, jsonify
import requests
import subprocess
import os

app = Flask(__name__)

@app.route("/function_call", methods=["POST"])
def handle_function_call():
    data = request.json
    name = data.get("name")
    params = data.get("parameters", {})

    try:
        if name == "windows_open_file":
            keyword = params.get("keyword")
            os.startfile(keyword)
            return jsonify({"status": "success", "message": f"Abrindo {keyword}"})

        elif name == "windows_search_files":
            keyword = params.get("keyword")
            file_type = params.get("file_type", "")
            # Aqui você pode implementar uma busca real com glob ou os.walk se quiser
            return jsonify({"status": "success", "files": [f"{keyword}.{file_type or 'txt'}"]})

        elif name == "windows_get_file_content":
            keyword = params.get("keyword")
            with open(keyword, "r", encoding="utf-8") as f:
                content = f.read()
            return jsonify({"status": "success", "content": content})

        elif name == "search_web":
            query = params.get("query")
            url = f"https://api.duckduckgo.com/?q={query}&format=json&no_redirect=1&no_html=1"
            response = requests.get(url)
            result = response.json()
            abstract = result.get("Abstract") or result.get("RelatedTopics", [{}])[0].get("Text", "Nenhum resultado encontrado.")
            return jsonify({"status": "success", "result": abstract})

        else:
            return jsonify({"status": "error", "message": f"Função '{name}' não reconhecida."})

    except Exception as e:
        return jsonify({"status": "error", "message": str(e)})

if __name__ == "__main__":
    app.run(port=5005)

