import requests
import json

OLLAMA_MODEL = "rlufti/fazai"
OLLAMA_URL = "http://localhost:11434/api/generate"
SERVER_URL = "http://localhost:5005/function_call"

def format_prompt(user_input):
    with open("template.txt", "r", encoding="utf-8") as f:
        template = f.read()
    return template.replace("{{ .Prompt }}", user_input)

def query_model(prompt):
    payload = {
        "model": OLLAMA_MODEL,
        "prompt": prompt,
        "stream": False
    }
    response = requests.post(OLLAMA_URL, json=payload)
    return response.json()["response"]

def call_function(json_call):
    response = requests.post(SERVER_URL, json=json.loads(json_call))
    return response.json()

def main():
    print("🤖 FazAI conectado. Digite um comando (ex: 'Abra o explorador de arquivos do Windows'):")
    while True:
        user_input = input("🗣️ > ")
        if user_input.lower() in ["sair", "exit", "quit"]:
            break
        prompt = format_prompt(user_input)
        model_response = query_model(prompt)
        print(f"📦 Resposta do modelo:\n{model_response}")
        try:
            result = call_function(model_response)
            print(f"✅ Execução: {result.get('message') or result.get('content')}")
        except Exception as e:
            print(f"⚠️ Erro ao executar: {e}")

if __name__ == "__main__":
    main()

