"""
FazAI Proxy - Intercepta chamadas do Ollama e adiciona function calling
Modo Colonial Ativado! 🏴‍☠️
"""

from flask import Flask, request, jsonify, Response
import requests
import json
import re
import os

app = Flask(__name__)

OLLAMA_URL = "http://localhost:11434"
FUNCTIONS_SERVER = "http://localhost:5005/function_call"
MODEL_NAME = "fazai"

# Funções disponíveis
AVAILABLE_FUNCTIONS = {
    "windows_open_file": {
        "description": "Abre um arquivo ou aplicativo no Windows",
        "parameters": ["keyword"]
    },
    "windows_search_files": {
        "description": "Busca arquivos no sistema",
        "parameters": ["keyword", "file_type"]
    },
    "windows_get_file_content": {
        "description": "Lê conteúdo de um arquivo",
        "parameters": ["keyword"]
    },
    "search_web": {
        "description": "Busca na web",
        "parameters": ["query"]
    }
}

def extract_function_call(text):
    """Tenta extrair uma chamada de função do texto do modelo"""
    # Procura por JSON no formato {"name": "...", "parameters": {...}}
    json_pattern = r'\{[^{}]*"name"\s*:\s*"([^"]+)"[^{}]*"parameters"\s*:\s*\{[^}]*\}[^{}]*\}'
    match = re.search(json_pattern, text, re.DOTALL)

    if match:
        try:
            json_str = match.group(0)
            return json.loads(json_str)
        except:
            pass

    return None

def execute_function(func_call):
    """Executa uma função no servidor de funções"""
    try:
        response = requests.post(FUNCTIONS_SERVER, json=func_call, timeout=10)
        return response.json()
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.route('/api/generate', methods=['POST'])
def generate():
    """Proxy para /api/generate com function calling"""
    data = request.json

    # Adiciona informações sobre funções disponíveis no prompt
