function generateString() {
    const length = parseInt(document.getElementById('length').value);
    const charsetType = document.getElementById('charset').value;
    const combiningChar = '\u0338'; // U+0338 combining long solidus overlay

    let result = '';
    let hexResult = '';

    for (let i = 0; i < length; i++) {
        const chineseChar = getRandomChineseChar(charsetType);
        const combined = chineseChar + combiningChar;
        result += combined;

        // Versão em códigos hex para notepad
        for (let j = 0; j < combined.length; j++) {
            const codePoint = combined.codePointAt(j);
            if (codePoint > 0xFFFF) {
                hexResult += '\\U' + codePoint.toString(16).toUpperCase().padStart(8, '0');
                j++; // Skip next surrogate pair
            } else {
                hexResult += '\\u' + codePoint.toString(16).toUpperCase().padStart(4, '0');
            }
        }
    }

    document.getElementById('result').value = hexResult;

