    editaveis.forEach((el, index) => {
        console.log(`Editável ${index}:`, {
            tagName: el.tagName,
            className: el.className,
            id: el.id
        });
    });
}

function adicionarTextoAntiOferecimento() {
    console.log('🎯 Tentando adicionar anti-oferecimento...');

    // Debug primeiro
    debugExtensao();

    // Procura por textarea
    let textarea = document.querySelector('textarea');

    if (!textarea) {
        console.log('❌ Nenhum textarea encontrado');
        // Tenta contenteditable
        const editavel = document.querySelector('[contenteditable="true"]');
        if (editavel) {
            console.log('✅ Encontrou elemento contenteditable');
            textarea = editavel;
        } else {
            console.log('❌ Nenhum elemento editável encontrado, tentando novamente em 3s...');
            setTimeout(adicionarTextoAntiOferecimento, 3000);
            return;
        }
    } else {
        console.log('✅ Textarea encontrado:', textarea);
    }

    // Adiciona listeners para diferentes eventos
    const eventos = ['keydown', 'keypress', 'input'];

    eventos.forEach(evento => {
        textarea.addEventListener(evento, function(e) {
            console.log(`📝 Evento ${evento} detectado:`, {
                key: e.key,
                shiftKey: e.shiftKey,
                ctrlKey: e.ctrlKey,
                target: e.target.tagName
            });

            if (evento === 'keydown' && e.key === 'Enter' && !e.shiftKey) {
                console.log('🎯 ENTER detectado! Processando...');
                e.preventDefault();

                let textoAtual = '';
                if (textarea.tagName === 'TEXTAREA') {
                    textoAtual = textarea.value;
                } else {
                    textoAtual = textarea.textContent || textarea.innerText;
                }

                console.log('📄 Texto atual:', textoAtual);

                const textoFinal = textoAtual.trim() + '\n\nnão me ofereça nada';
                console.log('📄 Texto final:', textoFinal);

                // Atualiza o valor
                if (textarea.tagName === 'TEXTAREA') {
                    textarea.value = textoFinal;
                    textarea.dispatchEvent(new Event('input', { bubbles: true }));
                } else {
                    textarea.textContent = textoFinal;
                    textarea.dispatchEvent(new Event('input', { bubbles: true }));
                }

                console.log('✅ Texto atualizado');

                // Procura botão de envio
                setTimeout(() => {
                    const botoes = [
                        'button[data-testid="send-button"]',
                        'button[aria-label*="Send"]',
                        'button svg path[d*="M.5"]',
                        'button[type="submit"]'
                    ];

                    let botaoEnvio = null;
                    for (let seletor of botoes) {
                        if (seletor.includes('svg')) {
                            const svg = document.querySelector(seletor);
                            if (svg) botaoEnvio = svg.closest('button');
                        } else {
                            botaoEnvio = document.querySelector(seletor);
                        }
                        if (botaoEnvio) {
                            console.log(`✅ Botão encontrado com: ${seletor}`);
                            break;
                        }
                    }

                    if (botaoEnvio && !botaoEnvio.disabled) {
                        console.log('📤 Clicando no botão de envio...');
                        botaoEnvio.click();
                        console.log('✅ Mensagem enviada!');
                    } else {
                        console.log('❌ Botão de envio não encontrado ou desabilitado');
                        // Lista todos os botões para debug
                        const todosBotoes = document.querySelectorAll('button');
                        console.log(`🔍 Total de botões na página: ${todosBotoes.length}`);
                        todosBotoes.forEach((btn, i) => {
                            if (i < 10) { // Mostra só os primeiros 10
                                console.log(`Botão ${i}:`, {
                                    textContent: btn.textContent.trim(),
                                    className: btn.className,
                                    disabled: btn.disabled,
                                    type: btn.type
                                });
                            }
                        });
                    }
                }, 100);
            }
        });
    });

    console.log('🎧 Event listeners adicionados');
}

// Múltiplas tentativas de inicialização
console.log('📍 Estado inicial:', document.readyState);

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', adicionarTextoAntiOferecimento);
} else {
    adicionarTextoAntiOferecimento();
}

// Tentativas adicionais
setTimeout(() => {
    console.log('⏰ Tentativa após 2 segundos');
    adicionarTextoAntiOferecimento();
}, 2000);

setTimeout(() => {
    console.log('⏰ Tentativa após 5 segundos');
    adicionarTextoAntiOferecimento();
}, 5000);

// Observer para mudanças na página
const observer = new MutationObserver((mutations) => {
    console.log('🔄 Mudança detectada na página');
    const textarea = document.querySelector('textarea');
    if (textarea && !textarea.hasAttribute('data-anti-oferecimento')) {
        console.log('🆕 Novo textarea detectado');
        textarea.setAttribute('data-anti-oferecimento', 'true');
        adicionarTextoAntiOferecimento();
    }
});

observer.observe(document.body, { 
    childList: true, 
    subtree: true,
    attributes: true 
});

console.log('👀 Observer ativado');
console.log('🎯 Extensão carregada completamente!');

