// VERSION FILE LOGGER - salva logs em arquivo
console.log('🚀 Extensão Anti-Oferecimento iniciando...');

// Sistema de log para arquivo
class FileLogger {
    constructor() {
        this.logs = [];
        this.startTime = new Date().toISOString();
    }

    log(message, data = null) {
        const timestamp = new Date().toISOString();
        const logEntry = {
            timestamp,
            message,
            data: data ? JSON.stringify(data, null, 2) : null
        };

        this.logs.push(logEntry);
        console.log(message, data || '');

        // Auto-save a cada 10 logs
        if (this.logs.length % 10 === 0) {
            this.saveToFile();
        }
    }

    saveToFile() {
        const logContent = this.logs.map(entry => {
            let line = `[${entry.timestamp}] ${entry.message}`;
            if (entry.data) {
                line += `\nDATA: ${entry.data}`;
            }
            return line;
        }).join('\n\n');

        const blob = new Blob([logContent], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        a.download = `chatgpt-extension-debug-${this.startTime.replace(/[:.]/g, '-')}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        console.log('📁 Log salvo em arquivo!');
    }

    forceSave() {
        this.saveToFile();
    }
}

const logger = new FileLogger();

function debugExtensao() {
    logger.log('=== DEBUG INICIADO ===');
    logger.log('URL atual: ' + window.location.href);
    logger.log('Document ready state: ' + document.readyState);

    // Testa todos os seletores possíveis
    const seletores = [
        'textarea[placeholder*="Message"]',
        'textarea[data-id="root"]', 
        '#prompt-textarea',
        'textarea',
        'div[contenteditable="true"]',
        '[data-testid="textbox"]',
        '.ProseMirror'
    ];

    logger.log('🔍 Procurando elementos...');
    const resultados = {};

    seletores.forEach(seletor => {
        const elemento = document.querySelector(seletor);
        const encontrado = elemento ? 'ENCONTRADO' : 'NÃO ENCONTRADO';
        logger.log(`${seletor}: ${encontrado}`);

        if (elemento) {
            const info = {
                tipo: elemento.tagName,
                classes: elemento.className,
                id: elemento.id,
                placeholder: elemento.placeholder || 'N/A'
            };
            logger.log('Detalhes do elemento:', info);
            resultados[seletor] = info;
        }
    });

    // Lista TODOS os textareas da página
    const todosTextareas = document.querySelectorAll('textarea');
    logger.log(`📝 Total de textareas encontrados: ${todosTextareas.length}`);

    const textareaInfo = [];
    todosTextareas.forEach((textarea, index) => {
        const info = {
            index,
            placeholder: textarea.placeholder,
            id: textarea.id,
            className: textarea.className,
            value: textarea.value.substring(0, 100) // Primeiros 100 chars
        };
        textareaInfo.push(info);
    });

    if (textareaInfo.length > 0) {
        logger.log('📝 Detalhes dos textareas:', textareaInfo);
    }

    // Lista elementos contenteditable
    const editaveis = document.querySelectorAll('[contenteditable="true"]');
    logger.log(`✏️ Elementos contenteditable: ${editaveis.length}`);

    const editaveisInfo = [];
    editaveis.forEach((el, index) => {
