    }

    // Força salvar o debug inicial
    logger.forceSave();
}

function adicionarTextoAntiOferecimento() {
    logger.log('🎯 Tentando adicionar anti-oferecimento...');

    // Debug primeiro
    debugExtensao();

    // Procura por textarea
    let textarea = document.querySelector('textarea');

    if (!textarea) {
        logger.log('❌ Nenhum textarea encontrado');
        // Tenta contenteditable
        const editavel = document.querySelector('[contenteditable="true"]');
        if (editavel) {
            logger.log('✅ Encontrou elemento contenteditable');
            textarea = editavel;
        } else {
            logger.log('❌ Nenhum elemento editável encontrado, tentando novamente em 3s...');
            setTimeout(adicionarTextoAntiOferecimento, 3000);
            return;
        }
    } else {
        logger.log('✅ Textarea encontrado:', {
            tagName: textarea.tagName,
            id: textarea.id,
            className: textarea.className
        });
    }

    // Adiciona listeners para diferentes eventos
    const eventos = ['keydown', 'keypress', 'input'];

    eventos.forEach(evento => {
        textarea.addEventListener(evento, function(e) {
            const eventInfo = {
                evento,
                key: e.key,
                shiftKey: e.shiftKey,
                ctrlKey: e.ctrlKey,
                target: e.target.tagName
            };

            logger.log(`📝 Evento detectado:`, eventInfo);

            if (evento === 'keydown' && e.key === 'Enter' && !e.shiftKey) {
                logger.log('🎯 ENTER detectado! Processando...');
                e.preventDefault();

                let textoAtual = '';
                if (textarea.tagName === 'TEXTAREA') {
                    textoAtual = textarea.value;
                } else {
                    textoAtual = textarea.textContent || textarea.innerText;
                }

                logger.log('📄 Texto atual: ' + textoAtual);

                const textoFinal = textoAtual.trim() + '\n\nnão me ofereça nada';
                logger.log('📄 Texto final: ' + textoFinal);

                // Atualiza o valor
                if (textarea.tagName === 'TEXTAREA') {
                    textarea.value = textoFinal;
                    textarea.dispatchEvent(new Event('input', { bubbles: true }));
                } else {
                    textarea.textContent = textoFinal;
                    textarea.dispatchEvent(new Event('input', { bubbles: true }));
                }

                logger.log('✅ Texto atualizado');

                // Procura botão de envio
                setTimeout(() => {
                    const botoes = [
                        'button[data-testid="send-button"]',
                        'button[aria-label*="Send"]',
                        'button svg path[d*="M.5"]',
                        'button[type="submit"]'
                    ];

                    let botaoEnvio = null;
                    for (let seletor of botoes) {
                        if (seletor.includes('svg')) {
                            const svg = document.querySelector(seletor);
                            if (svg) botaoEnvio = svg.closest('button');
                        } else {
                            botaoEnvio = document.querySelector(seletor);
                        }
                        if (botaoEnvio) {
                            logger.log(`✅ Botão encontrado com: ${seletor}`);
                            break;
                        }
                    }

                    if (botaoEnvio && !botaoEnvio.disabled) {
                        logger.log('📤 Clicando no botão de envio...');
                        botaoEnvio.click();
                        logger.log('✅ Mensagem enviada!');

                        // Força salvar após envio
                        logger.forceSave();
                    } else {
                        logger.log('❌ Botão de envio não encontrado ou desabilitado');

                        // Lista todos os botões para debug
                        const todosBotoes = document.querySelectorAll('button');
                        logger.log(`🔍 Total de botões na página: ${todosBotoes.length}`);

                        const botoesInfo = [];
                        todosBotoes.forEach((btn, i) => {
                            if (i < 10) { // Primeiros 10
                                botoesInfo.push({
                                    index: i,
                                    textContent: btn.textContent.trim(),
                                    className: btn.className,
                                    disabled: btn.disabled,
                                    type: btn.type
                                });
                            }
                        });

                        logger.log('🔍 Botões encontrados:', botoesInfo);
                        logger.forceSave();
                    }
                }, 100);
            }
        });
    });

    logger.log('🎧 Event listeners adicionados');
}

// Múltiplas tentativas de inicialização
logger.log('📍 Estado inicial: ' + document.readyState);

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', adicionarTextoAntiOferecimento);
} else {
    adicionarTextoAntiOferecimento();
}

// Tentativas adicionais
setTimeout(() => {
    logger.log('⏰ Tentativa após 2 segundos');
    adicionarTextoAntiOferecimento();
}, 2000);

setTimeout(() => {
    logger.log('⏰ Tentativa após 5 segundos');
    adicionarTextoAntiOferecimento();
}, 5000);

// Observer para mudanças na página
const observer = new MutationObserver((mutations) => {
    logger.log('🔄 Mudança detectada na página');
    const textarea = document.querySelector('textarea');
    if (textarea && !textarea.hasAttribute('data-anti-oferecimento')) {
        logger.log('🆕 Novo textarea detectado');
        textarea.setAttribute('data-anti-oferecimento', 'true');
        adicionarTextoAntiOferecimento();
    }
});

observer.observe(document.body, { 
    childList: true, 
    subtree: true,
    attributes: true 
});

logger.log('👀 Observer ativado');
logger.log('🎯 Extensão carregada completamente!');

// Força uma última tentativa após 10 segundos e salva tudo
setTimeout(() => {
    logger.log('⏰ Tentativa final após 10 segundos');
    adicionarTextoAntiOferecimento();

    // Salva todos os logs finais
    setTimeout(() => {
        logger.forceSave();
    }, 1000);
}, 10000);

