    parameters: {
      type: "object",
      properties: {
        name: {
          type: "string",
          description: "Name of the application to launch"
        }
      },
      required: ["name"]
    }
  },
  {
    name: "Powershell-Tool",
    description: "Execute PowerShell commands and return the output with status code",
    parameters: {
      type: "object",
      properties: {
        command: {
          type: "string",
          description: "PowerShell command to execute"
        }
      },
      required: ["command"]
    }
  },

{
  name: "State-Tool",
  description: "Capture comprehensive desktop state including focused/opened applications, interactive UI elements, and content. Optionally includes visual screenshot when use_vision=True",
  parameters: {
    type: "object",
    properties: {
      use_vision: {
        type: "boolean",
        description: "Include visual screenshot",
        default: false
      }
    }
  }
},
{
  name: "Click-Tool",
  description: "Click on UI elements at specific coordinates. Supports left/right/middle mouse buttons and single/double/triple clicks",
  parameters: {
    type: "object",
    properties: {
      loc: {
        type: "array",
        items: { type: "integer" },
        minItems: 2,
        maxItems: 2,
        description: "X,Y coordinates"
      },
      button: {
        type: "string",
        enum: ["left", "right", "middle"],
        default: "left"
      },
      clicks: {
        type: "integer",
        default: 1
      }
    },
    required: ["loc"]
  }
},

  {
    name: "Type-Tool",
    description: "Type text into input fields. Set clear=True to replace text, False to append",
    parameters: {
      type: "object",
      properties: {
        loc: { type: "array", items: { type: "integer" }, minItems: 2, maxItems: 2 },
        text: { type: "string" },
        clear: { type: "boolean", default: false }
      },
      required: ["loc", "text"]
    }
  },
  {
    name: "read_file",
    description: "Read file contents from Windows filesystem",
    parameters: {
      type: "object",
      properties: {
        path: { type: "string", description: "Absolute file path" }
      },
      required: ["path"]
    }
  },
  {
    name: "write_file",
    description: "Write or append to files",
    parameters: {
      type: "object",
      properties: {
        path: { type: "string" },
        content: { type: "string" },
        mode: { type: "string", enum: ["rewrite", "append"], default: "rewrite" }
      },
      required: ["path", "content"]
    }
  },
  {
    name: "list_directory",
    description: "List files and directories at path",
    parameters: {
      type: "object",
      properties: {
        path: { type: "string" }
      },
