/**
 * ============================================================================
 * AUTH MIDDLEWARE - Middleware de Autenticação Bearer Token
 * ============================================================================
 * Protege endpoints HTTP com token de autenticação simples
 */

import { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

export interface AuthConfig {
  enabled: boolean;
  token?: string;
  headerName?: string;
}

/**
 * Gera token aleatório seguro se não fornecido
 */
export function generateSecureToken(): string {
  return crypto.randomBytes(32).toString('hex');
}

/**
 * Middleware de autenticação Bearer Token
 */
export function authMiddleware(config: AuthConfig) {
  return (req: Request, res: Response, next: NextFunction) => {
    // Se autenticação desabilitada, passa direto
    if (!config.enabled) {
      return next();
    }

    // Permitir endpoint de health sem autenticação
    if (req.path === '/health') {
      return next();
    }

    const headerName = config.headerName || 'Authorization';
    const authHeader = req.headers[headerName.toLowerCase()] as string;

    if (!authHeader) {
      console.log(`❌ [AUTH] Requisição sem header ${headerName}:`, {
        ip: req.ip,
        path: req.path,
        method: req.method
      });
      return res.status(401).json({
        error: 'Unauthorized',
        message: `Missing ${headerName} header`
      });
    }

    // Extrair token do header "Bearer <token>"
    const tokenMatch = authHeader.match(/^Bearer\s+(.+)$/i);
    if (!tokenMatch) {
      console.log('❌ [AUTH] Formato de token inválido:', {
        ip: req.ip,
        header: authHeader.substring(0, 20) + '...'
      });
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Invalid authorization format. Use: Bearer <token>'
      });
    }

    const providedToken = tokenMatch[1];

    // Validar token
    if (providedToken !== config.token) {
      console.log('❌ [AUTH] Token inválido:', {
        ip: req.ip,
        path: req.path,
        providedToken: providedToken.substring(0, 10) + '...'
      });
      return res.status(403).json({
        error: 'Forbidden',
        message: 'Invalid authentication token'
      });
    }

    // Token válido
    console.log('✅ [AUTH] Acesso autorizado:', {
      ip: req.ip,
      path: req.path,
      method: req.method
    });
    next();
  };
}

/**
 * Exibe informações de autenticação no console
 */
export function displayAuthInfo(config: AuthConfig): void {
  console.log('\n╔══════════════════════════════════════════════════════════╗');
  console.log('║              🔐 CONFIGURAÇÃO DE AUTENTICAÇÃO             ║');
  console.log('╚══════════════════════════════════════════════════════════╝');

  if (!config.enabled) {
    console.log('\n⚠️  AUTENTICAÇÃO DESABILITADA');
    console.log('   Servidor acessível sem restrições!');
    console.log('   Recomendado apenas para uso local.\n');
    return;
  }

  console.log('\n✅ AUTENTICAÇÃO HABILITADA\n');
  console.log('Header esperado:');
  console.log(`   ${config.headerName || 'Authorization'}: Bearer <token>`);
  console.log('\n📝 Seu token de acesso:');
  console.log(`   ${config.token}`);
  console.log('\n🔒 Endpoints protegidos: TODOS (exceto /health)');
  console.log('\n📋 Exemplo de uso (cURL):');
  console.log(`   curl -H "Authorization: Bearer ${config.token}" http://localhost:3000/sse`);
  console.log('\n════════════════════════════════════════════════════════════\n');
}

