```python
import ollama
from concurrent.futures import ThreadPoolExecutor
import statistics

def conselho_provisorio():
    modelos = [
        'dolphin-llama3:8b',      # O rebelde
        'wizard-vicuna-uncensored:13b',  # O sábio
        'openchat:7b',            # O equilibrado
        # 'mixtral-uncensored:7b'   # O técnico (se couber)
    ]

    def consulta_quorum(prompt, peso_consenso=True):
        def query_modelo(modelo):
            try:
                response = ollama.chat(model=modelo, messages=[{
                    'role': 'user', 'content': prompt
                }])
                return {
                    'modelo': modelo,
                    'resposta': response['message']['content'],
                    'confianca': len(response['message']['content'])  # proxy simples
                }
            except:
                return None

        # Consulta paralela
        with ThreadPoolExecutor(max_workers=3) as executor:
            resultados = list(executor.map(query_modelo, modelos))

        resultados = [r for r in resultados if r]

        if peso_consenso:
            # Análise de consenso/diversidade
            return analise_respostas(resultados)
        else:
            return resultados

    return consulta_quorum

def analise_respostas(resultados):
    # Lógica pra sintetizar ou escolher melhor resposta
