#pragma once

#include <cstdint>
#include <string>
#include <vector>
#include <optional>
#include <chrono>

namespace fazai {

/// Request for inference
struct InferenceRequest {
    std::string input;
    std::optional<int32_t> max_tokens;
    std::optional<float> temperature;
    std::optional<float> top_p;
    std::optional<int32_t> top_k;
    std::optional<std::string> session_id;
    std::vector<std::string> stop_sequences;
};

/// Response from inference
struct InferenceResponse {
    std::string status;
    std::string result;
    std::string origin = "local";
    std::string session_id;
    double inference_time_ms = 0.0;
    int32_t tokens_generated = 0;
};

/// Streaming event types
enum class EventType {
    SESSION,
    REASONING,
    TOKEN,
    RESULT,
    ERROR,
    METRICS
};

/// Base streaming event
struct StreamEvent {
    EventType type;
    std::string timestamp;

    virtual ~StreamEvent() = default;
    virtual std::string to_json() const = 0;
};

/// Session event
struct SessionEvent : StreamEvent {
    std::string session_id;
    std::string to_json() const override;
};

/// Token event
struct TokenEvent : StreamEvent {
    std::string token;
    int32_t token_id;
    std::string to_json() const override;
};

/// Result event
struct ResultEvent : StreamEvent {
    std::string status;
    std::string content;
    std::string origin;
    std::string to_json() const override;
};

/// Error event
struct ErrorEvent : StreamEvent {
    std::string error;
    std::string code;
    std::string to_json() const override;
};

/// Worker statistics
struct WorkerStats {
    bool model_loaded = false;
    std::string model_path;
    double load_time_seconds = 0.0;
    int32_t n_ctx = 0;
    int32_t n_gpu_layers = 0;
    int64_t total_requests = 0;
    int64_t successful_requests = 0;
