enum class LogLevel { DEBUG, INFO, WARN, ERROR };

class Logger {
public:
    static void init(LogLevel level);
    static void log(LogLevel level, const std::string& message);

    template<typename... Args>
    static void debug(Args&&... args) { log_impl(LogLevel::DEBUG, std::forward<Args>(args)...); }

    template<typename... Args>
    static void info(Args&&... args) { log_impl(LogLevel::INFO, std::forward<Args>(args)...); }

    template<typename... Args>
    static void warn(Args&&... args) { log_impl(LogLevel::WARN, std::forward<Args>(args)...); }

    template<typename... Args>
    static void error(Args&&... args) { log_impl(LogLevel::ERROR, std::forward<Args>(args)...); }

private:
    template<typename... Args>
    static void log_impl(LogLevel level, Args&&... args) {
        std::ostringstream oss;
        (oss << ... << args);
        log(level, oss.str());
    }
};

