WorkerConfig WorkerConfig::from_env() {
    WorkerConfig config;
    config.model_path = get_env("GEMMA_MODEL_PATH", "/opt/fazai/models/gemma/gemma-3-270m-it-qat-Q4_0.gguf");
    config.n_ctx = std::stoi(get_env("GEMMA_N_CTX", "8192"));

    auto threads_env = get_env("GEMMA_N_THREADS", "0");
    config.n_threads = std::stoi(threads_env);
    if (config.n_threads == 0) {
        config.n_threads = std::max(1u, std::thread::hardware_concurrency());
    }

    config.n_gpu_layers = std::stoi(get_env("GEMMA_N_GPU_LAYERS", "0"));
    config.verbose = get_env("GEMMA_VERBOSE", "false") == "true";
    config.max_tokens = std::stoi(get_env("GEMMA_MAX_TOKENS", "512"));
    config.temperature = std::stof(get_env("GEMMA_TEMPERATURE", "0.8"));

    config.top_k = std::stoi(get_env("GEMMA_TOP_K", "40"));
    config.top_p = std::stof(get_env("GEMMA_TOP_P", "0.95"));
    config.min_p = std::stof(get_env("GEMMA_MIN_P", "0.05"));
    config.seed = std::stoi(get_env("GEMMA_SEED", "-1"));
    return config;
}

GemmaWorker::GemmaWorker(const WorkerConfig& config) : config_(config) {
    Logger::info("Initializing GemmaWorker with model: ", config.model_path);
    load_model();
}

GemmaWorker::~GemmaWorker() {
    if (model_) {
        Logger::info("Unloading model");
        llama_model_free(model_);
    }
}

void GemmaWorker::load_model() {
    auto start = std::chrono::high_resolution_clock::now();

    llama_log_set([](ggml_log_level level, const char* text, void*) {
        if (level >= GGML_LOG_LEVEL_WARN) {
            Logger::warn(text);
        }
    }, nullptr);

    ggml_backend_load_all();

    llama_model_params mparams = llama_model_default_params();
    mparams.n_gpu_layers = config_.n_gpu_layers;
    mparams.use_mmap = config_.use_mmap;


    model_ = llama_model_load_from_file(config_.model_path.c_str(), mparams);
    if (!model_) {
        throw std::runtime_error("Failed to load model: " + config_.model_path);
    }

    vocab_ = llama_model_get_vocab(model_);

    auto end = std::chrono::high_resolution_clock::now();
    load_time_seconds_ = std::chrono::duration<double>(end - start).count();

    Logger::info("Model loaded successfully in ", load_time_seconds_, "s");
}

std::string GemmaWorker::format_chat(const std::string& system, const std::string& user) {
    const char* tmpl = llama_model_chat_template(model_, nullptr);

    std::vector<llama_chat_message> msgs;
    if (!system.empty()) {
        msgs.push_back({"system", system.c_str()});
    }
    msgs.push_back({"user", user.c_str()});

    int needed = llama_chat_apply_template(tmpl, msgs.data(), (int)msgs.size(),
                                           true, nullptr, 0);
    if (needed < 0) {
        throw std::runtime_error("Chat template formatting failed");
    }

    std::string out;
    out.resize(needed);
    llama_chat_apply_template(tmpl, msgs.data(), (int)msgs.size(),
                              true, out.data(), (int)out.size());
    return out;
}

std::vector<llama_token> GemmaWorker::tokenize(const std::string& text, bool add_bos) {
    const int n = -llama_tokenize(vocab_, text.c_str(), (int)text.size(), nullptr, 0, add_bos, true);
    if (n <= 0) return {};

    std::vector<llama_token> ids(n);
    llama_tokenize(vocab_, text.c_str(), (int)text.size(), ids.data(), (int)ids.size(), add_bos, true);
    return ids;
}

InferenceResponse GemmaWorker::infer(const InferenceRequest& request) {
    return infer_stream(request, nullptr);
}

InferenceResponse GemmaWorker::infer_stream(const InferenceRequest& request, TokenCallback callback) {
    auto start = std::chrono::high_resolution_clock::now();

    Metrics::instance().increment_requests();
    total_requests_++;

    try {
        std::string formatted = format_chat("You are a helpful assistant", request.input);
        auto tokens = tokenize(formatted, true);

        llama_context_params cparams = llama_context_default_params();
        cparams.n_ctx = config_.n_ctx;
        cparams.n_threads = config_.n_threads;
        cparams.n_threads_batch = config_.n_threads;

        llama_context* ctx = llama_init_from_model(model_, cparams);
        if (!ctx) {
            throw std::runtime_error("Failed to create context");
        }

        llama_batch batch = llama_batch_get_one(tokens.data(), (int)tokens.size());

        llama_sampler* smpl = llama_sampler_chain_init(llama_sampler_chain_default_params());
        llama_sampler_chain_add(smpl, llama_sampler_init_top_k(request.top_k.value_or(config_.top_k)));
        llama_sampler_chain_add(smpl, llama_sampler_init_top_p(request.top_p.value_or(config_.top_p), 1));
        llama_sampler_chain_add(smpl, llama_sampler_init_min_p(config_.min_p, 1));

        llama_sampler_chain_add(smpl, llama_sampler_init_temp(request.temperature.value_or(config_.temperature)));
        llama_sampler_chain_add(smpl, llama_sampler_init_dist(config_.seed));

        std::string result;
        int generated = 0;
        int max_tokens = request.max_tokens.value_or(config_.max_tokens);

        while (true) {
            if (llama_decode(ctx, batch) != 0) break;

            llama_token tok = llama_sampler_sample(smpl, ctx, -1);
            if (llama_vocab_is_eog(vocab_, tok)) break;

            char buf[256];
            int n = llama_token_to_piece(vocab_, tok, buf, sizeof(buf), 0, true);
            if (n > 0) {
                std::string token_str(buf, n);
                result += token_str;

                if (callback) {
                    callback(token_str, tok);
                }
            }

            batch = llama_batch_get_one(&tok, 1);
            if (++generated >= max_tokens) break;
        }

        llama_sampler_free(smpl);
        llama_free(ctx);

        auto end = std::chrono::high_resolution_clock::now();
        double inference_ms = std::chrono::duration<double, std::milli>(end - start).count();

        Metrics::instance().increment_success();
        Metrics::instance().add_inference_time(inference_ms);
        successful_requests_++;
        total_inference_time_ms_ += inference_ms;

        InferenceResponse response;
        response.status = "success";
        response.result = result;
        response.session_id = request.session_id.value_or("default");
        response.inference_time_ms = inference_ms;
        response.tokens_generated = generated;

        return response;

    } catch (const std::exception& e) {
        Metrics::instance().increment_failures();
        failed_requests_++;
        throw;
    }
}

WorkerStats GemmaWorker::get_stats() const {
    WorkerStats stats;
    stats.model_loaded = model_ != nullptr;
    stats.model_path = config_.model_path;
    stats.load_time_seconds = load_time_seconds_;
    stats.n_ctx = config_.n_ctx;
    stats.n_gpu_layers = config_.n_gpu_layers;
    stats.total_requests = total_requests_;
    stats.successful_requests = successful_requests_;
    stats.failed_requests = failed_requests_;
    stats.avg_inference_time_ms = total_requests_ > 0 ? 
        total_inference_time_ms_ / total_requests_ : 0.0;
    return stats;
}

