using json = nlohmann::json;

StreamingServer::StreamingServer(uint16_t port, std::shared_ptr<GemmaWorker> worker)
    : port_(port), worker_(worker) {

    server_.set_access_channels(websocketpp::log::alevel::none);
    server_.set_error_channels(websocketpp::log::elevel::none);

    server_.init_asio();
    server_.set_reuse_addr(true);

    server_.set_open_handler([this](connection_hdl hdl) { on_open(hdl); });
    server_.set_close_handler([this](connection_hdl hdl) { on_close(hdl); });
    server_.set_message_handler([this](connection_hdl hdl, WebSocketServer::message_ptr msg) {
        on_message(hdl, msg);
    });
}

StreamingServer::~StreamingServer() {
    stop();
}

void StreamingServer::run() {
    Logger::info("WebSocket server listening on port ", port_);
    server_.listen(port_);
    server_.start_accept();
    server_.run();
}

void StreamingServer::stop() {
    server_.stop_listening();
    server_.stop();
    if (server_thread_ && server_thread_->joinable()) {
        server_thread_->join();
    }
}

void StreamingServer::on_open(connection_hdl hdl) {
    Logger::info("WebSocket connection opened");
}

void StreamingServer::on_close(connection_hdl hdl) {
    Logger::info("WebSocket connection closed");
}

void StreamingServer::on_message(connection_hdl hdl, WebSocketServer::message_ptr msg) {
    try {
        auto j = json::parse(msg->get_payload());

        InferenceRequest request;
        request.input = j.at("input").get<std::string>();
        if (j.contains("max_tokens")) request.max_tokens = j["max_tokens"];
        if (j.contains("temperature")) request.temperature = j["temperature"];
        if (j.contains("top_p")) request.top_p = j["top_p"];
        if (j.contains("top_k")) request.top_k = j["top_k"];
        if (j.contains("session_id")) request.session_id = j["session_id"];

        process_request(hdl, request);

    } catch (const std::exception& e) {
        Logger::error("WebSocket message error: ", e.what());

        ErrorEvent err;
        err.type = EventType::ERROR;
        err.error = e.what();
        err.code = "PARSE_ERROR";

        try {
            server_.send(hdl, err.to_json() + "\n", websocketpp::frame::opcode::text);
        } catch (...) {}
    }
}

void StreamingServer::process_request(connection_hdl hdl, const InferenceRequest& request) {
    // Send session event
    SessionEvent session_evt;
    session_evt.type = EventType::SESSION;
    session_evt.session_id = request.session_id.value_or("default");
    server_.send(hdl, session_evt.to_json() + "\n", websocketpp::frame::opcode::text);

    try {
        // Stream inference with token callback
        auto response = worker_->infer_stream(request, [this, hdl](const std::string& token, int32_t token_id) {
            TokenEvent tok_evt;
            tok_evt.type = EventType::TOKEN;
            tok_evt.token = token;
            tok_evt.token_id = token_id;

            try {
                server_.send(hdl, tok_evt.to_json() + "\n", websocketpp::frame::opcode::text);
            } catch (...) {}
        });

        // Send result event
        ResultEvent result_evt;
        result_evt.type = EventType::RESULT;
        result_evt.status = response.status;
        result_evt.content = response.result;
        result_evt.origin = response.origin;
        server_.send(hdl, result_evt.to_json() + "\n", websocketpp::frame::opcode::text);

    } catch (const std::exception& e) {
        Logger::error("Inference error: ", e.what());

        ErrorEvent err;
        err.type = EventType::ERROR;
        err.error = e.what();
        err.code = "INFERENCE_ERROR";
        server_.send(hdl, err.to_json() + "\n", websocketpp::frame::opcode::text);
    }
}

