static std::shared_ptr<fazai::StreamingServer> g_server;

void signal_handler(int signal) {
    fazai::Logger::info("Received signal ", signal, ", shutting down gracefully...");
    if (g_server) {
        g_server->stop();
    }
}

int main(int argc, char** argv) {
    std::string model_path;
    uint16_t port = 8080;

    for (int i = 1; i < argc; ++i) {
        std::string arg(argv[i]);
        if (arg == "--model" && i + 1 < argc) {
            model_path = argv[++i];
        } else if (arg == "--port" && i + 1 < argc) {
            port = static_cast<uint16_t>(std::stoi(argv[++i]));
        } else if (arg == "--help" || arg == "-h") {
            std::cout << "FazAI Gemma Worker v2.0.0\n\n";
            std::cout << "Usage: " << argv[0] << " [options]\n\n";
            std::cout << "Options:\n";
            std::cout << "  --model PATH    Path to GGUF model file\n";
            std::cout << "  --port PORT     WebSocket server port (default: 8080)\n";
            std::cout << "  --help, -h      Show this message\n\n";
            std::cout << "Environment variables:\n";
            std::cout << "  GEMMA_MODEL_PATH, GEMMA_N_CTX, GEMMA_N_THREADS\n";
            std::cout << "  GEMMA_MAX_TOKENS, GEMMA_TEMPERATURE, LOG_LEVEL\n";
            return 0;
        }
    }

    fazai::Config::instance().load_from_env();
    std::string log_level = fazai::Config::instance().get("LOG_LEVEL", "INFO");
    if (log_level == "DEBUG") fazai::Logger::init(fazai::LogLevel::DEBUG);
    else if (log_level == "WARN") fazai::Logger::init(fazai::LogLevel::WARN);
    else if (log_level == "ERROR") fazai::Logger::init(fazai::LogLevel::ERROR);
    else fazai::Logger::init(fazai::LogLevel::INFO);

    fazai::Logger::info("Starting FazAI Gemma Worker v2.0.0");

    if (!model_path.empty()) {
        setenv("GEMMA_MODEL_PATH", model_path.c_str(), 1);
    }

    auto worker_config = fazai::WorkerConfig::from_env();
    fazai::Logger::info("Model: ", worker_config.model_path);
    fazai::Logger::info("Context: ", worker_config.n_ctx);
    fazai::Logger::info("Threads: ", worker_config.n_threads);

    try {
        auto worker = std::make_shared<fazai::GemmaWorker>(worker_config);

        if (!worker->is_ready()) {
            fazai::Logger::error("Failed to load model");
            return 1;
        }

        fazai::Logger::info("Worker ready, starting WebSocket server on port ", port);

        std::signal(SIGINT, signal_handler);
        std::signal(SIGTERM, signal_handler);

        g_server = std::make_shared<fazai::StreamingServer>(port, worker);
        g_server->run();

        fazai::Logger::info("Server stopped");
        return 0;

    } catch (const std::exception& e) {
        fazai::Logger::error("Fatal error: ", e.what());
        return 1;
    }
}

