namespace fazai {

SessionManager::SessionManager(llama_model* model, int32_t n_ctx, int32_t n_threads)
    : model_(model), n_ctx_(n_ctx), n_threads_(n_threads) {}

SessionManager::~SessionManager() {
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& [id, session] : sessions_) {
        if (session->ctx) {
            llama_free(session->ctx);
        }
    }
}

std::shared_ptr<Session> SessionManager::get_or_create(const std::string& session_id) {
    std::lock_guard<std::mutex> lock(mutex_);

    auto it = sessions_.find(session_id);
    if (it != sessions_.end()) {
        it->second->last_used = std::chrono::system_clock::now();
        return it->second;
    }

    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx = n_ctx_;
    cparams.n_threads = n_threads_;
    cparams.n_threads_batch = n_threads_;

    llama_context* ctx = llama_init_from_model(model_, cparams);
    if (!ctx) {
        Logger::error("Failed to create session context");
        return nullptr;
    }

    auto session = std::make_shared<Session>();
    session->id = session_id;
    session->ctx = ctx;
    session->created_at = std::chrono::system_clock::now();
    session->last_used = session->created_at;
    session->total_tokens = 0;

    sessions_[session_id] = session;
    Logger::info("Created new session: ", session_id);

    return session;
}

void SessionManager::destroy(const std::string& session_id) {
    std::lock_guard<std::mutex> lock(mutex_);

    auto it = sessions_.find(session_id);
    if (it != sessions_.end()) {
        if (it->second->ctx) {
            llama_free(it->second->ctx);
        }
        sessions_.erase(it);
        Logger::info("Destroyed session: ", session_id);
    }
}

void SessionManager::cleanup_expired(int timeout_seconds) {
    std::lock_guard<std::mutex> lock(mutex_);

    auto now = std::chrono::system_clock::now();
    auto it = sessions_.begin();

    while (it != sessions_.end()) {
        auto age = std::chrono::duration_cast<std::chrono::seconds>(
            now - it->second->last_used).count();

        if (age > timeout_seconds) {
            Logger::info("Cleaning up expired session: ", it->first);
            if (it->second->ctx) {
                llama_free(it->second->ctx);
            }
            it = sessions_.erase(it);
        } else {
            ++it;
        }
    }
}

size_t SessionManager::active_count() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return sessions_.size();
}

