#include "qdrant_client.hpp"
#include "logger.hpp"
#include <curl/curl.h>
#include <sstream>

namespace fazai {
namespace qdrant {

QdrantClient::QdrantClient(const std::string& url) : base_url_(url) {
    curl_global_init(CURL_GLOBAL_DEFAULT);
}

json QdrantClient::make_request(const std::string& method, 
                                const std::string& path, 
                                const json& body) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        throw std::runtime_error("Failed to init CURL");
    }

    std::string url = base_url_ + path;
    std::string response_data;

    auto write_callback = [](char* ptr, size_t size, size_t nmemb, void* userdata) -> size_t {
        auto* str = static_cast<std::string*>(userdata);
        str->append(ptr, size * nmemb);
        return size * nmemb;
    };

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, +write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response_data);

    struct curl_slist* headers = nullptr;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    if (method == "POST" || method == "PUT") {
        std::string body_str = body.dump();
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body_str.c_str());
    }

    CURLcode res = curl_easy_perform(curl);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        throw std::runtime_error("CURL error: " + std::string(curl_easy_strerror(res)));
    }

    return json::parse(response_data);
}

bool QdrantClient::create_collection(const std::string& name, size_t vector_size) {
    json body = {
        {"vectors", {
            {"size", vector_size},
            {"distance", "Cosine"}
        }}
    };

    try {
        make_request("PUT", "/collections/" + name, body);
        return true;
    } catch (const std::exception& e) {
        Logger::error("Failed to create collection: ", e.what());
        return false;
    }
}

bool QdrantClient::upsert_point(const std::string& collection,
                                const std::string& id,
                                const std::vector<float>& vector,
                                const json& payload) {
    json body = {
        {"points", {{
            {"id", id},
            {"vector", vector},
            {"payload", payload}
        }}}
    };

    try {
        make_request("PUT", "/collections/" + collection + "/points", body);
        return true;
    } catch (const std::exception& e) {
        Logger::error("Failed to upsert point: ", e.what());
        return false;
    }
}

std::vector<SearchResult> QdrantClient::search(const std::string& collection,
                                               const std::vector<float>& query,
                                               size_t limit) {
    json body = {
        {"vector", query},
        {"limit", limit},
        {"with_payload", true},
        {"with_vector", true}
    };

    auto response = make_request("POST", "/collections/" + collection + "/points/search", body);

    std::vector<SearchResult> results;
    for (const auto& item : response["result"]) {
        SearchResult result;
        result.id = item["id"];
        result.score = item["score"];
        result.payload = item["payload"];
        result.vector = item["vector"];
        results.push_back(result);
    }

    return results;
}

}}
