}

bool KnowledgeBase::commit(const KBEntry& entry) {
    auto vector = embed(entry.snippet);

    nlohmann::json payload = {
        {"title", entry.title},
        {"tags", entry.tags},
        {"snippet", entry.snippet},
        {"status", entry.status},
        {"source", entry.source},
        {"os_version", entry.os_version},
        {"service", entry.service},
        {"timestamp", std::time(nullptr)}
    };

    std::string id = entry.title + "_" + std::to_string(std::time(nullptr));
    return client_->upsert_point(collection_, id, vector, payload);
}

std::vector<KBEntry> KnowledgeBase::retrieve(const std::string& query, size_t limit) {
    auto query_vec = embed(query);
    auto results = client_->search(collection_, query_vec, limit);

    std::vector<KBEntry> entries;
    for (const auto& result : results) {
        KBEntry entry;
        entry.title = result.payload["title"];
        entry.tags = result.payload["tags"];
        entry.snippet = result.payload["snippet"];
        entry.status = result.payload["status"];
        entry.source = result.payload["source"];
        entry.os_version = result.payload.value("os_version", "");
        entry.service = result.payload.value("service", "");
        entries.push_back(entry);
    }

    return entries;
}

}
