std::string Agent::build_prompt(const std::string& objective,
                                const std::vector<std::string>& context,
                                const std::vector<Action>& history) {
    std::ostringstream prompt;

    prompt << "# FazAI Agent - Intelligent Automation System\n\n";
    prompt << "## Protocol: ND-JSON Actions (one per iteration)\n\n";
    prompt << "Available actions:\n";
    prompt << "- {\"type\":\"plan\",\"steps\":[...]}\n";
    prompt << "- {\"type\":\"ask\",\"question\":\"...\",\"options\":[...]}\n";
    prompt << "- {\"type\":\"research\",\"queries\":[...]}\n";
    prompt << "- {\"type\":\"shell\",\"command\":\"...\"}\n";
    prompt << "- {\"type\":\"observe\",\"summary\":\"...\"}\n";
    prompt << "- {\"type\":\"commit_kb\",\"title\":\"...\",\"tags\":[...]}\n";
    prompt << "- {\"type\":\"done\",\"result\":\"...\"}\n\n";

    prompt << "## Objective\n" << objective << "\n\n";

    if (!context.empty()) {
        prompt << "## Retrieved Context (KB)\n";
        for (const auto& ctx : context) {
            prompt << "- " << ctx << "\n";
        }
        prompt << "\n";
    }

    if (!history.empty()) {
        prompt << "## Action History\n";
        for (const auto& action : history) {
            prompt << action.data.dump() << "\n";
        }
        prompt << "\n";
    }

    prompt << "## Your Response (JSON line)\n";

    return prompt.str();
}

Action Agent::parse_action(const std::string& json_line) {
    auto j = nlohmann::json::parse(json_line);

    Action action;
    std::string type_str = j["type"];

    if (type_str == "plan") action.type = ActionType::PLAN;
    else if (type_str == "ask") action.type = ActionType::ASK;
    else if (type_str == "research") action.type = ActionType::RESEARCH;
    else if (type_str == "shell") action.type = ActionType::SHELL;
    else if (type_str == "observe") action.type = ActionType::OBSERVE;
    else if (type_str == "commit_kb") action.type = ActionType::COMMIT_KB;
    else if (type_str == "done") action.type = ActionType::DONE;

    action.data = j;
    return action;
}

void Agent::execute_objective(const std::string& objective, ActionCallback callback) {
    Logger::info("Starting agent execution for: ", objective);

    // Retrieve context from KB
    auto kb_entries = kb_->retrieve(objective, 5);
    std::vector<std::string> context;
    for (const auto& entry : kb_entries) {
        context.push_back(entry.title + ": " + entry.snippet);
    }

    std::vector<Action> history;
    int iteration = 0;
    const int max_iterations = 32;

    while (iteration++ < max_iterations) {
        Logger::info("Iteration ", iteration);

        auto prompt = build_prompt(objective, context, history);

        InferenceRequest req;
        req.input = prompt;
        req.max_tokens = 512;
        req.temperature = 0.2f;

        auto response = worker_->infer(req);

        // Parse action from response
        try {
            auto action = parse_action(response.result);
            callback(action);

            history.push_back(action);

            if (action.type == ActionType::DONE) {
                Logger::info("Agent completed objective");
                break;
            }

            // Execute and observe
            execute_action(action);
            auto observation = observe_result(action);

            Action obs_action;
            obs_action.type = ActionType::OBSERVE;
            obs_action.data = {{"summary", observation}};
            history.push_back(obs_action);

        } catch (const std::exception& e) {
            Logger::error("Failed to parse action: ", e.what());
            break;
        }
    }
}

