namespace fazai {

/// Result of an executed action
struct ExecutionResult {
    bool success = false;
    std::string stdout_output;
    std::string stderr_output;
    int exit_code = 0;
    std::string error_message;
    double execution_time_ms = 0.0;

    // Additional context
    std::map<std::string, std::string> metadata;
    std::vector<std::string> files_modified;
    std::vector<std::string> services_affected;
};

/// Observes and analyzes execution results
class Observer {
public:
    Observer() = default;

    /// Observe shell command execution
    std::string observe_shell(const ExecutionResult& result);

    /// Observe file operations
    std::string observe_file_ops(const ExecutionResult& result);

    /// Observe service status changes
    std::string observe_service(const ExecutionResult& result);

    /// Observe test results
    std::string observe_test(const ExecutionResult& result);

    /// Generate diff summary
    std::string observe_diff(
        const std::string& before,
        const std::string& after
    );

    /// Analyze errors and suggest fixes
    std::string analyze_error(const ExecutionResult& result);

    /// Extract metrics from result
    nlohmann::json extract_metrics(const ExecutionResult& result);

private:
    std::string format_observation(
        const std::string& action_type,
        bool success,
        const std::string& summary,
        const nlohmann::json& details = nullptr
    );

    bool is_critical_error(const std::string& error);
    std::vector<std::string> suggest_fixes(const std::string& error);
};

} // namespace fazai

