namespace fazai {

std::string Observer::observe_shell(const ExecutionResult& result) {
    nlohmann::json details = {
        {"exit_code", result.exit_code},
        {"execution_time_ms", result.execution_time_ms},
        {"stdout_lines", std::count(result.stdout_output.begin(), result.stdout_output.end(), '\n')},
        {"stderr_lines", std::count(result.stderr_output.begin(), result.stderr_output.end(), '\n')}
    };

    std::ostringstream summary;

    if (result.success) {
        summary << "Command executed successfully";

        // Extract key info from stdout
        if (!result.stdout_output.empty()) {
            auto lines = split_lines(result.stdout_output);
            if (lines.size() <= 3) {
                summary << ": " << result.stdout_output;
            } else {
                summary << " (" << lines.size() << " lines output)";
                details["stdout_preview"] = lines[0] + "\n" + lines[1] + "\n...";
            }
        }

        // Track modified files
        if (!result.files_modified.empty()) {
            details["files_modified"] = result.files_modified;
            summary << ", modified " << result.files_modified.size() << " file(s)";
        }

        // Track affected services
        if (!result.services_affected.empty()) {
            details["services_affected"] = result.services_affected;
            summary << ", affected " << result.services_affected.size() << " service(s)";
        }

    } else {
        summary << "Command failed with exit code " << result.exit_code;

        if (!result.error_message.empty()) {
            summary << ": " << result.error_message;
        }

        // Add stderr preview
        if (!result.stderr_output.empty()) {
            auto lines = split_lines(result.stderr_output);
            details["stderr_preview"] = lines.size() > 3 
                ? lines[0] + "\n" + lines[1] + "\n..." 
                : result.stderr_output;
        }

        // Suggest fixes for common errors
        auto fixes = suggest_fixes(result.stderr_output);
        if (!fixes.empty()) {
            details["suggested_fixes"] = fixes;
            summary << "\nSuggested fixes: " << fixes[0];
        }
    }

    return format_observation("shell", result.success, summary.str(), details);
}

std::string Observer::observe_file_ops(const ExecutionResult& result) {
    nlohmann::json details;
    std::ostringstream summary;

    if (result.success) {
        summary << "File operations completed";

        // Analyze what changed
        if (!result.files_modified.empty()) {
            details["files"] = result.files_modified;
            summary << ": " << result.files_modified.size() << " file(s) modified";

            // Check for config files
            std::vector<std::string> config_files;
            for (const auto& file : result.files_modified) {
                if (file.find(".conf") != std::string::npos ||
                    file.find("config") != std::string::npos ||
                    file.find(".ini") != std::string::npos) {
                    config_files.push_back(file);
                }
            }

            if (!config_files.empty()) {
                details["config_files_modified"] = config_files;
                summary << " (including " << config_files.size() << " config file(s))";
            }
        }

        // Add metadata
        for (const auto& [key, value] : result.metadata) {
            details["metadata_" + key] = value;
        }

    } else {
        summary << "File operations failed: " << result.error_message;
        details["error"] = result.error_message;
    }

    return format_observation("file_ops", result.success, summary.str(), details);
}

std::string Observer::observe_service(const ExecutionResult& result) {
    nlohmann::json details;
    std::ostringstream summary;

    if (result.success) {
        // Parse systemctl/service status output
        std::regex status_regex(R"(Active:\s+(\w+)\s+\(([^)]+)\))");
        std::smatch match;

        if (std::regex_search(result.stdout_output, match, status_regex)) {
            std::string state = match[1];
            std::string sub_state = match[2];

            details["state"] = state;
            details["sub_state"] = sub_state;

            summary << "Service is " << state;
            if (state == "active") {
                summary << " (" << sub_state << ")";
            }
        } else {
            summary << "Service status retrieved";
        }

        // Extract PID if present
        std::regex pid_regex(R"(Main PID:\s+(\d+))");
        if (std::regex_search(result.stdout_output, match, pid_regex)) {
            details["pid"] = std::stoi(match[1]);
        }

        // Extract memory usage
        std::regex mem_regex(R"(Memory:\s+([\d.]+)([KMG]))");
        if (std::regex_search(result.stdout_output, match, mem_regex)) {
            details["memory"] = match[1].str() + match[2].str();
        }

    } else {
        summary << "Failed to check service status: " << result.error_message;
        details["error"] = result.error_message;
    }

    return format_observation("service", result.success, summary.str(), details);
}

std::string Observer::observe_test(const ExecutionResult& result) {
    nlohmann::json details;
    std::ostringstream summary;

    if (result.success) {
        // Parse test results
        std::regex test_regex(R"((\d+)\s+passed.*?(\d+)\s+failed)");
        std::smatch match;

        if (std::regex_search(result.stdout_output, match, test_regex)) {
            int passed = std::stoi(match[1]);
            int failed = std::stoi(match[2]);

            details["tests_passed"] = passed;
            details["tests_failed"] = failed;
            details["tests_total"] = passed + failed;

            summary << "Tests completed: " << passed << " passed";
            if (failed > 0) {
                summary << ", " << failed << " failed";
            }
        } else {
            summary << "Tests completed successfully";
        }

    } else {
        summary << "Tests failed: " << result.error_message;
        details["error"] = result.error_message;

        // Extract failed test names
        std::regex fail_regex(R"(FAIL:\s+(.+))");
        std::vector<std::string> failed_tests;

        auto begin = std::sregex_iterator(
            result.stderr_output.begin(), 
            result.stderr_output.end(), 
            fail_regex
        );
        auto end = std::sregex_iterator();

        for (auto i = begin; i != end; ++i) {
            failed_tests.push_back((*i)[1]);
        }

        if (!failed_tests.empty()) {
            details["failed_tests"] = failed_tests;
        }
    }

    return format_observation("test", result.success, summary.str(), details);
}

std::string Observer::observe_diff(const std::string& before, const std::string& after) {
    nlohmann::json details;
    std::ostringstream summary;

    auto before_lines = split_lines(before);
    auto after_lines = split_lines(after);

    // Simple diff stats
    int added = 0, removed = 0, modified = 0;

    if (after_lines.size() > before_lines.size()) {
        added = after_lines.size() - before_lines.size();
    } else if (before_lines.size() > after_lines.size()) {
        removed = before_lines.size() - after_lines.size();
    }

    // Count modified lines
    size_t min_lines = std::min(before_lines.size(), after_lines.size());
    for (size_t i = 0; i < min_lines; ++i) {
        if (before_lines[i] != after_lines[i]) {
            modified++;
        }
    }

    details["lines_added"] = added;
    details["lines_removed"] = removed;
    details["lines_modified"] = modified;
    details["total_lines_before"] = before_lines.size();
    details["total_lines_after"] = after_lines.size();

    summary << "Changes detected: ";
    if (added > 0) summary << "+" << added << " ";
    if (removed > 0) summary << "-" << removed << " ";
    if (modified > 0) summary << "~" << modified << " ";
    summary << "lines";

    return format_observation("diff", true, summary.str(), details);
}

std::string Observer::analyze_error(const ExecutionResult& result) {
    nlohmann::json details;
    std::ostringstream summary;

    bool is_critical = is_critical_error(result.error_message);
    details["is_critical"] = is_critical;
    details["exit_code"] = result.exit_code;

    // Categorize error
    std::string error_category = "unknown";
    std::string error_lower = result.error_message;
    std::transform(error_lower.begin(), error_lower.end(), error_lower.begin(), ::tolower);

    if (error_lower.find("permission denied") != std::string::npos) {
        error_category = "permission";
    } else if (error_lower.find("not found") != std::string::npos) {
        error_category = "not_found";
    } else if (error_lower.find("connection") != std::string::npos) {
        error_category = "network";
    } else if (error_lower.find("timeout") != std::string::npos) {
        error_category = "timeout";
    } else if (error_lower.find("syntax") != std::string::npos) {
        error_category = "syntax";
    }

    details["error_category"] = error_category;

    // Get suggested fixes
    auto fixes = suggest_fixes(result.error_message);
    if (!fixes.empty()) {
        details["suggested_fixes"] = fixes;
        summary << "Error analyzed (" << error_category << "). ";
        summary << "Suggested fix: " << fixes[0];
    } else {
        summary << "Error analyzed (" << error_category << "). ";
        summary << "No automatic fix available.";
    }

    return format_observation("error_analysis", false, summary.str(), details);
}

nlohmann::json Observer::extract_metrics(const ExecutionResult& result) {
    nlohmann::json metrics = {
        {"success", result.success},
        {"exit_code", result.exit_code},
        {"execution_time_ms", result.execution_time_ms},
        {"files_modified_count", result.files_modified.size()},
        {"services_affected_count", result.services_affected.size()}
    };

    // Extract numeric metrics from output
    std::regex metric_regex(R"((\w+):\s+([\d.]+)\s*([KMG]?B|ms|%))");
    std::smatch match;

    auto output = result.stdout_output + result.stderr_output;
    auto begin = std::sregex_iterator(output.begin(), output.end(), metric_regex);
    auto end = std::sregex_iterator();

    for (auto i = begin; i != end; ++i) {
        std::string key = (*i)[1];
        std::string value = (*i)[2];
        std::string unit = (*i)[3];
        metrics["extracted_" + key] = value + unit;
    }

    return metrics;
}

std::string Observer::format_observation(
    const std::string& action_type,
    bool success,
    const std::string& summary,
    const nlohmann::json& details
) {
    nlohmann::json observation = {
        {"type", "observe"},
        {"action_type", action_type},
        {"success", success},
        {"summary", summary},
        {"timestamp", std::time(nullptr)}
    };

    if (!details.is_null()) {
        observation["details"] = details;
    }

    return observation.dump();
}

bool Observer::is_critical_error(const std::string& error) {
    std::string error_lower = error;
    std::transform(error_lower.begin(), error_lower.end(), error_lower.begin(), ::tolower);

    std::vector<std::string> critical_patterns = {
        "segmentation fault",
        "core dumped",
        "fatal error",
        "kernel panic",
        "out of memory",
        "disk full",
        "corruption",
        "system failure"
    };

    for (const auto& pattern : critical_patterns) {
        if (error_lower.find(pattern) != std::string::npos) {
            return true;
        }
    }

    return false;
}

std::vector<std::string> Observer::suggest_fixes(const std::string& error) {
    std::vector<std::string> fixes;
    std::string error_lower = error;
    std::transform(error_lower.begin(), error_lower.end(), error_lower.begin(), ::tolower);

    if (error_lower.find("permission denied") != std::string::npos) {
        fixes.push_back("Try running with sudo or check file permissions");
        fixes.push_back("Verify user has appropriate access rights");
    }
    else if (error_lower.find("command not found") != std::string::npos) {
        fixes.push_back("Install the required package");
        fixes.push_back("Check if command is in PATH");
    }
    else if (error_lower.find("connection refused") != std::string::npos) {
        fixes.push_back("Verify service is running");
        fixes.push_back("Check firewall settings");
        fixes.push_back("Confirm correct port number");
    }
    else if (error_lower.find("timeout") != std::string::npos) {
        fixes.push_back("Increase timeout duration");
        fixes.push_back("Check network connectivity");
    }
    else if (error_lower.find("port already in use") != std::string::npos) {
        fixes.push_back("Stop conflicting service");
        fixes.push_back("Use a different port");
    }
    else if (error_lower.find("out of memory") != std::string::npos) {
        fixes.push_back("Increase available RAM");
        fixes.push_back("Reduce memory-intensive operations");
    }

    return fixes;
}

// Helper function
std::vector<std::string> Observer::split_lines(const std::string& text) {
    std::vector<std::string> lines;
    std::istringstream stream(text);
    std::string line;

    while (std::getline(stream, line)) {
        lines.push_back(line);
    }

    return lines;
}

