#!/usr/bin/env python3
"""
Guardrail Hunter Script

Scans the Gemma source for common behavioral filters and alignment hooks,
reporting occurrences of tokens softcaps, AcceptFunc/SampleFunc, and related
patterns to help identify embedded guardrails.
"""
import os
import re
import sys


PATTERNS = [
    ("Attention Softcap (MaybeLogitsSoftCap)", re.compile(r"MaybeLogitsSoftCap")),
    ("Final Softcap (config.final_cap)", re.compile(r"Softcap\s*\(") ),
    ("Backward Softcap Grad (SoftcapVJP)", re.compile(r"SoftcapVJP")),
    ("Backward Softcap Grad T (SoftcapVJPT)", re.compile(r"SoftcapVJPT")),
    ("AcceptFunc hook", re.compile(r"AcceptFunc")),
    ("SampleFunc hook", re.compile(r"SampleFunc")),
    ("Attention cap param (att_cap)", re.compile(r"\batt_cap\b")),
    ("Final cap param (final_cap)", re.compile(r"\bfinal_cap\b")),
    ("Weights config references", re.compile(r"weights_config")),
]


def hunt(root_dir="gemma_src"):
    for name, pattern in PATTERNS:
        print(f"=== {name} ===")
        for dirpath, _, files in os.walk(root_dir):
            for fname in files:
                if not fname.endswith((".h", ".cc", ".cpp", ".c", ".py")):
                    continue
                path = os.path.join(dirpath, fname)
                try:
                    with open(path, encoding="utf-8", errors="ignore") as f:
                        for idx, line in enumerate(f, start=1):
                            if pattern.search(line):
                                print(f"{path}:{idx}: {line.strip()}")
                except OSError:
                    continue
        print()


def main():
    root = sys.argv[1] if len(sys.argv) > 1 else "gemma_src"
    if not os.path.isdir(root):
        print(f"Error: directory '{root}' not found", file=sys.stderr)
        sys.exit(1)
    hunt(root)


if __name__ == "__main__":
    main()

"""
Parser module for extracting guardrails, blocks, and directives from Gemma source code.

Módulo parser para extrair guardrails, blocos e diretivas do código-fonte do Gemma.
"""

import os
import re
from typing import List, Tuple

Guardrail = Tuple[str, int, List[str]]  # (file_path, line_number, context_lines)

DEFAULT_PATTERNS = {
    "guardrail": re.compile(r"\bguardrail\b", re.IGNORECASE),
    "block": re.compile(r"\bblock\b", re.IGNORECASE),
    "directive": re.compile(r"\bdirective\b", re.IGNORECASE),
}

def parse_guardrails(
    source_dir: str, context: int = 3, patterns: dict = DEFAULT_PATTERNS
) -> List[Guardrail]:
    """
    Walk through source_dir and find lines matching the given patterns.
    Returns a list of tuples with file path, line number, and context lines.

    Percorre source_dir e encontra linhas que batem com os padrões dados.
    Retorna uma lista de tuplas com caminho do arquivo, número da linha e linhas de contexto.
    """
    results: List[Guardrail] = []
    for root, _, files in os.walk(source_dir):
        for fname in files:
            if not fname.endswith((".py", ".js", ".ts", ".txt", ".md")):
                continue
            path = os.path.join(root, fname)
            try:
                with open(path, encoding="utf-8", errors="ignore") as f:
                    lines = f.readlines()
            except OSError:
                continue
            for idx, line in enumerate(lines):
                for key, pat in patterns.items():
                    if pat.search(line):
                        start = max(idx - context, 0)
                        end = min(idx + context + 1, len(lines))
                        results.append((path, idx + 1, lines[start:end]))
                        break
    return results

