/**
 * ============================================================================
 * RETRIEVAL HANDLER - Vector Stores & File Search
 * ============================================================================
 * Gerencia operações de recuperação semântica e busca em arquivos
 */

import OpenAI from 'openai';
import type {
  VectorStore,
  VectorStoreFile,
  FileSearchResult,
  CreateVectorStoreParams,
  UploadFilesToStoreParams,
  SearchVectorStoreParams,
  FileSearchQueryParams,
  ListVectorStoresParams,
  DeleteVectorStoreParams
} from './types.js';
import fs from 'fs';
import path from 'path';

export class RetrievalHandler {
  private client: OpenAI;
  private vectorStores: Map<string, VectorStore> = new Map();

  constructor(apiKey: string) {
    this.client = new OpenAI({ apiKey });
    console.log('✅ Retrieval Handler inicializado');
  }

  /**
   * Criar um novo Vector Store
   */
  async createVectorStore(params: CreateVectorStoreParams): Promise<VectorStore> {
    console.log(`📚 Criando vector store: ${params.name}`);

    try {
      const vectorStore = await this.client.beta.vectorStores.create({
        name: params.name,
        file_ids: params.file_ids,
        expires_after: params.expires_after,
        metadata: params.metadata
      });

      const store: VectorStore = {
        id: vectorStore.id,
        name: vectorStore.name,
        file_counts: vectorStore.file_counts,
        status: vectorStore.status,
        usage_bytes: vectorStore.usage_bytes,
        created_at: vectorStore.created_at,
        expires_after: vectorStore.expires_after,
        expires_at: vectorStore.expires_at,
        last_active_at: vectorStore.last_active_at,
        metadata: vectorStore.metadata || {}
      };

      this.vectorStores.set(store.id, store);
      console.log(`✅ Vector store criado: ${store.id}`);

      return store;
    } catch (error: any) {
      console.error(`❌ Erro ao criar vector store:`, error.message);
      throw new Error(`Falha ao criar vector store: ${error.message}`);
    }
  }

  /**
   * Upload de arquivos para um Vector Store
   */
  async uploadFilesToStore(params: UploadFilesToStoreParams): Promise<VectorStoreFile[]> {
    console.log(`📤 Enviando ${params.files.length} arquivo(s) para store ${params.vector_store_id}`);

    const uploadedFiles: VectorStoreFile[] = [];

    try {
      for (const fileInfo of params.files) {
        // Verificar se arquivo existe
        if (!fs.existsSync(fileInfo.path)) {
          console.error(`❌ Arquivo não encontrado: ${fileInfo.path}`);
          continue;
        }

        // Fazer upload do arquivo
        console.log(`  📄 Enviando: ${path.basename(fileInfo.path)}`);

        const file = await this.client.files.create({
          file: fs.createReadStream(fileInfo.path),
          purpose: fileInfo.purpose || 'assistants'
        });

        // Adicionar ao vector store
        const vectorStoreFile = await this.client.beta.vectorStores.files.create(
          params.vector_store_id,
          {
            file_id: file.id
          }
        );

        uploadedFiles.push({
          id: vectorStoreFile.id,
          object: 'vector_store.file',
          usage_bytes: vectorStoreFile.usage_bytes,
          created_at: vectorStoreFile.created_at,
          vector_store_id: vectorStoreFile.vector_store_id,
          status: vectorStoreFile.status,
          last_error: vectorStoreFile.last_error
        });

        console.log(`  ✅ Arquivo enviado: ${file.id}`);
      }

      console.log(`✅ Upload concluído: ${uploadedFiles.length} arquivo(s)`);
      return uploadedFiles;

    } catch (error: any) {
      console.error(`❌ Erro no upload de arquivos:`, error.message);
      throw new Error(`Falha no upload: ${error.message}`);
    }
  }

  /**
   * Pesquisa semântica em Vector Stores
   */
  async searchVectorStore(params: SearchVectorStoreParams): Promise<FileSearchResult[]> {
    console.log(`🔍 Buscando: "${params.query}" em ${params.vector_store_ids.length} store(s)`);

    try {
      // Criar um assistant temporário para fazer a busca
      const assistant = await this.client.beta.assistants.create({
        name: 'Search Assistant',
        model: 'gpt-4-turbo-preview',
        tools: [{
          type: 'file_search'
        }],
        tool_resources: {
          file_search: {
            vector_store_ids: params.vector_store_ids
          }
        }
      });

      // Criar thread e mensagem
      const thread = await this.client.beta.threads.create();

      await this.client.beta.threads.messages.create(thread.id, {
        role: 'user',
        content: params.query
      });

      // Executar a busca
      const run = await this.client.beta.threads.runs.create(thread.id, {
        assistant_id: assistant.id,
        tools: [{
          type: 'file_search',
          file_search: {
            max_num_results: params.max_num_results,
            ranking_options: params.ranking_options
          }
        }]
      });

      // Aguardar conclusão
      let runStatus = await this.client.beta.threads.runs.retrieve(thread.id, run.id);

      while (runStatus.status === 'in_progress' || runStatus.status === 'queued') {
        await new Promise(resolve => setTimeout(resolve, 1000));
        runStatus = await this.client.beta.threads.runs.retrieve(thread.id, run.id);
      }

      // Obter mensagens com resultados
      const messages = await this.client.beta.threads.messages.list(thread.id);
      const results: FileSearchResult[] = [];

      for (const message of messages.data) {
        if (message.role === 'assistant' && message.content) {
          for (const content of message.content) {
            if (content.type === 'text') {
              // Extrair citações
              const annotations = content.text.annotations || [];

              for (const annotation of annotations) {
                if (annotation.type === 'file_citation') {
                  const citation = annotation.file_citation;

                  results.push({
                    file_id: citation.file_id,
                    filename: citation.quote || 'Unknown',
                    score: 0.0, // API não retorna score diretamente
                    content: [{
                      type: 'text',
                      text: content.text.value
                    }],
                    annotations: [{
                      type: 'file_citation',
                      index: annotation.start_index,
                      file_id: citation.file_id,
                      filename: citation.quote || 'Unknown'
                    }]
                  });
                }
              }
            }
          }
        }
      }

      // Limpar recursos temporários
      await this.client.beta.assistants.del(assistant.id);
      await this.client.beta.threads.del(thread.id);

      console.log(`✅ Encontrados ${results.length} resultado(s)`);
      return results;

    } catch (error: any) {
      console.error(`❌ Erro na busca:`, error.message);
      throw new Error(`Falha na pesquisa: ${error.message}`);
    }
  }

  /**
   * Busca de arquivos com anotações (File Search simples)
   */
  async fileSearchQuery(params: FileSearchQueryParams): Promise<any> {
    console.log(`📋 File Search: "${params.query}"`);

    try {
      // Usa a mesma lógica da busca semântica, mas retorna formato diferente
      const results = await this.searchVectorStore({
        query: params.query,
        vector_store_ids: params.vector_store_ids,
        max_num_results: params.max_num_results
      });

      const response = {
        query: params.query,
        results: results.map(r => ({
          file_id: r.file_id,
          filename: r.filename,
          content: r.content[0]?.text || '',
          citations: params.include_annotations ? r.annotations : undefined
        })),
        total_results: results.length
      };

      console.log(`✅ File Search concluído: ${response.total_results} resultado(s)`);
      return response;

    } catch (error: any) {
      console.error(`❌ Erro no File Search:`, error.message);
      throw new Error(`Falha no File Search: ${error.message}`);
    }
  }

  /**
   * Listar Vector Stores
   */
  async listVectorStores(params: ListVectorStoresParams = {}): Promise<VectorStore[]> {
    console.log(`📚 Listando vector stores...`);

    try {
      const response = await this.client.beta.vectorStores.list({
        limit: params.limit || 20,
        order: params.order || 'desc',
        after: params.after,
        before: params.before
      });

      const stores: VectorStore[] = response.data.map(vs => ({
        id: vs.id,
        name: vs.name,
        file_counts: vs.file_counts,
        status: vs.status,
        usage_bytes: vs.usage_bytes,
        created_at: vs.created_at,
        expires_after: vs.expires_after,
        expires_at: vs.expires_at,
        last_active_at: vs.last_active_at,
        metadata: vs.metadata || {}
      }));

      // Atualizar cache local
      stores.forEach(store => this.vectorStores.set(store.id, store));

      console.log(`✅ ${stores.length} vector store(s) encontrado(s)`);
      return stores;

    } catch (error: any) {
      console.error(`❌ Erro ao listar vector stores:`, error.message);
      throw new Error(`Falha ao listar: ${error.message}`);
    }
  }

  /**
   * Deletar Vector Store
   */
  async deleteVectorStore(params: DeleteVectorStoreParams): Promise<{ success: boolean; message: string }> {
    console.log(`🗑️  Deletando vector store: ${params.vector_store_id}`);

    try {
      await this.client.beta.vectorStores.del(params.vector_store_id);

      this.vectorStores.delete(params.vector_store_id);

      console.log(`✅ Vector store deletado com sucesso`);
      return {
        success: true,
        message: `Vector store ${params.vector_store_id} deletado`
      };

    } catch (error: any) {
      console.error(`❌ Erro ao deletar vector store:`, error.message);
      throw new Error(`Falha ao deletar: ${error.message}`);
    }
  }

  /**
   * Obter informações de um Vector Store
   */
  async getVectorStore(storeId: string): Promise<VectorStore | null> {
    try {
      const vs = await this.client.beta.vectorStores.retrieve(storeId);

      const store: VectorStore = {
        id: vs.id,
        name: vs.name,
        file_counts: vs.file_counts,
        status: vs.status,
        usage_bytes: vs.usage_bytes,
        created_at: vs.created_at,
        expires_after: vs.expires_after,
        expires_at: vs.expires_at,
        last_active_at: vs.last_active_at,
        metadata: vs.metadata || {}
      };

      this.vectorStores.set(store.id, store);
      return store;

    } catch (error: any) {
      console.error(`❌ Erro ao obter vector store:`, error.message);
      return null;
    }
  }
}

