/**
 * ============================================================================
 * HTTP/SSE SERVER - Servidor MCP via HTTP
 * ============================================================================
 * Expõe o MCP server via Server-Sent Events para ChatGPT Windows app
 */

import express from 'express';
import cors from 'cors';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { ListToolsRequestSchema, CallToolRequestSchema } from '@modelcontextprotocol/sdk/types.js';
import { CUAHandler } from './cua-handler.js';
import { RetrievalHandler } from './retrieval-handler.js';
import { validateSafetyChecks } from './safety-checks.js';
import type { HTTPServerConfig, SSEMessage } from './types.js';

export class HTTPMCPServer {
  private app: express.Application;
  private server: Server;
  private cuaHandler: CUAHandler;
  private retrievalHandler: RetrievalHandler;
  private config: HTTPServerConfig;
  private clients: Map<string, express.Response> = new Map();

  constructor(apiKey: string, config?: Partial<HTTPServerConfig>) {
    this.config = {
      port: config?.port || 3000,
      host: config?.host || 'localhost',
      cors: {
        enabled: config?.cors?.enabled ?? true,
        origins: config?.cors?.origins || ['*']
      }
    };

    this.app = express();
    this.cuaHandler = new CUAHandler(apiKey);
    this.retrievalHandler = new RetrievalHandler(apiKey);
    this.server = new Server(
      {
        name: 'openai-mcp-complete',
        version: '1.0.0',
      },
      {
        capabilities: {
          tools: {},
        },
      }
    );

    this.setupExpress();
    this.setupMCPHandlers();
  }

  /**
   * Configurar Express e middlewares
   */
  private setupExpress(): void {
    // CORS
    if (this.config.cors.enabled) {
      this.app.use(cors({
        origin: this.config.cors.origins,
        methods: ['GET', 'POST', 'OPTIONS'],
        allowedHeaders: ['Content-Type', 'Accept'],
        credentials: true
      }));
    }

    // JSON parser
    this.app.use(express.json());

    // Logging middleware
    this.app.use((req, res, next) => {
      console.log(`📨 ${req.method} ${req.path} - ${req.ip}`);
      next();
    });

    // Health check
    this.app.get('/health', (req, res) => {
      res.json({
        status: 'ok',
        server: 'openai-mcp-complete',
        version: '1.0.0',
        timestamp: new Date().toISOString()
      });
    });

    // SSE endpoint - PRINCIPAL!
    this.app.get('/sse', this.handleSSE.bind(this));

    // Tools listing (para debug)
    this.app.get('/tools', async (req, res) => {
      try {
        const tools = await this.listTools();
        res.json(tools);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // Tool execution (POST)
    this.app.post('/tools/:toolName', async (req, res) => {
      try {
        const result = await this.executeTool(req.params.toolName, req.body);
        res.json(result);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });
  }

  /**
   * Handler SSE - Conexão persistente para ChatGPT
   */
  private handleSSE(req: express.Request, res: express.Response): void {
    const clientId = Math.random().toString(36).substring(7);

    console.log(`🔌 Cliente SSE conectado: ${clientId}`);

    // Configurar headers SSE
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no'); // Nginx

    // Salvar cliente
    this.clients.set(clientId, res);

    // Enviar evento de conexão
    this.sendSSE(res, {
      type: 'connected',
      data: {
        clientId,
        server: 'openai-mcp-complete',
        version: '1.0.0'
      }
    });

    // Enviar lista de ferramentas
    this.listTools().then(tools => {
      this.sendSSE(res, {
        type: 'tools',
        data: tools
      });
    });

    // Keepalive a cada 30 segundos
    const keepalive = setInterval(() => {
      this.sendSSE(res, {
        type: 'ping',
        data: { timestamp: Date.now() }
      });
    }, 30000);

    // Cleanup ao desconectar
    req.on('close', () => {
      console.log(`🔌 Cliente SSE desconectado: ${clientId}`);
      clearInterval(keepalive);
      this.clients.delete(clientId);
    });
  }

  /**
   * Enviar mensagem SSE
   */
  private sendSSE(res: express.Response, message: SSEMessage): void {
    const data = JSON.stringify(message);
    res.write(`data: ${data}\n\n`);
  }

  /**
   * Broadcast para todos os clientes SSE
   */
  private broadcast(message: SSEMessage): void {
    this.clients.forEach(res => {
      this.sendSSE(res, message);
    });
  }

  /**
   * Configurar handlers MCP
   */
  private setupMCPHandlers(): void {
    // List Tools
    this.server.setRequestHandler(ListToolsRequestSchema, async () => {
      return {
        tools: [
          // Computer Use Agent Tools
          {
            name: 'start_cua_session',
            description: 'Inicia uma nova sessão do Computer Use Agent para controlar um computador/navegador',
            inputSchema: {
              type: 'object',
              properties: {
                initialPrompt: { type: 'string', description: 'Prompt inicial descrevendo a tarefa' },
                environment: { 
                  type: 'string', 
                  enum: ['browser', 'mac', 'windows', 'ubuntu'],
                  default: 'browser' 
                },
                displayWidth: { type: 'number', default: 1024 },
                displayHeight: { type: 'number', default: 768 },
                includeScreenshot: { type: 'boolean', default: false }
              },
              required: ['initialPrompt']
            }
          },
          {
            name: 'execute_cua_action',
            description: 'Executa a próxima ação em uma sessão CUA ativa',
            inputSchema: {
              type: 'object',
              properties: {
                sessionId: { type: 'string', description: 'ID da sessão CUA' },
                acknowledgedSafetyChecks: {
                  type: 'array',
                  description: 'Verificações de segurança reconhecidas',
                  items: { type: 'object' }
                }
              },
              required: ['sessionId']
            }
          },
          {
            name: 'get_cua_session',
            description: 'Obtém informações sobre uma sessão CUA',
            inputSchema: {
              type: 'object',
              properties: {
                sessionId: { type: 'string' }
              },
              required: ['sessionId']
            }
          },
          {
            name: 'stop_cua_session',
            description: 'Encerra uma sessão CUA',
            inputSchema: {
              type: 'object',
              properties: {
                sessionId: { type: 'string' }
              },
              required: ['sessionId']
            }
          },

          // Retrieval Tools
          {
            name: 'create_vector_store',
            description: 'Cria um novo Vector Store para armazenar e pesquisar arquivos',
            inputSchema: {
              type: 'object',
              properties: {
                name: { type: 'string', description: 'Nome do vector store' },
                file_ids: { 
                  type: 'array', 
                  items: { type: 'string' },
                  description: 'IDs de arquivos para adicionar' 
                },
                expires_after: {
                  type: 'object',
                  properties: {
                    anchor: { type: 'string', enum: ['last_active_at'] },
                    days: { type: 'number' }
                  }
                },
                metadata: { type: 'object', description: 'Metadados personalizados' }
              },
              required: ['name']
            }
          },
          {
            name: 'upload_files_to_store',
            description: 'Faz upload de arquivos para um Vector Store',
            inputSchema: {
              type: 'object',
              properties: {
                vector_store_id: { type: 'string', description: 'ID do vector store' },
                files: {
                  type: 'array',
                  items: {
                    type: 'object',
                    properties: {
                      path: { type: 'string', description: 'Caminho do arquivo' },
                      purpose: { type: 'string', default: 'assistants' }
                    },
                    required: ['path']
                  }
                }
              },
              required: ['vector_store_id', 'files']
            }
          },
          {
            name: 'search_vector_store',
            description: 'Realiza pesquisa semântica em Vector Stores',
            inputSchema: {
              type: 'object',
              properties: {
                query: { type: 'string', description: 'Consulta de pesquisa' },
                vector_store_ids: {
                  type: 'array',
                  items: { type: 'string' },
                  description: 'IDs dos vector stores para pesquisar'
                },
                max_num_results: { type: 'number', default: 10 },
                ranking_options: {
                  type: 'object',
                  properties: {
                    ranker: { type: 'string', enum: ['auto', 'default-2024-08-21'] },
                    score_threshold: { type: 'number' }
                  }
                }
              },
              required: ['query', 'vector_store_ids']
            }
          },
          {
            name: 'file_search_query',
            description: 'Busca arquivos com citações e anotações',
            inputSchema: {
              type: 'object',
              properties: {
                query: { type: 'string' },
                vector_store_ids: { type: 'array', items: { type: 'string' } },
                include_annotations: { type: 'boolean', default: true },
                max_num_results: { type: 'number', default: 10 }
              },
              required: ['query', 'vector_store_ids']
            }
          },
          {
            name: 'list_vector_stores',
            description: 'Lista todos os Vector Stores disponíveis',
            inputSchema: {
              type: 'object',
              properties: {
                limit: { type: 'number', default: 20 },
                order: { type: 'string', enum: ['asc', 'desc'], default: 'desc' },
                after: { type: 'string' },
                before: { type: 'string' }
              }
            }
          },
          {
            name: 'delete_vector_store',
            description: 'Deleta um Vector Store',
            inputSchema: {
              type: 'object',
              properties: {
                vector_store_id: { type: 'string' }
              },
              required: ['vector_store_id']
            }
          }
        ]
      };
    });

    // Call Tool
    this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
      const { name, arguments: args } = request.params;

      console.log(`🔧 Executando ferramenta: ${name}`);

      try {
        let result: any;

        // Computer Use Agent Tools
        switch (name) {
          case 'start_cua_session':
            result = await this.cuaHandler.startSession(args as any);
            break;

          case 'execute_cua_action':
            result = await this.cuaHandler.executeAction(args as any);
            break;

          case 'get_cua_session':
            result = await this.cuaHandler.getSession(args as any);
            break;

          case 'stop_cua_session':
            result = await this.cuaHandler.stopSession(args as any);
            break;

          // Retrieval Tools
          case 'create_vector_store':
            result = await this.retrievalHandler.createVectorStore(args as any);
            break;

          case 'upload_files_to_store':
            result = await this.retrievalHandler.uploadFilesToStore(args as any);
            break;

          case 'search_vector_store':
            result = await this.retrievalHandler.searchVectorStore(args as any);
            break;

          case 'file_search_query':
            result = await this.retrievalHandler.fileSearchQuery(args as any);
            break;

          case 'list_vector_stores':
            result = await this.retrievalHandler.listVectorStores(args as any);
            break;

          case 'delete_vector_store':
            result = await this.retrievalHandler.deleteVectorStore(args as any);
            break;

          default:
            throw new Error(`Ferramenta desconhecida: ${name}`);
        }

        console.log(`✅ Ferramenta executada com sucesso: ${name}`);

        // Broadcast resultado para clientes SSE
        this.broadcast({
          type: 'result',
          data: {
            tool: name,
            result,
            timestamp: Date.now()
          }
        });

        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(result, null, 2)
            }
          ]
        };

      } catch (error: any) {
        console.error(`❌ Erro ao executar ${name}:`, error.message);

        // Broadcast erro
        this.broadcast({
          type: 'error',
          data: {
            tool: name,
            error: error.message,
            timestamp: Date.now()
          }
        });

        return {
          content: [
            {
              type: 'text',
              text: `Erro: ${error.message}`
            }
          ],
          isError: true
        };
      }
    });
  }

  /**
   * Listar ferramentas (método auxiliar)
   */
  private async listTools(): Promise<any> {
    const response = await this.server.request(
      { method: 'tools/list' },
      ListToolsRequestSchema
    );
    return response;
  }

  /**
   * Executar ferramenta (método auxiliar)
   */
  private async executeTool(name: string, args: any): Promise<any> {
    const response = await this.server.request(
      {
        method: 'tools/call',
        params: { name, arguments: args }
      },
      CallToolRequestSchema
    );
    return response;
  }

  /**
   * Iniciar servidor HTTP
   */
  start(): void {
    this.app.listen(this.config.port, this.config.host, () => {
      console.log('');
      console.log('🌐 ============================================');
      console.log('🚀 HTTP/SSE MCP Server RODANDO!');
      console.log('🌐 ============================================');
      console.log('');
      console.log(`📍 URL para ChatGPT: http://${this.config.host}:${this.config.port}/sse`);
      console.log(`❤️  Health Check:    http://${this.config.host}:${this.config.port}/health`);
      console.log(`🔧 Tools List:       http://${this.config.host}:${this.config.port}/tools`);
      console.log('');
      console.log('✅ Ferramentas disponíveis:');
      console.log('   - Computer Use Agent (4 tools)');
      console.log('   - Retrieval/Vector Stores (6 tools)');
      console.log('');
      console.log('💡 Cole esta URL no ChatGPT Windows:');
      console.log(`   http://${this.config.host}:${this.config.port}/sse`);
      console.log('');
    });
  }
}

// ============================================================================
// EXECUÇÃO STANDALONE
// ============================================================================

if (import.meta.url === `file://${process.argv[1]}`) {
  const apiKey = process.env.OPENAI_API_KEY;

  if (!apiKey) {
    console.error('❌ ERRO: OPENAI_API_KEY não está configurada!');
    console.error('Configure com: set OPENAI_API_KEY=sua-chave-aqui');
    process.exit(1);
  }

  const port = parseInt(process.env.HTTP_PORT || '3000');
  const host = process.env.HTTP_HOST || 'localhost';

  const server = new HTTPMCPServer(apiKey, { port, host });
  server.start();
}

