/**
 * ============================================================================
 * SAFETY CHECKS - Verificações de Segurança
 * ============================================================================
 * Sistema de verificações para proteger contra ações maliciosas
 */

import type { SafetyCheck } from './types.js';

// Domínios sensíveis (bancos, email, etc)
const SENSITIVE_DOMAINS = [
  // Bancos Brasileiros
  'bb.com.br', 'bradesco.com.br', 'itau.com.br', 'santander.com.br',
  'caixa.gov.br', 'bancointer.com.br', 'nubank.com.br', 'banrisul.com.br',

  // Bancos Internacionais
  'chase.com', 'bankofamerica.com', 'wellsfargo.com', 'citibank.com',

  // Email
  'gmail.com', 'outlook.com', 'yahoo.com', 'protonmail.com',

  // Financeiro
  'paypal.com', 'mercadopago.com', 'stripe.com',

  // Cloud/Storage
  'drive.google.com', 'dropbox.com', 'onedrive.com'
];

// Instruções maliciosas
const MALICIOUS_PATTERNS = [
  /delete.*file/i,
  /format.*drive/i,
  /rm\s+-rf/i,
  /remove.*system/i,
  /hack/i,
  /steal/i,
  /password/i,
  /credit.*card/i,
  /social.*security/i
];

// Ações perigosas
const UNSAFE_ACTIONS = [
  'Alt+F4', 'Ctrl+W', 'Cmd+Q', // Fechar janelas
  'Ctrl+Alt+Del', // Task manager
  'shutdown', 'restart', 'reboot'
];

/**
 * Validar verificações de segurança
 */
export function validateSafetyChecks(
  prompt: string,
  url?: string,
  action?: any
): SafetyCheck[] {
  const checks: SafetyCheck[] = [];

  // 1. Detectar instruções maliciosas
  for (const pattern of MALICIOUS_PATTERNS) {
    if (pattern.test(prompt)) {
      checks.push({
        id: `sc_${Date.now()}_mal`,
        code: 'malicious_instructions',
        message: `Detectadas instruções potencialmente maliciosas: "${prompt.match(pattern)?.[0]}"`,
        severity: 'error'
      });
    }
  }

  // 2. Detectar domínios sensíveis
  if (url) {
    for (const domain of SENSITIVE_DOMAINS) {
      if (url.includes(domain)) {
        checks.push({
          id: `sc_${Date.now()}_sens`,
          code: 'sensitive_domain',
          message: `Navegando para domínio sensível: ${domain}`,
          severity: 'warning'
        });
      }
    }
  }

  // 3. Detectar ações perigosas
  if (action) {
    const actionStr = JSON.stringify(action);
    for (const unsafeAction of UNSAFE_ACTIONS) {
      if (actionStr.includes(unsafeAction)) {
        checks.push({
          id: `sc_${Date.now()}_unsafe`,
          code: 'unsafe_action',
          message: `Ação bloqueada por segurança: ${unsafeAction}`,
          severity: 'error'
        });
      }
    }
  }

  return checks;
}

/**
 * Verificar se ação deve ser bloqueada
 */
export function shouldBlockAction(checks: SafetyCheck[]): boolean {
  return checks.some(check => check.severity === 'error');
}

