/**
 * ============================================================================
 * CUA HANDLER - Computer Use Agent
 * ============================================================================
 * Gerencia sessões e ações do Computer Use Agent
 */

import OpenAI from 'openai';
import { chromium, Browser, Page } from 'playwright';
import type {
  CUASession,
  CUAAction,
  SafetyCheck,
  StartCUASessionParams,
  ExecuteCUAActionParams,
  GetCUASessionParams,
  StopCUASessionParams
} from './types.js';
import { validateSafetyChecks, shouldBlockAction } from './safety-checks.js';

export class CUAHandler {
  private client: OpenAI;
  private sessions: Map<string, CUASession> = new Map();

  constructor(apiKey: string) {
    this.client = new OpenAI({ apiKey });
    console.log('✅ CUA Handler inicializado');
  }

  /**
   * Iniciar nova sessão CUA
   */
  async startSession(params: StartCUASessionParams): Promise<any> {
    console.log(`🚀 Iniciando sessão CUA: ${params.initialPrompt}`);

    // Gerar ID único
    const sessionId = `cua_${Date.now()}_${Math.random().toString(36).substring(7)}`;

    // Verificações de segurança
    const safetyChecks = validateSafetyChecks(params.initialPrompt);
    if (shouldBlockAction(safetyChecks)) {
      throw new Error(`Ação bloqueada por segurança: ${safetyChecks[0].message}`);
    }

    try {
      // Inicializar browser se necessário
      let browser: Browser | undefined;
      let page: Page | undefined;

      if (params.environment === 'browser') {
        browser = await chromium.launch({
          headless: false // Mostrar browser
        });

        const context = await browser.newContext({
          viewport: {
            width: params.displayWidth || 1024,
            height: params.displayHeight || 768
          }
        });

        page = await context.newPage();
        console.log('  ✅ Browser inicializado');
      }

      // Criar sessão
      const session: CUASession = {
        id: sessionId,
        environment: params.environment || 'browser',
        displayWidth: params.displayWidth || 1024,
        displayHeight: params.displayHeight || 768,
        browser,
        page,
        createdAt: new Date()
      };

      this.sessions.set(sessionId, session);

      // Chamar OpenAI CUA API
      const response = await this.client.responses.create({
        model: 'computer-use-preview',
        tools: [{
          type: 'computer_use_preview',
          display_width: session.displayWidth,
          display_height: session.displayHeight,
          environment: session.environment
        }],
        input: [{
          role: 'user',
          content: [{
            type: 'input_text',
            text: params.initialPrompt
          }]
        }],
        reasoning: {
          summary: 'concise'
        },
        truncation: 'auto'
      });

      console.log(`✅ Sessão CUA criada: ${sessionId}`);

      return {
        sessionId,
        status: 'created',
        environment: session.environment,
        displayWidth: session.displayWidth,
        displayHeight: session.displayHeight,
        initialResponse: response.output,
        safetyChecks
      };

    } catch (error: any) {
      console.error(`❌ Erro ao iniciar sessão:`, error.message);
      throw new Error(`Falha ao iniciar CUA: ${error.message}`);
    }
  }

  /**
   * Executar ação na sessão
   */
  async executeAction(params: ExecuteCUAActionParams): Promise<any> {
    const session = this.sessions.get(params.sessionId);
    if (!session) {
      throw new Error(`Sessão não encontrada: ${params.sessionId}`);
    }

    console.log(`⚡ Executando ação na sessão: ${params.sessionId}`);

    try {
      // Continuar conversa com CUA
      const response = await this.client.responses.create({
        model: 'computer-use-preview',
        previous_response_id: params.sessionId, // Linking responses
        tools: [{
          type: 'computer_use_preview',
          display_width: session.displayWidth,
          display_height: session.displayHeight,
          environment: session.environment
        }],
        input: [{
          role: 'user',
          content: [{
            type: 'computer_call_output',
            call_id: `call_${Date.now()}`,
            output: {
              type: 'computer_screenshot',
              image_url: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==' // 1x1 pixel
            }
          }]
        }]
      });

      // Executar ação no browser se houver
      if (session.page && response.output) {
        for (const item of response.output) {
          if (item.type === 'computer_call') {
            await this.executeComputerAction(session.page, item.action);
          }
        }
      }

      return {
        sessionId: params.sessionId,
        status: 'executed',
        output: response.output
      };

    } catch (error: any) {
      console.error(`❌ Erro ao executar ação:`, error.message);
      throw new Error(`Falha na execução: ${error.message}`);
    }
  }

  /**
   * Executar ação de computador no Playwright
   */
  private async executeComputerAction(page: Page, action: CUAAction): Promise<void> {
    console.log(`  🖱️  Ação: ${action.type}`);

    switch (action.type) {
      case 'click':
        if (action.x !== undefined && action.y !== undefined) {
          await page.mouse.click(action.x, action.y, {
            button: action.button || 'left'
          });
        }
        break;

      case 'type':
        if (action.text) {
          await page.keyboard.type(action.text);
        }
        break;

      case 'scroll':
        if (action.scroll_x !== undefined || action.scroll_y !== undefined) {
          await page.mouse.wheel(
            action.scroll_x || 0,
            action.scroll_y || 0
          );
        }
        break;

      case 'keypress':
        if (action.keys) {
          for (const key of action.keys) {
            await page.keyboard.press(key);
          }
        }
        break;

      case 'wait':
        if (action.milliseconds) {
          await page.waitForTimeout(action.milliseconds);
        }
        break;

      case 'screenshot':
        await page.screenshot({ path: 'screenshot.png' });
        break;

      default:
        console.log(`  ⚠️  Ação não implementada: ${action.type}`);
    }
  }

  /**
   * Obter informações da sessão
   */
  async getSession(params: GetCUASessionParams): Promise<any> {
    const session = this.sessions.get(params.sessionId);
    if (!session) {
      throw new Error(`Sessão não encontrada: ${params.sessionId}`);
    }

    return {
      sessionId: session.id,
      environment: session.environment,
      displayWidth: session.displayWidth,
      displayHeight: session.displayHeight,
      createdAt: session.createdAt,
      active: true
    };
  }

  /**
   * Encerrar sessão
   */
  async stopSession(params: StopCUASessionParams): Promise<any> {
    const session = this.sessions.get(params.sessionId);
    if (!session) {
      throw new Error(`Sessão não encontrada: ${params.sessionId}`);
    }

    console.log(`🛑 Encerrando sessão: ${params.sessionId}`);

    try {
      // Fechar browser se houver
      if (session.browser) {
        await session.browser.close();
      }

      this.sessions.delete(params.sessionId);

      console.log(`✅ Sessão encerrada: ${params.sessionId}`);

      return {
        sessionId: params.sessionId,
        status: 'stopped',
        message: 'Sessão encerrada com sucesso'
      };

    } catch (error: any) {
      console.error(`❌ Erro ao encerrar sessão:`, error.message);
      throw new Error(`Falha ao encerrar: ${error.message}`);
    }
  }
}

