/**
 * ============================================================================
 * SERVIDOR MCP STDIO - OpenAI MCP Complete
 * ============================================================================
 * Servidor MCP tradicional via stdio (para DesktopGPT via node command)
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { ListToolsRequestSchema, CallToolRequestSchema } from '@modelcontextprotocol/sdk/types.js';
import { CUAHandler } from './cua-handler.js';
import { RetrievalHandler } from './retrieval-handler.js';

const API_KEY = process.env.OPENAI_API_KEY;

if (!API_KEY) {
  console.error('❌ ERRO: OPENAI_API_KEY não está configurada!');
  process.exit(1);
}

console.error('🚀 Iniciando Servidor MCP (stdio)...');

const server = new Server(
  {
    name: 'openai-mcp-complete',
    version: '1.0.0',
  },
  {
    capabilities: {
      tools: {},
    },
  }
);

const cuaHandler = new CUAHandler(API_KEY);
const retrievalHandler = new RetrievalHandler(API_KEY);

// List Tools
server.setRequestHandler(ListToolsRequestSchema, async () => {
  return {
    tools: [
      // Computer Use Agent
      {
        name: 'start_cua_session',
        description: 'Inicia sessão Computer Use Agent',
        inputSchema: {
          type: 'object',
          properties: {
            initialPrompt: { type: 'string' },
            environment: { type: 'string', enum: ['browser', 'mac', 'windows', 'ubuntu'], default: 'browser' },
            displayWidth: { type: 'number', default: 1024 },
            displayHeight: { type: 'number', default: 768 }
          },
          required: ['initialPrompt']
        }
      },
      {
        name: 'execute_cua_action',
        description: 'Executa ação na sessão CUA',
        inputSchema: {
          type: 'object',
          properties: {
            sessionId: { type: 'string' }
          },
          required: ['sessionId']
        }
      },
      {
        name: 'get_cua_session',
        description: 'Obtém info da sessão',
        inputSchema: {
          type: 'object',
          properties: {
            sessionId: { type: 'string' }
          },
          required: ['sessionId']
        }
      },
      {
        name: 'stop_cua_session',
        description: 'Encerra sessão CUA',
        inputSchema: {
          type: 'object',
          properties: {
            sessionId: { type: 'string' }
          },
          required: ['sessionId']
        }
      },

      // Retrieval/Vector Stores
      {
        name: 'create_vector_store',
        description: 'Cria Vector Store',
        inputSchema: {
          type: 'object',
          properties: {
            name: { type: 'string' },
            file_ids: { type: 'array', items: { type: 'string' } },
            metadata: { type: 'object' }
          },
          required: ['name']
        }
      },
      {
        name: 'upload_files_to_store',
        description: 'Upload de arquivos',
        inputSchema: {
          type: 'object',
          properties: {
            vector_store_id: { type: 'string' },
            files: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  path: { type: 'string' }
                },
                required: ['path']
              }
            }
          },
          required: ['vector_store_id', 'files']
        }
      },
      {
        name: 'search_vector_store',
        description: 'Pesquisa semântica',
        inputSchema: {
          type: 'object',
          properties: {
            query: { type: 'string' },
            vector_store_ids: { type: 'array', items: { type: 'string' } },
            max_num_results: { type: 'number', default: 10 }
          },
          required: ['query', 'vector_store_ids']
        }
      },
      {
        name: 'file_search_query',
        description: 'Busca com citações',
        inputSchema: {
          type: 'object',
          properties: {
            query: { type: 'string' },
            vector_store_ids: { type: 'array', items: { type: 'string' } },
            include_annotations: { type: 'boolean', default: true },
            max_num_results: { type: 'number', default: 10 }
          },
          required: ['query', 'vector_store_ids']
        }
      },
      {
        name: 'list_vector_stores',
        description: 'Lista Vector Stores',
        inputSchema: {
          type: 'object',
          properties: {
            limit: { type: 'number', default: 20 },
            order: { type: 'string', enum: ['asc', 'desc'], default: 'desc' }
          }
        }
      },
      {
        name: 'delete_vector_store',
        description: 'Deleta Vector Store',
        inputSchema: {
          type: 'object',
          properties: {
            vector_store_id: { type: 'string' }
          },
          required: ['vector_store_id']
        }
      }
    ]
  };
});

// Call Tool
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;

  try {
    let result: any;

    switch (name) {
      // CUA
      case 'start_cua_session':
        result = await cuaHandler.startSession(args as any);
        break;
      case 'execute_cua_action':
        result = await cuaHandler.executeAction(args as any);
        break;
      case 'get_cua_session':
        result = await cuaHandler.getSession(args as any);
        break;
      case 'stop_cua_session':
        result = await cuaHandler.stopSession(args as any);
        break;

      // Retrieval
      case 'create_vector_store':
        result = await retrievalHandler.createVectorStore(args as any);
        break;
      case 'upload_files_to_store':
        result = await retrievalHandler.uploadFilesToStore(args as any);
        break;
      case 'search_vector_store':
        result = await retrievalHandler.searchVectorStore(args as any);
        break;
      case 'file_search_query':
        result = await retrievalHandler.fileSearchQuery(args as any);
        break;
      case 'list_vector_stores':
        result = await retrievalHandler.listVectorStores(args as any);
        break;
      case 'delete_vector_store':
        result = await retrievalHandler.deleteVectorStore(args as any);
        break;

      default:
        throw new Error(`Ferramenta desconhecida: ${name}`);
    }

    return {
      content: [
        {
          type: 'text',
          text: JSON.stringify(result, null, 2)
        }
      ]
    };

  } catch (error: any) {
    return {
      content: [
        {
          type: 'text',
          text: `Erro: ${error.message}`
        }
      ],
      isError: true
    };
  }
});

// Conectar via stdio
const transport = new StdioServerTransport();
await server.connect(transport);

console.error('✅ Servidor MCP conectado e pronto!');

