/**
 * Pesquisa semântica em Vector Stores
 */
async searchVectorStore(params: SearchVectorStoreParams): Promise<FileSearchResult[]> {
  console.log(`🔍 Buscando: "${params.query}" em ${params.vector_store_ids.length} store(s)`);

  try {
    // Criar um assistant temporário para fazer a busca
    const assistant = await this.client.beta.assistants.create({
      name: 'Search Assistant',
      model: 'gpt-4-turbo-preview',
      tools: [{
        type: 'file_search'
      }],
      tool_resources: {
        file_search: {
          vector_store_ids: params.vector_store_ids
        }
      }
    });

    // Criar thread e mensagem
    const thread = await this.client.beta.threads.create();

    await this.client.beta.threads.messages.create(thread.id, {
      role: 'user',
      content: params.query
    });

    // Executar a busca
    const run = await this.client.beta.threads.runs.create(thread.id, {
      assistant_id: assistant.id,
      tools: [{
        type: 'file_search',
        file_search: {
          max_num_results: params.max_num_results,
          ranking_options: params.ranking_options
        }
      }]
    });

    // Aguardar conclusão
    let runStatus = await this.client.beta.threads.runs.retrieve(thread.id, run.id);

    while (runStatus.status === 'in_progress' || runStatus.status === 'queued') {
      await new Promise(resolve => setTimeout(resolve, 1000));
      runStatus = await this.client.beta.threads.runs.retrieve(thread.id, run.id);
    }

    // Obter mensagens com resultados
    const messages = await this.client.beta.threads.messages.list(thread.id);
    const results: FileSearchResult[] = [];

    for (const message of messages.data) {
      if (message.role === 'assistant' && message.content) {
        for (const content of message.content) {
          if (content.type === 'text') {
            // Extrair citações
            const annotations = content.text.annotations || [];

            for (const annotation of annotations) {
              if (annotation.type === 'file_citation') {
                const citation = annotation.file_citation;

                results.push({
                  file_id: citation.file_id,
                  filename: citation.quote || 'Unknown',
                  score: 0.0, // API não retorna score diretamente
                  content: [{
                    type: 'text',
                    text: content.text.value
                  }],
                  annotations: [{
                    type: 'file_citation',
                    index: annotation.start_index,
                    file_id: citation.file_id,
                    filename: citation.quote || 'Unknown'
                  }]
                });
              }
            }
          }
        }
      }
    }

    // Limpar recursos temporários
    await this.client.beta.assistants.del(assistant.id);
    await this.client.beta.threads.del(thread.id);

    console.log(`✅ Encontrados ${results.length} resultado(s)`);
    return results;

  } catch (error: any) {
    console.error(`❌ Erro na busca:`, error.message);
    throw new Error(`Falha na pesquisa: ${error.message}`);
  }
}

