  /**
   * Busca de arquivos com anotações (File Search simples)
   */
  async fileSearchQuery(params: FileSearchQueryParams): Promise<any> {
    console.log(`📋 File Search: "${params.query}"`);

    try {
      const results = await this.searchVectorStore({
        query: params.query,
        vector_store_ids: params.vector_store_ids,
        max_num_results: params.max_num_results
      });

      const response = {
        query: params.query,
        results: results.map(r => ({
          file_id: r.file_id,
          filename: r.filename,
          content: r.content[0]?.text || '',
          citations: params.include_annotations ? r.annotations : undefined
        })),
        total_results: results.length
      };

      console.log(`✅ File Search concluído: ${response.total_results} resultado(s)`);
      return response;

    } catch (error: any) {
      console.error(`❌ Erro no File Search:`, error.message);
      throw new Error(`Falha no File Search: ${error.message}`);
    }
  }

  /**
   * Listar Vector Stores
   */
  async listVectorStores(params: ListVectorStoresParams = {}): Promise<any[]> {
    console.log(`📚 Listando vector stores...`);

    try {
      // Retornar stores do cache local
      const stores = Array.from(this.vectorStores.values());

      console.log(`✅ ${stores.length} vector store(s) encontrado(s)`);
      return stores;

    } catch (error: any) {
      console.error(`❌ Erro ao listar vector stores:`, error.message);
      throw new Error(`Falha ao listar: ${error.message}`);
    }
  }

  /**
   * Deletar Vector Store
   */
  async deleteVectorStore(params: DeleteVectorStoreParams): Promise<{ success: boolean; message: string }> {
    console.log(`🗑️  Deletando vector store: ${params.vector_store_id}`);

    try {
      this.vectorStores.delete(params.vector_store_id);

      console.log(`✅ Vector store deletado com sucesso`);
      return {
        success: true,
        message: `Vector store ${params.vector_store_id} deletado`
      };

    } catch (error: any) {
      console.error(`❌ Erro ao deletar vector store:`, error.message);
      throw new Error(`Falha ao deletar: ${error.message}`);
    }
  }

  /**
   * Obter informações de um Vector Store
   */
  async getVectorStore(storeId: string): Promise<any | null> {
    try {
      const store = this.vectorStores.get(storeId);
      return store || null;

    } catch (error: any) {
      console.error(`❌ Erro ao obter vector store:`, error.message);
      return null;
    }
  }
}

