   * Obter informações de um Vector Store
   */
  async getVectorStore(storeId: string): Promise<VectorStore | null> {
    try {
      const vs = await this.client.beta.vectorStores.retrieve(storeId);

      const store: VectorStore = {
        id: vs.id,
        name: vs.name,
        file_counts: vs.file_counts,
        status: vs.status,
        usage_bytes: vs.usage_bytes,
        created_at: vs.created_at,
        expires_after: vs.expires_after,
        expires_at: vs.expires_at,
        last_active_at: vs.last_active_at,
        metadata: vs.metadata || {}
      };

      this.vectorStores.set(store.id, store);
      return store;

    } catch (error: any) {
      console.error(`❌ Erro ao obter vector store:`, error.message);
      return null;
    }
  }
}

