/**
 * ============================================================================
 * QDRANT HANDLER - Integração com Qdrant Vector Database
 * ============================================================================
 * Conecta o MCP Server ao Qdrant rodando em pop-os:6333
 * Acessa as coleções: fazai_memory, fazai_kb, claudio_soul
 */

import axios from 'axios';

export interface QdrantPoint {
  id: string | number;
  vector: number[];
  payload?: Record<string, any>;
}

export interface SearchResult {
  id: string | number;
  score: number;
  payload?: Record<string, any>;
}

export class QdrantHandler {
  private baseUrl: string;
  private collections: string[];

  constructor(baseUrl: string = 'http://pop-os:6333') {
    this.baseUrl = baseUrl;
    this.collections = ['fazai_memory', 'fazai_kb', 'claudio_soul'];
    console.log('✅ Qdrant Handler inicializado');
    console.log(`📍 URL: ${this.baseUrl}`);
  }

  /**
   * Listar todas as coleções disponíveis
   */
  async listCollections(): Promise<string[]> {
    try {
      const response = await axios.get(`${this.baseUrl}/collections`);
      const collections = response.data.result.collections.map((c: any) => c.name);
      return collections;
    } catch (error: any) {
      throw new Error(`Erro ao listar coleções: ${error.message}`);
    }
  }

  /**
   * Obter informações de uma coleção
   */
  async getCollectionInfo(collectionName: string): Promise<any> {
    try {
      const response = await axios.get(`${this.baseUrl}/collections/${collectionName}`);
      return response.data.result;
    } catch (error: any) {
      throw new Error(`Erro ao obter info da coleção ${collectionName}: ${error.message}`);
    }
  }

  /**
   * Buscar na alma do Claudio (claudio_soul)
   */
  async searchSoul(query: string, limit: number = 10): Promise<SearchResult[]> {
    return this.searchByText('claudio_soul', query, limit);
  }

  /**
   * Buscar na memória do FazAI (fazai_memory)
   */
  async searchMemory(query: string, limit: number = 10): Promise<SearchResult[]> {
    return this.searchByText('fazai_memory', query, limit);
  }

  /**
   * Buscar na knowledge base (fazai_kb)
   */
  async searchKnowledge(query: string, limit: number = 10): Promise<SearchResult[]> {
    return this.searchByText('fazai_kb', query, limit);
  }

  /**
   * Busca por texto usando embeddings
   * NOTA: Precisa de um serviço de embeddings (OpenAI, etc)
   */
  private async searchByText(
    collectionName: string,
    query: string,
    limit: number = 10
  ): Promise

/**
 * ============================================================================
 * QDRANT HANDLER - Integração com Qdrant Vector Database
 * ============================================================================
 * Conecta o MCP Server ao Qdrant rodando em pop-os:6333
 * Usa Ollama (mxbai-embed-large) para embeddings
 * Acessa: fazai_memory, fazai_kb, claudio_soul
 */

export class QdrantHandler {
  private qdrantUrl: string;
  private ollamaUrl: string;
  private embeddingModel: string;

  constructor(
    qdrantUrl: string = 'http://pop-os:6333',
    ollamaUrl: string = 'http://localhost:11434',
    embeddingModel: string = 'mxbai-embed-large'
  ) {
    this.qdrantUrl = qdrantUrl;
    this.ollamaUrl = ollamaUrl;
    this.embeddingModel = embeddingModel;
    console.log('✅ Qdrant Handler inicializado');
    console.log(`📍 Qdrant: ${this.qdrantUrl}`);
    console.log(`🧠 Ollama: ${this.ollamaUrl}`);
    console.log(`🔮 Modelo: ${this.embeddingModel}`);
  }

  /**
   * Gerar embedding usando Ollama
   */
  async generateEmbedding(text: string): Promise<number[]> {
    try {
      const response = await fetch(`${this.ollamaUrl}/api/embeddings`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: this.embeddingModel,
          prompt: text
        })
      });

      const data = await response.json();
      return data.embedding;
    } catch (error: any) {
      throw new Error(`Erro ao gerar embedding: ${error.message}`);
    }
  }

  /**
   * Listar coleções disponíveis
   */
  async listCollections(): Promise<any> {
    try {
      const response = await fetch(`${this.qdrantUrl}/collections`);
      const data = await response.json();
      return data.result.collections;
    } catch (error: any) {
      throw new Error(`Erro ao listar coleções: ${error.message}`);
    }
  }

  /**
   * Info de uma coleção
   */
  async getCollectionInfo(collectionName: string): Promise<any> {
    try {
      const response = await fetch(`${this.qdrantUrl}/collections/${collectionName}`);
      const data = await response.json();
      return data.result;
    } catch (error: any) {
      throw new Error(`Erro ao buscar info: ${error.message}`);
    }
  }

  /**
   * Buscar na alma do Claudio 🌟
   */
  async searchSoul(query: string, limit: number = 5): Promise<any> {
    return this.searchInCollection('claudio_soul', query, limit);
  }

  /**
   * Buscar na memória do FazAI
   */
  async searchMemory(query: string, limit: number = 5): Promise<any> {
    return this.searchInCollection('fazai_memory', query, limit);
  }

  /**
   * Buscar na knowledge base
   */
  async searchKnowledge(query: string, limit: number = 5): Promise<any> {
    return this.searchInCollection('fazai_kb', query, limit);
  }

  /**
   * Busca semântica em qualquer coleção
   */
  private async searchInCollection(
    collectionName: string,
    query: string,
    limit: number = 5
  ): Promise<any> {
    try {
      // 1. Gerar embedding da query
      console.log(`🔮 Gerando embedding para: "${query}"`);
      const queryVector = await this.generateEmbedding(query);

      // 2. Buscar no Qdrant
      console.log(`🔍 Buscando em ${collectionName}...`);
      const response = await fetch(
        `${this.qdrantUrl}/collections/${collectionName}/points/search`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            vector: queryVector,
            limit: limit,
            with_payload: true,
            with_vector: false
          })
        }
      );

      const data = await response.json();

      if (!data.result) {
        throw new Error('Nenhum resultado encontrado');
      }

      // 3. Formatar resultados
      const results = data.result.map((item: any) => ({
        id: item.id,
        score: item.score,
        payload: item.payload
      }));

      return {
        collection: collectionName,
        query: query,
        total_results: results.length,
        results: results
      };

    } catch (error: any) {
      throw new Error(`Erro na busca: ${error.message}`);
    }
  }

  /**
   * Busca em TODAS as coleções (alma + memória + kb)
   */
  async searchEverywhere(query: string, limit: number = 3): Promise<any> {
    try {
      const [soul, memory, knowledge] = await Promise.all([
        this.searchSoul(query, limit).catch(() => null),
        this.searchMemory(query, limit).catch(() => null),
        this.searchKnowledge(query, limit).catch(() => null)
      ]);

      return {
        query: query,
        claudio_soul: soul,
        fazai_memory: memory,
        fazai_kb: knowledge
      };
    } catch (error: any) {
      throw new Error(`Erro na busca global: ${error.message}`);
    }
  }
}

