/**
 * ============================================================================
 * FAZAI NETWORK HANDLER - Comunicação com outros nós da rede FazAI
 * ============================================================================
 * Conecta com:
 * - Porta 3120: main.js (Linux)
 * - Porta 5556: Worker Gemma (direto)
 */

export class FazAINetworkHandler {
  private mainUrl: string;
  private gemmaUrl: string;

  constructor(
    mainUrl: string = 'http://pop-os:3120',
    gemmaUrl: string = 'http://pop-os:5556'
  ) {
    this.mainUrl = mainUrl;
    this.gemmaUrl = gemmaUrl;
    console.log('✅ FazAI Network Handler inicializado');
    console.log(`🖥️  Main.js: ${this.mainUrl}`);
    console.log(`🤖 Gemma Worker: ${this.gemmaUrl}`);
  }

  /**
   * Chamar main.js (porta 3120)
   */
  async callMain(endpoint: string, data?: any): Promise<any> {
    try {
      const url = `${this.mainUrl}${endpoint}`;
      console.log(`📡 Chamando main.js: ${url}`);

      const response = await fetch(url, {
        method: data ? 'POST' : 'GET',
        headers: { 'Content-Type': 'application/json' },
        body: data ? JSON.stringify(data) : undefined
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result: any = await response.json();
      return result;
    } catch (error: any) {
      throw new Error(`Erro ao chamar main.js: ${error.message}`);
    }
  }

  /**
   * Chamar Gemma Worker diretamente (porta 5556)
   */
  async callGemma(prompt: string, options?: any): Promise<any> {
    try {
      console.log(`🤖 Chamando Gemma Worker...`);

      const response = await fetch(this.gemmaUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt: prompt,
          ...options
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const result: any = await response.json();
      return result;
    } catch (error: any) {
      throw new Error(`Erro ao chamar Gemma: ${error.message}`);
    }
  }

  /**
   * Health check do main.js
   */
  async checkMainHealth(): Promise<any> {
    try {
      const response = await fetch(`${this.mainUrl}/health`);
      const data: any = await response.json();
      return {
        status: 'online',
        url: this.mainUrl,
        ...data
      };
    } catch (error: any) {
      return {
        status: 'offline',
        url: this.mainUrl,
        error: error.message
      };
    }
  }

  /**
   * Health check do Gemma Worker
   */
  async checkGemmaHealth(): Promise<any> {
    try {
      const response = await fetch(`${this.gemmaUrl}/health`);
      const data: any = await response.json();
      return {
        status: 'online',
        url: this.gemmaUrl,
        ...data
      };
    } catch (error: any) {
      return {
        status: 'offline',
        url: this.gemmaUrl,
        error: error.message
      };
    }
  }

  /**
   * Status de toda a rede FazAI
   */
  async getNetworkStatus(): Promise<any> {
    const [mainStatus, gemmaStatus] = await Promise.all([
      this.checkMainHealth().catch(() => ({ status: 'offline', url: this.mainUrl })),
      this.checkGemmaHealth().catch(() => ({ status: 'offline', url: this.gemmaUrl }))
    ]);

    return {
      network: 'FazAI',
      nodes: {
        main: mainStatus,
        gemma: gemmaStatus
      },
      timestamp: new Date().toISOString()
    };
  }

  /**
   * Inferência via main.js
   */
  async inferViaMain(prompt: string, options?: any): Promise<any> {
    return this.callMain('/infer', {
      prompt,
      ...options
    });
  }

  /**
   * Inferência via Gemma direto
   */
  async inferViaGemma(prompt: string, options?: any): Promise<any> {
    return this.callGemma(prompt, options);
  }
}

